      xref_length: Number(source.xref_length || 0) || 0,
      descriptor_count: Number(counts.descriptor_count || counts.xobject_content_stream_count || counts.content_stream_count || 0) || 0,
      drawing_count: Number(counts.drawing_count || 0) || 0,
      text_span_count: Number(counts.text_span_count || 0) || 0,
