      image_resource_count: Number(resources.image_count || 0) || 0,
      font_resource_count: Number(resources.font_count || 0) || 0,
      xobject_resource_count: Number(resources.xobject_count || counts.xobject_count || 0) || 0,
      xobject_content_stream_count: Number(resources.xobject_content_stream_count || counts.xobject_content_stream_count || 0) || 0,
      extgstate_resource_count: Number(resources.extgstate_count || counts.extgstate_count || 0) || 0,
