    if (!object || !manifest) return null;
    const treeSummary = nativePdfDescriptorTreeSummary(nativePdfDescriptorTreeForObject(object));
    const plan = normalizeNativePdfEditPlan(manifest.native_pdf_edit_plan || object.nativePdfEditPlan || object.importMeta?.nativePdfEditPlan || object.importMeta?.native_pdf_edit_plan, object);
    const source = nativePdfSourceForObject(object);
