    const height = clamp(Number(rect.height || rect.h || pageHeight * (Number(ratio.height || ratio.h || 0.18) || 0.18)) || pageHeight * 0.18, 4, pageHeight);
    const x = clamp(Number(rect.x ?? rect.left ?? pageWidth * (Number(ratio.x ?? ratio.left ?? 0.10) || 0.10)) || pageWidth * 0.10, 0, Math.max(0, pageWidth - width));
