      afterXrefLength: Number(payload.mutation?.after_xref_length || 0) || 0,
      beforeContentStreamCount: Array.isArray(payload.mutation?.before_pages?.[0]?.content_xrefs) ? payload.mutation.before_pages[0].content_xrefs.length : 0,
      afterContentStreamCount: Array.isArray(payload.mutation?.after_pages?.[0]?.content_xrefs) ? payload.mutation.after_pages[0].content_xrefs.length : 0,
      pdfObjectStreamWriterAttached: true,
      nativeCompiledPdfOutputAvailable: Boolean(payload.compile?.native_compiled_pdf_output_available ?? true),
      nativeEquivalentPdfOutputAvailable: Boolean(
        payload.compile?.bounded_native_equivalent_object_tree_roundtrip_available
        || payload.compile?.bounded_native_equivalent_resource_roundtrip_available
        || payload.mutation?.native_equivalent_pdf_output_available
      ),
      fullNativeEquivalence: Boolean(visualDiffProof.fullNativeEquivalence),
