      xobjectContentStreamRewriteDescriptorCount: Number(payload.compile?.xobject_content_stream_rewrite_descriptor_count || 0) || 0,
      paintOperatorRunRewriteApplied: Boolean(payload.compile?.paint_operator_run_rewrite_applied || payload.mutation?.paint_operator_run_rewrite_applied),
