      rgbColorOperatorRunRewriteApplied: Boolean(payload.compile?.rgb_color_operator_run_rewrite_applied || payload.mutation?.rgb_color_operator_run_rewrite_applied),
      rgbColorOperatorRewriteDescriptorCount: Number(payload.compile?.rgb_color_operator_rewrite_descriptor_count || 0) || 0,
      strokeWidthOperatorRunRewriteApplied: Boolean(payload.compile?.stroke_width_operator_run_rewrite_applied || payload.mutation?.stroke_width_operator_run_rewrite_applied),
      strokeWidthOperatorRewriteDescriptorCount: Number(payload.compile?.stroke_width_operator_rewrite_descriptor_count || 0) || 0,
      pathGeometryTransformApplied: Boolean(payload.compile?.path_geometry_transform_applied || payload.mutation?.path_geometry_transform_applied),
      pathGeometryTransformDescriptorCount: Number(payload.compile?.path_geometry_transform_descriptor_count || 0) || 0,
