      compiled_count: results.filter((result) => result.status === "ok" && result.dataUrl).length,
      blocked_count: results.filter((result) => result.status === "blocked").length,
      skipped_count: results.filter((result) => result.status === "skipped").length,
      compiler_targets: [...new Set(results.map((result) => result.compilerTarget).filter(Boolean))],
      native_compiled_pdf_output_available: results.some((result) => result.status === "ok" && result.dataUrl),
      native_equivalent_pdf_output_available: results.some((result) => result.status === "ok" && result.nativeEquivalentPdfOutputAvailable),
      visual_diff_gate: {
        schema: "figureStudio.nativePdfVisualDiffExportGate.v1",
        required: true,
        passed_count: results.filter((result) => normalizeNativePdfVisualDiffProof(result, result).passed).length,
        proof_count: results.filter((result) => result.visualDiffProof || result.visual_diff_proof || result.visualEquivalenceProof || result.visual_equivalence_proof).length,
        full_native_equivalence: results.some((result) => normalizeNativePdfVisualDiffProof(result, result).fullNativeEquivalence)
      },
