        appliedDescriptorTypes: result.appliedDescriptorTypes || [],
        resourceGraphMutated: Boolean(result.resourceGraphMutated),
        objectTreeContentStreamRewriteApplied: Boolean(result.objectTreeContentStreamRewriteApplied),
        objectTreeRewriteDescriptorCount: Number(result.objectTreeRewriteDescriptorCount || 0) || 0,
        xobjectContentStreamRewriteApplied: Boolean(result.xobjectContentStreamRewriteApplied),
        xobjectContentStreamRewriteDescriptorCount: Number(result.xobjectContentStreamRewriteDescriptorCount || 0) || 0,
        paintOperatorRunRewriteApplied: Boolean(result.paintOperatorRunRewriteApplied),
        paintOperatorRewriteDescriptorCount: Number(result.paintOperatorRewriteDescriptorCount || 0) || 0,
        rgbColorOperatorRunRewriteApplied: Boolean(result.rgbColorOperatorRunRewriteApplied),
        rgbColorOperatorRewriteDescriptorCount: Number(result.rgbColorOperatorRewriteDescriptorCount || 0) || 0,
        strokeWidthOperatorRunRewriteApplied: Boolean(result.strokeWidthOperatorRunRewriteApplied),
