        clipPathContentStreamRewriteApplied: Boolean(result.clipPathContentStreamRewriteApplied),
        clipPathOperatorRunRewriteApplied: Boolean(result.clipPathOperatorRunRewriteApplied),
        clipPathRewriteDescriptorCount: Number(result.clipPathRewriteDescriptorCount || 0) || 0,
        blendModeResourceRewriteApplied: Boolean(result.blendModeResourceRewriteApplied),
        blendModeResourceRewriteDescriptorCount: Number(result.blendModeResourceRewriteDescriptorCount || 0) || 0,
        alphaResourceRewriteApplied: Boolean(result.alphaResourceRewriteApplied),
        alphaResourceRewriteDescriptorCount: Number(result.alphaResourceRewriteDescriptorCount || 0) || 0,
        softMaskResourceRewriteApplied: Boolean(result.softMaskResourceRewriteApplied),
        softMaskResourceRewriteDescriptorCount: Number(result.softMaskResourceRewriteDescriptorCount || 0) || 0,
        gradientResourceRewriteApplied: Boolean(result.gradientResourceRewriteApplied),
        gradientResourceRewriteDescriptorCount: Number(result.gradientResourceRewriteDescriptorCount || 0) || 0,
        gradientMeshPatternNativeWriteApplied: Boolean(result.gradientMeshPatternNativeWriteApplied),
        gradientMeshPatternNativeWriteDescriptorCount: Number(result.gradientMeshPatternNativeWriteDescriptorCount || 0) || 0,
        shadingFunctionColorRewriteApplied: Boolean(result.shadingFunctionColorRewriteApplied),
        selectedUseGradientCloneRebindApplied: Boolean(result.selectedUseGradientCloneRebindApplied),
        selectedUseGradientCloneRebindDescriptorCount: Number(result.selectedUseGradientCloneRebindDescriptorCount || 0) || 0,
        shadingResourceCloneApplied: Boolean(result.shadingResourceCloneApplied),
        functionResourceCloneApplied: Boolean(result.functionResourceCloneApplied),
        stitchedGradientFunctionRewriteApplied: Boolean(result.stitchedGradientFunctionRewriteApplied),
        gradientFunctionPromoted: Boolean(result.gradientFunctionPromoted),
        gradientFunctionDemoted: Boolean(result.gradientFunctionDemoted),
        gradientStopCountRewriteApplied: Boolean(result.gradientStopCountRewriteApplied),
        gradientGeometryRewriteApplied: Boolean(result.gradientGeometryRewriteApplied),
        shadingBackgroundColorRewriteApplied: Boolean(result.shadingBackgroundColorRewriteApplied),
        patternStreamColorRewriteApplied: Boolean(result.patternStreamColorRewriteApplied),
        robustBooleanGeometryApplied: Boolean(result.robustBooleanGeometryApplied),
        robustBooleanDescriptorCount: Number(result.robustBooleanDescriptorCount || 0) || 0,
        pathAnchorGeometryApplied: Boolean(result.pathAnchorGeometryApplied),
        pathAnchorDescriptorCount: Number(result.pathAnchorDescriptorCount || 0) || 0,
        pathAnchorReplacementApplied: Boolean(result.pathAnchorReplacementApplied),
        pathAnchorReplacementDescriptorCount: Number(result.pathAnchorReplacementDescriptorCount || 0) || 0,
        sharedFormCloneRebindApplied: Boolean(result.sharedFormCloneRebindApplied),
        sharedFormCloneRebindDescriptorCount: Number(result.sharedFormCloneRebindDescriptorCount || 0) || 0,
        selectedUseExtGStateCloneRebindApplied: Boolean(result.selectedUseExtGStateCloneRebindApplied),
        selectedUseExtGStateCloneRebindDescriptorCount: Number(result.selectedUseExtGStateCloneRebindDescriptorCount || 0) || 0,
        selectedUseRgbColorCloneRebindApplied: Boolean(result.selectedUseRgbColorCloneRebindApplied),
        selectedUseRgbColorCloneRebindDescriptorCount: Number(result.selectedUseRgbColorCloneRebindDescriptorCount || 0) || 0,
        selectedUseDeviceColorCloneRebindApplied: Boolean(result.selectedUseDeviceColorCloneRebindApplied),
        selectedUseDeviceColorCloneRebindDescriptorCount: Number(result.selectedUseDeviceColorCloneRebindDescriptorCount || 0) || 0,
        deviceColorOperatorRunRewriteApplied: Boolean(result.deviceColorOperatorRunRewriteApplied),
        deviceColorOperatorRewriteDescriptorCount: Number(result.deviceColorOperatorRewriteDescriptorCount || 0) || 0,
        selectedUseSpecialColorTintCloneRebindApplied: Boolean(result.selectedUseSpecialColorTintCloneRebindApplied),
        selectedUseSpecialColorTintCloneRebindDescriptorCount: Number(result.selectedUseSpecialColorTintCloneRebindDescriptorCount || 0) || 0,
        specialColorOperatorRunRewriteApplied: Boolean(result.specialColorOperatorRunRewriteApplied),
        specialColorOperatorRewriteDescriptorCount: Number(result.specialColorOperatorRewriteDescriptorCount || 0) || 0,
        selectedUseStrokeGeometryCloneRebindApplied: Boolean(result.selectedUseStrokeGeometryCloneRebindApplied),
        selectedUseStrokeGeometryCloneRebindDescriptorCount: Number(result.selectedUseStrokeGeometryCloneRebindDescriptorCount || 0) || 0,
        selectedUseLocalStateMaterializationApplied: Boolean(result.selectedUseLocalStateMaterializationApplied),
        visualDiffProof: normalizeNativePdfVisualDiffProof(result, result),
        issues: result.issues || []
