  function getSmartConnectorStateForQa() {
    const connectors = allCanvasObjectsDeep().filter(isSmartConnectorObject);
    return {
      schema: "figureStudio.smartConnector.qa.v1",
      tool: state.tool,
      anchorCount: els.smartConnectorOverlay?.querySelectorAll(".smart-connector-anchor").length || 0,
      endpointHandleCount: els.smartConnectorOverlay?.querySelectorAll(".smart-connector-endpoint").length || 0,
      bendHandleCount: els.smartConnectorOverlay?.querySelectorAll(".smart-connector-bend").length || 0,
      portRoles: [...SMART_CONNECTOR_PORT_ROLES],
      selectedConnectorId: selectedTopLevelObjects().length === 1 && isSmartConnectorObject(selectedTopLevelObjects()[0]) ? selectedTopLevelObjects()[0].figureId : "",
      selectedGeometryHandle: smartConnectorInteraction.endpoint
        ? { kind: "endpoint", endpoint: smartConnectorInteraction.endpoint.endpoint, connectorId: smartConnectorInteraction.endpoint.connectorId }
        : smartConnectorInteraction.bend
          ? { kind: "bend", index: smartConnectorInteraction.bend.index, connectorId: smartConnectorInteraction.bend.connectorId }
          : null,
      connectors: connectors.map((connector) => {
        const meta = normalizeSmartConnectorMeta(connector.smartConnectorMeta);
        const style = readStyle(connector);
        const bends = normalizeSmartConnectorBends(connector._smartConnectorBends || meta.autoBends);
        const start = connectorEndpointPoint(meta.start);
        const end = connectorEndpointPoint(meta.end);
        const routeBlockedBounds = smartConnectorRoutingBlockedRects(connector, meta);
        const labelBlockedBounds = smartConnectorLabelBlockedRects(connector);
        const labelObject = smartConnectorLabelObject(connector);
        const labelBox = labelObject?.getBoundingRect?.();
        const labelBounds = labelBox ? { left: labelBox.left, top: labelBox.top, right: labelBox.left + labelBox.width, bottom: labelBox.top + labelBox.height } : null;
        return {
          id: connector.figureId,
          name: connector.name,
          meta: cloneManifestValue(meta, {}),
          style: {
            stroke: style.stroke || "",
            strokeWidth: Number(style.strokeWidth || 0),
            lineDash: style.lineDash || "solid",
            arrowStart: normalizeLineHead(style.arrowStart || "none"),
            arrowEnd: normalizeLineHead(style.arrowEnd || style.arrowHead || "none")
          },
          bends,
          routingState: meta.routingState,
          automaticRouteClear: meta.route !== "elbow" || (Boolean(start && end) && smartConnectorBendsClear(start, end, bends, routeBlockedBounds)),
          labelBounds,
          labelClear: !labelBounds || !labelBlockedBounds.some((rect) => connectorRectsOverlap(labelBounds, rect)),
          occupiedBounds: labelBlockedBounds,
          routeBlockedBounds,
          endpoints: { start, end },
          fullyDetached: !meta.start.objectId && !meta.end.objectId,
          bounds: connector.getBoundingRect(),
          labelObjectId: smartConnectorLabelObject(connector)?.figureId || "",
          pathCommandCount: Array.isArray(connector.path) ? connector.path.length : 0
        };
      }),
      callouts: canvas?.getObjects?.().filter((object) => object.scientificCalloutMeta).map((object) => ({
        id: object.figureId,
        leaderConnectorId: object.scientificCalloutMeta.leaderConnectorId || ""
      })) || [],
      groups: (canvas?.getObjects?.() || []).filter((object) => groupChildren(object).length).map((group) => ({
        id: group.figureId || "",
        name: group.name || "",
        childIds: (() => {
          const descendants = [];
          const visit = (object) => groupChildren(object).forEach((child) => { descendants.push(child); visit(child); });
          visit(group);
          return descendants.map((object) => object.figureId || "").filter(Boolean);
        })()
      }))
    };
  }

  function setSmartConnectorForQa(connectorId, patch = {}) {
    const connector = getByFigureId(connectorId);
    if (!isSmartConnectorObject(connector)) return { status: "not-found", connectorId };
    const meta = normalizeSmartConnectorMeta({ ...connector.smartConnectorMeta, ...patch });
    connector.smartConnectorMeta = meta;
    refreshSmartConnectors();
    syncUi();
    return { status: "ok", connectorId, meta: cloneManifestValue(meta, {}) };
  }

  function reassignSmartConnectorEndpointForQa(connectorId, endpoint, objectId, anchor) {
    const connector = getByFigureId(connectorId);
    const target = getByFigureId(objectId);
    if (!isSmartConnectorObject(connector) || !smartConnectorTargetEligible(target) || !["start", "end"].includes(endpoint)) return { status: "unavailable" };
    const next = normalizeSmartConnectorMeta({ ...connector.smartConnectorMeta, [endpoint]: { objectId, anchor } });
    connector.smartConnectorMeta = next;
    refreshSmartConnectors();
    syncUi();
    return { status: "ok", meta: cloneManifestValue(next, {}) };
  }

  function createSmartConnectorForQa(startObjectId, endObjectId, options = {}) {
    const startTarget = getByFigureId(startObjectId);
    const endTarget = getByFigureId(endObjectId);
    if (!smartConnectorTargetEligible(startTarget) || !smartConnectorTargetEligible(endTarget)) return { status: "unavailable" };
    const connector = makeSmartConnector(
      { objectId: startTarget.figureId, anchor: options.startAnchor || "right" },
      { objectId: endTarget.figureId, anchor: options.endAnchor || "left" },
      options,
      options.name || "Smart connector",
      sourceMeta({ kind: "qa-smart-connector" })
    );
    canvas.add(connector);
    syncSmartConnectorLabel(connector);
    canvas.setActiveObject(connector);
    syncUi();
    return { status: "ok", connectorId: connector.figureId };
  }

