  function selectSelectionContextScenarioForQa(kind = "shape") {
    let byRole = Object.fromEntries(selectionContextScenarioObjects().map((object) => [object.qaSelectionContextRole, object]));
    if (pathNodeEdit.object) stopPathNodeEdit({ sync: false });
    if (kind === "document") {
      canvas.discardActiveObject();
      canvas.requestRenderAll();
      syncUi();
      return getSelectionContextStateForQa();
    }
    if (kind === "mixed-text-locked") {
      if (!byRole["text-locked"]) {
        const lockedText = makeTextbox("Locked annotation", 286, 158, 210, 46, {
          fill: "#1f6f8b",
          fontFamily: DEFAULT_FONT_FAMILY,
          fontSize: 18,
          textAlign: "center",
          opacity: 1
        }, "Locked context text", sourceMeta({ sourceId: "qa-selection-context", kind: "qa" }));
        lockedText.qaSelectionContextRole = "text-locked";
        applyLock(lockedText, true);
        canvas.add(lockedText);
        byRole = { ...byRole, "text-locked": lockedText };
      }
      setActiveObjects([byRole.text, byRole["text-locked"]].filter(Boolean));
    } else if (kind === "mixed") setActiveObjects([byRole.shape, byRole.text, byRole.line].filter(Boolean));
    else if (kind === "mixed-vector") setActiveObjects([byRole["path-a"], byRole["path-b"]].filter(Boolean));
    else {
      const role = kind === "anchor" || kind === "path" ? "path-a" : kind;
      if (byRole[role]) setActiveObjects([byRole[role]]);
    }
    if (kind === "anchor" && byRole["path-a"]) {
      startPathNodeEdit(byRole["path-a"]);
      const endpoint = pathNodeDescriptors(byRole["path-a"])[1] || pathNodeDescriptors(byRole["path-a"])[0];
      if (endpoint) {
        selectPathHandle(byRole["path-a"], endpoint.commandIndex, endpoint.handleType);
        renderPathNodeOverlay();
      }
    }
    canvas.requestRenderAll();
    syncUi();
    return getSelectionContextStateForQa();
  }

