  function getLiveTypographyStateForQa(options = {}) {
    const object = options.objectId || options.object_id ? getByFigureId(options.objectId || options.object_id) : selectedTopLevelObjects()[0];
    if (!object) return { status: "not-found" };
    const style = readStyle(object);
    const selection = resolveSelectionContext([object]);
    return {
      status: "ok",
      objectId: object.figureId || "",
      type: layerTypeLabel(object),
      text: getObjectText(object),
      fontFamily: style.fontFamily || "",
      fontSize: Number(style.fontSize || 0),
      lineHeight: Number(style.lineHeight || 0),
      charSpacing: Number(style.charSpacing || 0),
      underline: Boolean(style.underline),
      linethrough: Boolean(style.linethrough),
      direction: style.direction || "ltr",
      textAlign: style.textAlign || "left",
      kerning: cloneManifestValue(object.figureStudioKerningPairs, {}),
      textPath: textPathStateForObject(object),
      textPathMeta: cloneManifestValue(object.figureStudioTextPathMeta, null),
      pdfText: pdfTextRunReviewState(object),
      selectionContext: {
        kind: selection.kind,
        label: selection.label,
        properties: Object.fromEntries(Object.entries(selection.properties || {}).map(([key, value]) => [key, {
          value: value.value,
          mixed: value.mixed,
          supportedCount: value.supportedCount
        }]))
      }
    };
  }

