  function selectParagraphListRangeForQa(options = {}) {
    const object = options.objectId || options.object_id ? getByFigureId(options.objectId || options.object_id) : selectedTopLevelObjects()[0];
    if (!canUseSemanticLists(object)) return { status: "unavailable" };
    canvas.setActiveObject(object);
    if (!object.isEditing) object.enterEditing();
    const lines = String(object.text || "").split("\n");
    const from = clamp(Math.round(Number(options.startParagraph ?? options.start_paragraph ?? 0) || 0), 0, Math.max(0, lines.length - 1));
    const to = clamp(Math.round(Number(options.endParagraph ?? options.end_paragraph ?? from) || from), from, Math.max(0, lines.length - 1));
    const starts = [];
    let offset = 0;
    lines.forEach((line) => { starts.push(offset); offset += line.length + 1; });
    object.selectionStart = starts[from];
    object.selectionEnd = Math.min(String(object.text || "").length, starts[to] + lines[to].length);
    object._updateTextarea?.();
    canvas.requestRenderAll();
    syncUi();
    return { status: "ok", startParagraph: from, endParagraph: to, selected: selectedParagraphIndexes(object) };
  }

