    return {
      status: "ok",
      objectId: curve.figureId || "",
      sourceObjectId: sourceObject?.figureId || "",
      sourceBacked: Boolean(sourceObject && sourceBounds),
      commandCount: Array.isArray(curve.path) ? curve.path.length : 0,
      handleCount: handles.length,
      controlHandleCount: controlHandles.length,
      controlHandleTypes: controlHandles.map((descriptor) => descriptor.handleType)
    };
