    const formDefinition = selectedPdfFormDefinitionForRow(object, row);
    if (
      !row?.cloneAndRebindSharedForm
      || !row.selectedXObjectInvocationId
      || row.targetContentStreamScope !== "form-xobject-content-stream"
      || !paintContext?.exact
      || !strokeStyle
      || !["S", "s", "B", "B*", "b", "b*"].includes(String(paintOperator?.operator || ""))
      || !Number.isFinite(Number(paintOperator?.operator_index))
      || !Number.isFinite(Number(paintOperator?.byte_offset))
      || (extGStateNames.length && extGStateNames.some((name) => !extGStateUsages.some((usage) => String(usage.resource_name || "") === name)))
      || guardedExtGState
      || invocation?.transparency_group_in_chain === true
      || formDefinition?.transparency_group === true
      || !scale
    ) return null;
