      schema: "figureStudio.selectedPdfUseStrokeContext.v1",
      object,
      row,
      sequence,
      paintContext,
      paintOperator,
      properties,
      availableProperties: Object.keys(properties),
      miterLimit: properties.miterLimit || null,
      invocationId: row.selectedXObjectInvocationId,
      invocationPath: row.selectedXObjectInvocationPath || "",
      ownerXref,
      uniformScale: scale,
      effectiveCtm,
      entryDefaultAppearanceProven: invocation?.entry_default_appearance_proven === true,
      sourceFormStreamSha256: String(formDefinition?.stream_sha256 || ""),
      cloneAndRebindSharedForm: true,
      fullNativeEquivalence: false
