      ...context,
      sourceOwner,
      descriptor,
      descriptorId: descriptor?.id || "",
      patches,
      values,
      sourceValues,
      stagedProperties: Object.keys(patches),
      staged: Object.keys(patches).length > 0,
      fullNativeEquivalence: false
