      schema: "figureStudio.selectedPdfUseColorState.v2",
      object,
      sourceOwner,
      channels,
      availableChannels: Object.keys(channels),
      staged: Object.values(channels).some((entry) => entry.staged),
      invocationId: contexts[0].invocationId,
      invocationPath: contexts[0].invocationPath,
      ownerXref: contexts[0].ownerXref,
