    const specialColors = (specialColorPatches || []).filter(Boolean);
    const allColors = [...colors, ...specialColors];
    const strokes = (strokeStylePatches || []).filter(Boolean);
    const appearancePatch = extGStateAppearancePatch && typeof extGStateAppearancePatch === "object" ? extGStateAppearancePatch : null;
