      page_number: pdfSourcePageNumberForObject(sourceOwner) || 1,
      target_content_stream_xref: state.ownerXref || row?.targetXObjectXref || 0,
      target_content_stream_scope: "form-xobject-content-stream",
      target_xobject_xref: state.ownerXref || row?.targetXObjectXref || 0,
      target_xobject_name: row?.targetXObjectName || "",
      ...primaryPatch,
      action: appearancePatch ? "rewrite_selected_use_appearance_stack" : "rewrite_selected_use_path_appearance",
      device_color_patches: colors,
      rgb_color_patches: colors.every((patch) => String(patch?.target_color_space || patch?.source_color_space || "DeviceRGB") === "DeviceRGB") ? colors : [],
      special_color_patches: specialColors,
      stroke_style_patches: strokes,
      extgstate_appearance_patch: appearancePatch,
