      selected_paint_operator: paintOperator.operator,
      selected_paint_operator_index: Number(paintOperator.operator_index),
      selected_paint_operator_byte_offset: Number(paintOperator.byte_offset),
      selected_form_invocation_id: state.invocationId || row?.selectedXObjectInvocationId || "",
