      boundedContentStreamRewrite: isSimpleStreamRewrite,
      boundedPaintOperatorRewrite: isPaintOperatorDisable && result.status === "ok",
      boundedRgbColorOperatorRewrite: isRgbColorOperatorRewrite && result.status === "ok",
      boundedStrokeWidthOperatorRewrite: isStrokeWidthOperatorRewrite && result.status === "ok",
      boundedPathGeometryTransform: isPathGeometryTransform && result.status === "ok",
