    const sourcePageSize = tree?.source_page_size || {};
    const sourceWidth = Math.max(1, Number(sourcePageSize.width || target.importMeta?.sourceWidth || target.importMeta?.originalWidth || 612) || 612);
    const sourceHeight = Math.max(1, Number(sourcePageSize.height || target.importMeta?.sourceHeight || target.importMeta?.originalHeight || 792) || 792);
    const streamRows = nativePdfEditableContentStreamRows(tree);
    const requestedXref = Number(options.targetContentStreamXref || options.target_content_stream_xref || 0) || 0;
