          depth: 2,
          actions: [],
          targetContentStreamXref: xref,
          targetContentStreamScope: "form-xobject-content-stream",
          targetXObjectXref: xref,
          targetXObjectName: String(xobject?.name || ""),
          targetXObjectPageCtm: invocation?.page_ctm || xobject?.page_ctm || [1, 0, 0, 1, 0, 0],
          targetXObjectInvocationIds: [invocation?.id].filter(Boolean),
          targetXObjectInvocationPaths: [invocation?.invocation_path].filter(Boolean),
          targetXObjectSharedDefinition: Boolean(invocation?.shared_definition),
