        targetContentStreamScope: row?.targetContentStreamScope || options.targetContentStreamScope || options.target_content_stream_scope || "",
        targetOperatorIndex: row?.targetOperatorIndex ?? options.targetOperatorIndex ?? options.target_operator_index ?? null,
