        targetOperatorByteOffset: row?.byteOffset ?? options.targetOperatorByteOffset ?? options.target_operator_byte_offset ?? options.byteOffset ?? options.byte_offset ?? null,
        operatorCategory: row?.operatorCategory || options.operatorCategory || options.operator_category || "",
