        targetContentStreamScope: row?.targetContentStreamScope || options.targetContentStreamScope || options.target_content_stream_scope || "",
        targetOperatorIndex: row?.targetOperatorIndex ?? options.targetOperatorIndex ?? options.target_operator_index ?? null,
        targetOperator: row?.targetOperator || options.targetOperator || options.target_operator || "",
        targetOperatorByteOffset: row?.byteOffset ?? options.targetOperatorByteOffset ?? options.target_operator_byte_offset ?? options.byteOffset ?? options.byte_offset ?? null,
