  function renderPdfPartRow(record) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = `pdf-part-row${record.selected ? " selected" : ""}${record.hidden ? " hidden-object" : ""}${record.locked ? " locked" : ""}`;
    row.dataset.pdfPartId = record.id;
    row.dataset.pdfPartKind = record.kind;
    row.title = record.parentName ? `Contained in ${record.parentName}` : "Select part";

    const kind = document.createElement("span");
    kind.className = `pdf-part-kind pdf-part-kind-${record.kind}`;
    kind.textContent = compactStatus(record.kind || "part");
    kind.dataset.pdfPartFilter = "type";
    kind.dataset.pdfPartFilterValue = record.kind || "";
    kind.title = `Filter type: ${compactStatus(record.kind || "part")}`;
    row.appendChild(kind);

    const label = document.createElement("span");
    label.className = "pdf-part-label";
    const name = document.createElement("strong");
    name.textContent = record.name || "PDF part";
    const meta = document.createElement("small");
    meta.className = "pdf-part-meta";
    meta.appendChild(document.createTextNode(record.sourceLabel || "source"));
    record.features.slice(0, 4).forEach((feature) => {
      meta.appendChild(pdfPartFilterChip("feature", feature, compactStatus(feature)));
    });
    record.regions.slice(0, 2).forEach((region) => {
      meta.appendChild(pdfPartFilterChip("region", region, compactStatus(region)));
    });
    label.append(name, meta);
    row.appendChild(label);

    const swatches = document.createElement("span");
    swatches.className = "pdf-part-swatches";
    swatches.appendChild(pdfPartSwatch(record.fill, "Fill", "fill"));
    swatches.appendChild(pdfPartSwatch(record.stroke, "Stroke", "stroke"));
    row.appendChild(swatches);
    return row;
  }

  function pdfPartFilterChip(field, value, label) {
    const chip = document.createElement("span");
    chip.className = "pdf-part-filter-chip";
    chip.textContent = label || value;
    chip.dataset.pdfPartFilter = field;
    chip.dataset.pdfPartFilterValue = value || "";
    chip.title = `Filter ${compactStatus(field)}: ${label || value}`;
    return chip;
  }

  function pdfPartSwatch(color, label, field) {
    const swatch = document.createElement("span");
    swatch.className = "pdf-part-swatch";
    swatch.title = color ? `Filter ${label.toLowerCase()}: ${color}` : `${label}: none`;
    swatch.style.background = color && color.startsWith("#") ? color : "transparent";
    swatch.dataset.empty = color ? "false" : "true";
    if (color) {
      swatch.dataset.pdfPartFilter = field;
      swatch.dataset.pdfPartFilterValue = color;
    }
    return swatch;
  }

  function pdfPartRecords() {
    if (!canvas) return [];
    const records = [];
    const previousCache = pdfPartsDenseMetaCache;
    pdfPartsDenseMetaCache = new WeakMap();
    try {
      const topLevelObjects = canvas.getObjects().filter(isFigureObject);
      topLevelObjects.forEach((object, index) => visitPdfPartObject(object, null, object, [index], records));
    } finally {
      pdfPartsDenseMetaCache = previousCache;
    }
    return records;
  }

  function pdfPartsDenseSvgProxyMetaForObject(object) {
    if (!object) return null;
    if (!pdfPartsDenseMetaCache) return denseSvgProxyMetaForObject(object);
    if (pdfPartsDenseMetaCache.has(object)) return pdfPartsDenseMetaCache.get(object);
    const meta = denseSvgProxyMetaForObject(object);
    pdfPartsDenseMetaCache.set(object, meta);
    return meta;
  }

  function pdfPartsIsDenseSvgProxyObject(object) {
    return Boolean(object && (isDenseSvgProxyMode(object.importMeta?.importMode || object.importMeta?.import_mode) || pdfPartsDenseSvgProxyMetaForObject(object)));
  }

  function visitPdfPartObject(object, parent, topLevel, path, records) {
    if (!object) return;
    if (pdfPartsManagerCandidate(object, parent, topLevel)) {
      records.push(pdfPartRecordForObject(object, parent, topLevel, path));
    }
    groupChildren(object).forEach((child, index) => {
      visitPdfPartObject(child, object, topLevel, [...path, index], records);
    });
  }

  function pdfPartsManagerCandidate(object, parent, topLevel) {
    if (!object || object.excludeFromExport) return false;
    const mode = pdfPartImportMode(object, parent, topLevel);
    const parentManifest = parent?.pdfEditabilityManifest || topLevel?.pdfEditabilityManifest || null;
    return Boolean(
      pdfEditabilityManifestForObject(object)
      || parentManifest
      || proxyPanelForObject(object)
      || pdfPartsIsDenseSvgProxyObject(object)
      || advancedFeatureProxyLayerMetaForObject(object)
      || rasterVectorTraceMetaForObject(object)
      || object.importMeta?.nativeProxyForSourceBackedFeature
      || object.importMeta?.native_proxy_for_source_backed_feature
      || /pdf|pymupdf|converted|raster-vector-trace|advanced-svg-native-feature-proxy|embedded-raster|dense-svg/i.test(mode)
    );
  }

  function pdfPartRecordForObject(object, parent, topLevel, path) {
    const topLevelObjects = canvas.getObjects();
    const topLevelObject = topLevelObjects.includes(object) ? object : topLevel;
    const manifest = object.pdfEditabilityManifest
      || pdfEditabilityManifestForObject(object)
      || parent?.pdfEditabilityManifest
      || pdfEditabilityManifestForObject(parent)
      || topLevel?.pdfEditabilityManifest
      || pdfEditabilityManifestForObject(topLevel)
      || null;
    const importInfo = object.importMeta || parent?.importMeta || topLevel?.importMeta || {};
    const id = object.figureId || `${topLevelObject?.figureId || "pdf-part"}:${path.join(".")}`;
    const selectedTargets = new Set(selectedTopLevelObjects().map((item) => item.figureId));
    const features = pdfPartSourceFeatureTypes(object, parent, topLevel);
    const regions = pdfPartSpatialRegions(object, parent, topLevel);
    const fill = normalizePdfPartColor(readStyle(object).fill || object.fill || object.styleMeta?.fill || "");
    const stroke = normalizePdfPartColor(readStyle(object).stroke || object.stroke || object.styleMeta?.stroke || "");
    const sourceLabel = importInfo.sourceFilename
      || importInfo.sourcePdfFilename
      || manifest?.source_filename
      || object.source?.filename
      || parent?.source?.filename
      || topLevel?.source?.filename
      || importInfo.importMode
      || "PDF/SVG source";
    const text = getObjectText(object) || String(object.text || "");
    const name = object.name || importedVectorObjectName({ namePrefix: "PDF part" }, object, path[path.length - 1] || 0);
    const edited = Boolean(
      manifest?.mutation?.edited
      || object.figureStudioEditState?.edited
      || parent?.figureStudioEditState?.edited
      || topLevel?.figureStudioEditState?.edited
    );
    const record = {
      id,
      object,
      topLevelObject,
      parent,
      parentName: parent && parent !== object ? parent.name || humanizeType(parent.figureType || parent.type) : "",
      name,
      sourceLabel,
      kind: pdfPartKind(object, parent, topLevel),
      importMode: pdfPartImportMode(object, parent, topLevel),
      fill,
      stroke,
      features,
      regions,
      edited,
      hidden: object.visible === false,
      locked: Boolean(object.locked),
      selected: Boolean(topLevelObject?.figureId && selectedTargets.has(topLevelObject.figureId)),
      searchText: [
        name,
        sourceLabel,
        text,
        pdfPartImportMode(object, parent, topLevel),
        fill,
        stroke,
        features.join(" "),
        regions.join(" "),
        edited ? "edited" : "unedited"
      ].join(" ").toLowerCase()
    };
    return record;
  }

  function pdfPartImportMode(object, parent, topLevel) {
    return object?.importMeta?.importMode
      || object?.importMeta?.import_mode
      || parent?.importMeta?.importMode
      || parent?.importMeta?.import_mode
      || topLevel?.importMeta?.importMode
      || topLevel?.importMeta?.import_mode
      || "";
  }

  function pdfPartKind(object, parent, topLevel) {
    if (isProxyBackedPanel(object) || isDenseSvgProxyObject(object)) return "proxy";
    const layerKind = object?.denseSvgProxyLayerMeta?.layer_kind
      || object?.importMeta?.releaseLayerKind
      || object?.importMeta?.release_layer_kind
      || parent?.denseSvgProxyLayerMeta?.layer_kind
      || "";
    if (["path", "text", "shape"].includes(layerKind)) return layerKind;
    const figureType = String(object?.figureType || object?.type || "").toLowerCase();
    const imported = importedVectorFigureType(object);
    if (imported === "image" || figureType === "image" || isRasterObject(object)) return "image";
    if (imported === "text" || figureType.includes("text") || figureType === "panellabel") return "text";
    if (imported === "path" || figureType === "path") return "path";
    if (["rect", "rectangle", "ellipse", "circle", "line", "arrow", "polygon", "polyline", "triangle", "advancedfeatureproxy"].includes(figureType) || ["rect", "ellipse", "line"].includes(imported)) return "shape";
    if (parent || topLevel) return "shape";
    return "path";
  }

  function normalizePdfPartColor(value) {
    const raw = String(value || "").trim().toLowerCase();
    if (!raw || raw === "none" || raw === "transparent") return "";
    const short = raw.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i);
    if (short) return `#${short[1]}${short[1]}${short[2]}${short[2]}${short[3]}${short[3]}`.toLowerCase();
    const hex = raw.match(/^#[0-9a-f]{6}/i);
    if (hex) return hex[0].toLowerCase();
    const rgb = raw.match(/^rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
    if (rgb) {
      return `#${[rgb[1], rgb[2], rgb[3]].map((part) => clamp(Number(part) || 0, 0, 255).toString(16).padStart(2, "0")).join("")}`;
    }
    const normalized = normalizeSvgPaint(raw);
    return /^#[0-9a-f]{6}$/i.test(normalized || "") ? normalized.toLowerCase() : raw;
  }

  function pdfPartSourceFeatureTypes(object, parent, topLevel) {
    const features = new Set();
    const add = (feature) => {
      const key = String(feature || "").trim().toLowerCase().replace(/[-\s]+/g, "_");
      if (["clip_path", "mask", "filter", "blend_mode"].includes(key)) features.add(key);
    };
    const descriptor = object?.importMeta?.advancedFeatureProxy || object?.importMeta?.advanced_feature_proxy || null;
    (descriptor?.features || []).forEach(add);
    (object?.denseSvgProxyLayerMeta?.materialization_source_feature_types || object?.importMeta?.materializationSourceFeatureTypes || object?.importMeta?.materialization_source_feature_types || []).forEach(add);
    (object?.denseSvgAdvancedFeatureProxyMeta?.feature_types || []).forEach(add);
    (parent?.denseSvgAdvancedFeatureProxyMeta?.feature_types || []).forEach(add);
    [
      object?.denseSvgProxyLayerMeta?.advanced_feature_profile,
      object?.pdfEditabilityManifest?.advanced_feature_profile,
      object?.pdfEditabilityManifest?.chunk?.advanced_feature_profile,
      parent?.denseSvgProxyLayerMeta?.advanced_feature_profile,
      parent?.pdfEditabilityManifest?.advanced_feature_profile,
      parent?.pdfEditabilityManifest?.chunk?.advanced_feature_profile,
      pdfPartsDenseSvgProxyMetaForObject(object)?.analysis?.advanced_feature_profile,
      pdfPartsDenseSvgProxyMetaForObject(parent)?.analysis?.advanced_feature_profile,
      pdfPartsDenseSvgProxyMetaForObject(topLevel)?.analysis?.advanced_feature_profile
    ].filter(Boolean).forEach((profile) => {
      if (Number(profile.referenced_clip_path_count || profile.clip_path_count || 0)) add("clip_path");
      if (Number(profile.referenced_mask_count || profile.mask_count || 0)) add("mask");
      if (Number(profile.referenced_filter_count || profile.filter_count || 0)) add("filter");
      if (Number(profile.blend_mode_element_count || 0)) add("blend_mode");
    });
    return [...features];
  }

  function pdfPartSpatialRegions(object, parent, topLevel) {
    const regions = new Set();
    const add = (value) => {
      if (!value) return;
      const name = typeof value === "string" ? value : value.name || value.id || "";
      const normalized = String(name || "").trim().toLowerCase().replace(/_/g, "-");
      if (!normalized) return;
      regions.add(normalized);
      if (normalized.endsWith("-half")) regions.add(normalized.replace("-half", ""));
      if (normalized === "plot") regions.add("plot-area");
      if (normalized === "panel") regions.add("panel-area");
    };
    add(object?.denseSvgProxyLayerMeta?.region);
    add(object?.importMeta?.releaseRegion || object?.importMeta?.release_region);
    add(parent?.denseSvgProxyLayerMeta?.region);
    add(parent?.importMeta?.releaseRegion || parent?.importMeta?.release_region);
    const box = object?.getBoundingRect?.();
    const art = artboardPx();
    if (box && art.width && art.height) {
      const centerX = box.left + box.width / 2;
      const centerY = box.top + box.height / 2;
      regions.add(centerX <= art.width / 2 ? "left" : "right");
      regions.add(centerY <= art.height / 2 ? "top" : "bottom");
      if (centerX >= art.width * 0.12 && centerX <= art.width * 0.88 && centerY >= art.height * 0.12 && centerY <= art.height * 0.88) regions.add("panel-area");
      if (centerX >= art.width * 0.20 && centerX <= art.width * 0.80 && centerY >= art.height * 0.18 && centerY <= art.height * 0.82) regions.add("plot-area");
    }
    return [...regions];
  }

  function pdfPartRecordMatchesFilters(record, filters) {
    const search = String(filters.search || "").trim().toLowerCase();
    if (search && !record.searchText.includes(search)) return false;
    if (filters.type && record.kind !== filters.type) return false;
    const fill = normalizePdfPartColor(filters.fill);
    if (fill && record.fill !== fill) return false;
    const stroke = normalizePdfPartColor(filters.stroke);
    if (stroke && record.stroke !== stroke) return false;
    if (filters.feature && !record.features.includes(filters.feature)) return false;
    if (filters.region && !record.regions.includes(filters.region)) return false;
    if (filters.edited === "edited" && !record.edited) return false;
    if (filters.edited === "unedited" && record.edited) return false;
    return true;
  }

  function filteredPdfPartRecords() {
    const filters = pdfPartsFilters();
    return pdfPartRecords().filter((record) => pdfPartRecordMatchesFilters(record, filters));
  }

  function pdfPartRecordById(id) {
    return pdfPartRecords().find((record) => record.id === id) || null;
  }

  function pdfPartSelectionTargets(records) {
    const seen = new Set();
    return (records || []).map((record) => record.topLevelObject || record.object).filter((object) => {
      if (!object || !isFigureObject(object) || seen.has(object.figureId)) return false;
      seen.add(object.figureId);
      return object.visible !== false && !object.locked && !isReferenceObject(object);
    });
  }

  function selectPdfPartRecord(record) {
    const target = record?.topLevelObject || record?.object;
    if (!target) return false;
    setActiveObjects([target]);
    if (record.object !== target) showToast(`Selected containing layer for ${record.name || "PDF part"}`);
    return true;
  }

  function pdfPartTopLevelTargets(records) {
    const seen = new Set();
    return (records || []).map((record) => record.topLevelObject || record.object).filter((object) => {
      if (!object || !isFigureObject(object) || seen.has(object.figureId) || isReferenceObject(object)) return false;
      seen.add(object.figureId);
      return true;
    });
  }

  function pdfPartParentTargets(records) {
    const seen = new Set();
    return (records || []).map((record) => record.parent || record.topLevelObject || record.object).filter((object) => {
      if (!object || !isFigureObject(object) || seen.has(object.figureId) || isReferenceObject(object)) return false;
      seen.add(object.figureId);
      return true;
    });
  }

  function recordPdfPartsBulkMutation(records, editType, details = {}) {
    const targets = pdfPartTopLevelTargets(records);
    targets.forEach((object) => {
      recordPdfEditabilityMutation(object, editType, {
        matched_part_count: records.length,
        ...(details || {})
      });
    });
    return targets.length;
  }

  function markPdfPartRecordDirty(record) {
    if (record?.topLevelObject && record.topLevelObject !== record.object) record.topLevelObject.dirty = true;
    if (record?.parent && record.parent !== record.object) record.parent.dirty = true;
    record?.object?.setCoords?.();
  }

  function isolatePdfPartRecords(records) {
    const allRecords = pdfPartRecords();
    if (!records.length || !allRecords.length) return { status: "empty", action: "isolate", matched: records.length };
    const visibleObjects = new Set();
    records.forEach((record) => {
      if (record.object) visibleObjects.add(record.object);
      if (record.parent) visibleObjects.add(record.parent);
      if (record.topLevelObject) visibleObjects.add(record.topLevelObject);
    });
    const visibilityById = {};
    let changed = 0;
    let isolated = 0;
    allRecords.forEach((record) => {
      visibilityById[record.id] = record.object?.visible !== false;
      const shouldShow = visibleObjects.has(record.object);
      if (record.object && record.object.visible !== shouldShow) {
        record.object.set?.({ visible: shouldShow });
        markPdfPartRecordDirty(record);
        changed += 1;
      }
      if (shouldShow) isolated += 1;
    });
    pdfPartsIsolationSnapshot = {
      schema: "figureStudio.pdfPartsIsolation.v1",
      created_at: new Date().toISOString(),
      filtered_count: records.length,
      isolated_record_count: isolated,
      total_count: allRecords.length,
      visibility_by_id: visibilityById
    };
    canvas.requestRenderAll();
    syncUi();
    showToast(`Isolated ${records.length.toLocaleString()} filtered PDF part${records.length === 1 ? "" : "s"}`);
    return { status: "ok", action: "isolate", matched: records.length, isolated, changed, total: allRecords.length };
  }

  function clearPdfPartsIsolation() {
    if (!pdfPartsIsolationSnapshot) {
      showToast("No PDF part isolation is active");
      return { status: "none", action: "clear-isolation", restored: 0 };
    }
    const visibilityById = pdfPartsIsolationSnapshot.visibility_by_id || {};
    const recordsById = new Map(pdfPartRecords().map((record) => [record.id, record]));
    let restored = 0;
    Object.entries(visibilityById).forEach(([id, visible]) => {
      const record = recordsById.get(id);
      if (!record?.object) return;
      const nextVisible = Boolean(visible);
      if (record.object.visible !== nextVisible) {
        record.object.set?.({ visible: nextVisible });
        markPdfPartRecordDirty(record);
        restored += 1;
      }
    });
    pdfPartsIsolationSnapshot = null;
    canvas.requestRenderAll();
    syncUi();
    showToast("PDF part isolation cleared");
    return { status: "ok", action: "clear-isolation", restored };
  }

  function executePdfPartsBulkAction(action) {
    const records = filteredPdfPartRecords();
    if (action === "clear-isolation") return clearPdfPartsIsolation();
    if (!records.length) {
      showToast("No matching PDF parts");
      return { status: "empty", action, matched: 0 };
    }
    if (action === "isolate") return isolatePdfPartRecords(records);
    if (action === "select") {
      const targets = pdfPartSelectionTargets(records);
      setActiveObjects(targets);
      showToast(`Selected ${targets.length.toLocaleString()} layer${targets.length === 1 ? "" : "s"} from filtered parts`);
      return { status: "ok", action, matched: records.length, selected: targets.length };
    }
    if (action === "select-parents" || action === "select-top") {
      const targets = action === "select-parents" ? pdfPartParentTargets(records) : pdfPartTopLevelTargets(records);
      setActiveObjects(targets);
      showToast(`Selected ${targets.length.toLocaleString()} PDF tree object${targets.length === 1 ? "" : "s"}`);
      return { status: "ok", action, matched: records.length, selected: targets.length };
    }
    if (action === "group") {
      const targets = pdfPartSelectionTargets(records);
      if (targets.length < 2) {
        showToast("Select at least two unlocked filtered layers to group");
        return { status: "not-enough-targets", action, matched: records.length, selected: targets.length };
      }
      const editedTargets = recordPdfPartsBulkMutation(records, "pdf_parts_group", { action });
      setActiveObjects(targets);
      groupSelection();
      return { status: "ok", action, matched: records.length, selected: targets.length, editedTargets };
    }
    if (action === "front" || action === "back") {
      const targets = pdfPartSelectionTargets(records);
      targets.forEach((object) => {
        if (action === "front" && typeof canvas.bringObjectToFront === "function") canvas.bringObjectToFront(object);
        else if (action === "back" && typeof canvas.sendObjectToBack === "function") canvas.sendObjectToBack(object);
      });
      const editedTargets = recordPdfPartsBulkMutation(records, action === "front" ? "pdf_parts_send_front" : "pdf_parts_send_back", { action });
      canvas.requestRenderAll();
      syncUi();
      commitHistory(action === "front" ? "Filtered PDF parts moved to front" : "Filtered PDF parts moved to back");
      return { status: "ok", action, matched: records.length, selected: targets.length, editedTargets };
    }
    const visible = action === "show" ? true : action === "hide" ? false : null;
    const locked = action === "lock" ? true : action === "unlock" ? false : null;
    records.forEach((record) => {
      if (visible !== null) record.object.set?.({ visible });
      if (locked !== null) applyLock(record.object, locked);
      if (record.topLevelObject && record.topLevelObject !== record.object) record.topLevelObject.dirty = true;
      record.object.setCoords?.();
    });
    const editedTargets = recordPdfPartsBulkMutation(records, `pdf_parts_${action}`, { action });
    canvas.requestRenderAll();
    syncUi();
    commitHistory(`Filtered PDF parts ${action === "hide" ? "hidden" : action === "show" ? "shown" : action === "lock" ? "locked" : "unlocked"}`);
    return { status: "ok", action, matched: records.length, editedTargets };
  }

  function getPdfPartsManagerStateForQa() {
    const records = pdfPartRecords();
    const filtered = filteredPdfPartRecords();
    return {
      schema: "figureStudio.pdfPartsManager.qa.v1",
      visible: Boolean(els.pdfPartsManager && !els.pdfPartsManager.hidden),
      filters: { ...pdfPartsFilters() },
      totalCount: records.length,
      filteredCount: filtered.length,
      editedCount: records.filter((record) => record.edited).length,
      hiddenCount: records.filter((record) => record.hidden).length,
      lockedCount: records.filter((record) => record.locked).length,
      isolation: pdfPartsIsolationSnapshot ? {
        active: true,
        filteredCount: Number(pdfPartsIsolationSnapshot.filtered_count || 0) || 0,
        isolatedRecordCount: Number(pdfPartsIsolationSnapshot.isolated_record_count || 0) || 0,
        totalCount: Number(pdfPartsIsolationSnapshot.total_count || 0) || 0
      } : { active: false },
      renderedRowCount: els.pdfPartsList?.querySelectorAll("[data-pdf-part-id]").length || 0,
      kinds: records.reduce((counts, record) => {
        counts[record.kind] = (counts[record.kind] || 0) + 1;
        return counts;
      }, {}),
      features: records.reduce((counts, record) => {
        record.features.forEach((feature) => {
          counts[feature] = (counts[feature] || 0) + 1;
        });
        return counts;
      }, {}),
      sample: filtered.slice(0, 8).map((record) => ({
        id: record.id,
        name: record.name,
        kind: record.kind,
        fill: record.fill,
        stroke: record.stroke,
        features: record.features,
        regions: record.regions,
        edited: record.edited,
        visible: !record.hidden,
        locked: record.locked
      }))
    };
  }

  function setPdfPartsManagerFiltersForQa(filters = {}) {
    ensureLayerState();
    setInspectorTab("layers");
    state.layers.pdfParts = normalizePdfPartsManagerFilters({
      ...pdfPartsFilters(),
      ...filters,
      rowOffset: filters.rowOffset ?? filters.row_offset ?? 0
    });
    renderPdfPartsManager();
    return getPdfPartsManagerStateForQa();
  }

  function resetPdfPartsFiltersForQa() {
    return resetPdfPartsFilters();
  }

  function applyPdfPartsInlineFilterForQa(options = {}) {
    return applyPdfPartsInlineFilter(options.field || options.filter, options.value);
  }

  function getPdfObjectTreeStateForQa() {
    const records = pdfPartRecords();
    const filtered = filteredPdfPartRecords();
    const rows = pdfObjectTreeRows(records, filtered);
    const topLevel = new Set();
    const parents = new Set();
    const depths = [];
    records.forEach((record) => {
      if (record.topLevelObject?.figureId) topLevel.add(record.topLevelObject.figureId);
      if (record.parent?.figureId) parents.add(record.parent.figureId);
      depths.push(String(record.id || "").split(":")[1]?.split(".").length || 1);
    });
    return {
      schema: "figureStudio.pdfObjectTree.qa.v1",
      recordCount: records.length,
      topLevelCount: topLevel.size,
      parentCount: parents.size,
      maxDepth: depths.length ? Math.max(...depths) : 0,
      groupedRecordCount: records.filter((record) => Boolean(record.parent)).length,
      filteredTopLevelCount: rows.filter((row) => row.filteredCount > 0).length,
      renderedTreeRowCount: els.pdfObjectTreeList?.querySelectorAll("[data-pdf-tree-object-id]").length || 0,
      nativeRowCount: rows.filter((row) => row.rowType === "native").length,
      operatorRunCount: rows.filter((row) => row.nativeRole === "operator_run").length,
      nativeRows: rows.filter((row) => row.rowType === "native").map((row) => ({
        id: row.id,
        objectId: row.object?.figureId || "",
        parentId: row.parentId || "",
        role: row.nativeRole,
        name: row.name,
        depth: Number(row.depth || 0) || 0,
        operator: row.targetOperator || "",
        operatorCategory: row.operatorCategory || "",
        byteOffset: row.byteOffset || 0,
        targetOperatorIndex: row.targetOperatorIndex || 0,
        targetContentStreamXref: row.targetContentStreamXref || 0,
        targetContentStreamScope: row.targetContentStreamScope || "",
        targetXObjectXref: row.targetXObjectXref || 0,
        targetXObjectName: row.targetXObjectName || "",
        targetXObjectInvocationIds: row.targetXObjectInvocationIds || [],
        targetXObjectInvocationPaths: row.targetXObjectInvocationPaths || [],
        targetXObjectSharedDefinition: Boolean(row.targetXObjectSharedDefinition),
        perInstanceNativeWriteSupported: row.perInstanceNativeWriteSupported !== false,
        nativeWriteScope: row.nativeWriteScope || "",
        hasPathSequence: Boolean(row.pathSequence?.commands?.length || row.source?.path_sequence?.commands?.length),
        pathSequenceCommandCount: Number(row.pathSequence?.command_count || row.source?.path_sequence?.command_count || 0) || 0,
        targetExtGStateXref: row.targetExtGStateXref || 0,
        targetFunctionXref: row.targetFunctionXref || 0,
        actions: (row.actions || []).map((item) => item.action)
      })),
      operatorRows: rows.filter((row) => row.nativeRole === "operator_run").map((row) => ({
        id: row.id,
        objectId: row.object?.figureId || "",
        parentId: row.parentId || "",
        depth: Number(row.depth || 0) || 0,
        operator: row.targetOperator || "",
        category: row.operatorCategory || "",
        byteOffset: row.byteOffset || 0,
        targetOperatorIndex: row.targetOperatorIndex || 0,
        targetContentStreamXref: row.targetContentStreamXref || 0,
        targetContentStreamScope: row.targetContentStreamScope || "",
        targetXObjectXref: row.targetXObjectXref || 0,
        targetXObjectName: row.targetXObjectName || "",
        targetXObjectInvocationIds: row.targetXObjectInvocationIds || [],
        targetXObjectInvocationPaths: row.targetXObjectInvocationPaths || [],
        targetXObjectSharedDefinition: Boolean(row.targetXObjectSharedDefinition),
        perInstanceNativeWriteSupported: row.perInstanceNativeWriteSupported !== false,
        nativeWriteScope: row.nativeWriteScope || "",
        hasPathSequence: Boolean(row.pathSequence?.commands?.length || row.source?.path_sequence?.commands?.length),
        pathSequenceCommandCount: Number(row.pathSequence?.command_count || row.source?.path_sequence?.command_count || 0) || 0,
        actions: (row.actions || []).map((item) => item.action)
      })),
      treeVisible: Boolean(els.pdfObjectTreePanel && !els.pdfObjectTreePanel.hidden),
      treeRowLimit: PDF_OBJECT_TREE_ROW_LIMIT,
      selectedIds: selectedTopLevelObjects().map((object) => object.figureId)
    };
  }

  async function executePdfObjectTreeCommandForQa(action, options = {}) {
    const before = getPdfObjectTreeStateForQa();
    if (options.rowId || options.row_id || ["edit-native-path", "commit-native-path", "cancel-native-path", "convert-native-path-overlay", "rewrite-content", "disable-paint", "recolor-rgb", "stroke-width", "move-path", "replace-path-boolean", "disable-clip", "blend-normal", "soften-opacity", "remove-soft-mask", "rewrite-gradient", "rewrite-shading-background", "rewrite-pattern-colors"].includes(action)) {
      const rowId = options.rowId || options.row_id || before.nativeRows.find((row) => row.actions.includes(action))?.id || "";
      const result = await executePdfObjectTreeRowAction(action, rowId, options);
      return {
        before,
        result,
        after: getPdfObjectTreeStateForQa()
      };
    }
    const result = executePdfPartsBulkAction(action || "select-parents");
    return {
      before,
      result,
      after: getPdfObjectTreeStateForQa()
    };
  }

  function getNativePathEditStateForQa() {
    const context = nativePathEditSourceContext();
    const overlayRect = els.pathNodeOverlay?.getBoundingClientRect?.();
    const handles = nativePathHandleDescriptors().map((descriptor) => {
      const point = nativePathEdit.active ? nativePathHandleCanvasPoint(descriptor) : { x: 0, y: 0 };
      return {
        commandIndex: descriptor.commandIndex,
        handleType: descriptor.handleType,
        nodeIndex: descriptor.nodeIndex,
        x: point.x,
        y: point.y,
        clientX: overlayRect ? overlayRect.left + (point.x / Math.max(1, Number(canvas?.width || 1))) * overlayRect.width : 0,
        clientY: overlayRect ? overlayRect.top + (point.y / Math.max(1, Number(canvas?.height || 1))) * overlayRect.height : 0,
        streamX: Number(descriptor.command?.[descriptor.xIndex] || 0),
        streamY: Number(descriptor.command?.[descriptor.yIndex] || 0),
        selected: Boolean(nativePathEdit.selected && samePathHandle(nativePathEdit.selected, descriptor)),
        nativeAuthority: nativePathTypedBindingForHandle(descriptor.commandIndex, descriptor.handleType) ? "proof-gated" : "source-backed"
      };
    });
    return {
      schema: "figureStudio.nativePdfPathEdit.qa.v1",
      active: Boolean(nativePathEdit.active),
      dirty: Boolean(nativePathEdit.dirty),
      commitPending: Boolean(nativePathEdit.commitPending),
      typedStatus: nativePathEdit.typedStatus || "idle",
      typedError: nativePathEdit.typedError || "",
      typedBinding: nativePathEdit.typedBinding ? {
        schema: nativePathEdit.typedBinding.schema || "",
        sourceRevisionId: nativePathEdit.typedBinding.sourceRevisionId || "",
        nodeId: nativePathEdit.typedBinding.nodeId || "",
        physicalStreamRef: nativePathEdit.typedBinding.physicalStreamRef || "",
        writeScopeKind: nativePathEdit.typedBinding.writeScopeKind || "",
        pageCtm: [...(nativePathEdit.typedBinding.pageCtm || [])],
        selectedInvocation: cloneManifestValue(nativePathEdit.typedBinding.selectedInvocation || null, null),
        invocationChain: cloneManifestValue(nativePathEdit.typedBinding.invocationChain || [], []),
        supportedHandleCount: handles.filter((handle) => handle.nativeAuthority === "proof-gated").length,
        fullNativeEquivalence: false
      } : null,
      lastCommit: cloneManifestValue(nativePathEdit.lastCommit || null, null),
      objectId: nativePathEdit.object?.figureId || "",
      rowId: nativePathEdit.rowId || "",
      targetContentStreamXref: nativePathEdit.row?.targetContentStreamXref || 0,
      targetContentStreamScope: nativePathEdit.row?.targetContentStreamScope || "",
      targetXObjectXref: nativePathEdit.row?.targetXObjectXref || 0,
      targetXObjectName: nativePathEdit.row?.targetXObjectName || "",
      selectedInvocationId: nativePathEdit.row?.selectedXObjectInvocationId || "",
      selectedInvocationPath: nativePathEdit.row?.selectedXObjectInvocationPath || "",
      cloneAndRebindSharedForm: Boolean(nativePathEdit.row?.cloneAndRebindSharedForm),
      targetOperator: nativePathEdit.row?.targetOperator || "",
      targetOperatorIndex: nativePathEdit.row?.targetOperatorIndex ?? null,
      targetOperatorByteOffset: nativePathEdit.row?.byteOffset ?? null,
      commandCount: nativePathEdit.commands.length,
      originalCommandCount: nativePathEdit.originalCommands.length,
      handleCount: handles.length,
      canDeleteSelectedAnchor: canDeleteNativePathAnchorDescriptor(),
      handles,
      sourceContext: context ? {
        sourceWidth: context.sourceWidth,
        sourceHeight: context.sourceHeight,
        sourceBounds: context.sourceBounds,
        streamScope: context.streamScope,
        pageCtm: context.pageCtm,
        targetXObjectXref: context.targetXObjectXref,
        targetXObjectName: context.targetXObjectName
      } : null,
      canvasSize: { width: Number(canvas?.width || 0), height: Number(canvas?.height || 0) },
      renderedHandleCount: els.pathNodeOverlay?.querySelectorAll("[data-native-path-handle='true']").length || 0,
      descriptorPreview: nativePathEdit.active ? nativePathEditDescriptorPayload() : null,
      lastPointerMove: lastNativePathPointerMove ? { ...lastNativePathPointerMove } : null
    };
  }

  function startNativePathEditForQa(options = {}) {
    const object = options.objectId || options.object_id ? getByFigureId(options.objectId || options.object_id) : selectedNativePdfCommandTarget();
    const rows = pdfObjectTreeRows(pdfPartRecords(), filteredPdfPartRecords());
    const rowId = options.rowId || options.row_id || "";
    const row = rowId
      ? rows.find((item) => item.id === rowId)
      : selectedNativePathRowForObject(object)
        || rows.find((item) => (!object || item.object === object) && nativePathRowHasEditableSequence(item));
    const result = startNativePathEditFromRow(row, row?.object || object);
    return {
      result,
      state: getNativePathEditStateForQa()
    };
  }

  async function prepareTypedNativePathEditForQa(options = {}) {
    const started = startNativePathEditForQa(options);
    if (started.result?.status !== "ok") return started;
    const binding = await attachTypedNativePathBinding({
      force: options.force !== false,
      announce: false,
      nodeIdHint: nativePathEdit.row?.typedNativeNodeId || nativePathEdit.row?.typed_native_node_id || ""
    });
    return {
      result: started.result,
      binding,
      state: getNativePathEditStateForQa()
    };
  }

  async function commitNativePathEditForQa() {
    const result = await commitNativePathEdit();
    return {
      result,
      state: getNativePathEditStateForQa(),
      objectTree: getPdfObjectTreeStateForQa()
    };
  }

  function cancelNativePathEditForQa() {
    const result = stopNativePathEdit();
    return {
      result,
      state: getNativePathEditStateForQa()
    };
  }

  function getNativePdfFeatureGraphStateForQa(options = {}) {
    const object = options.objectId || options.object_id ? getByFigureId(options.objectId || options.object_id) : null;
    const graphState = nativePdfFeatureGraphState(object);
    return {
      ...graphState,
      panelVisible: Boolean(els.pdfFeatureGraphPanel && !els.pdfFeatureGraphPanel.hidden),
      renderedChipCount: els.pdfFeatureGraphChips?.querySelectorAll("[data-pdf-feature-graph-type]").length || 0,
      renderedActionCount: els.pdfFeatureGraphPanel?.querySelectorAll("[data-pdf-feature-graph-action]").length || 0,
      renderedEditorNodeCount: els.pdfFeatureGraphNodeSelect?.querySelectorAll("option").length || 0,
      selectedEditorNodeId: els.pdfFeatureGraphNodeSelect?.value || "",
      selectedEditorAction: els.pdfFeatureGraphEditSelect?.value || "",
      highlightedRowCount: els.pdfObjectTreeList?.querySelectorAll(".graph-highlight").length || 0
    };
  }

  async function executeNativePdfFeatureGraphCommandForQa(action, options = {}) {
    const before = getNativePdfFeatureGraphStateForQa(options);
    const result = await executeNativePdfFeatureGraphCommand(action, options);
    return {
      before,
      result,
      after: getNativePdfFeatureGraphStateForQa(options),
      inventory: getNativePdfEditPlanInventoryForQa()
    };
  }

  function executePdfPartsBulkActionForQa(action) {
    const before = getPdfPartsManagerStateForQa();
    const result = executePdfPartsBulkAction(action);
    return {
      result,
      before,
      after: getPdfPartsManagerStateForQa(),
      selectedIds: selectedTopLevelObjects().map((object) => object.figureId)
    };
  }

  function layerHasProxyBadge(object) {
    if (isProxyBackedPanel(object)) return true;
    if (advancedFeatureProxyLayerMetaForObject(object)) return true;
    if (object?.importMeta?.advancedFeatureProxy || object?.importMeta?.advanced_feature_proxy) return true;
    if (object?.denseSvgAdvancedFeatureProxyMeta) return true;
    return groupChildren(object).some((child) => isProxyBackedPanel(child) || advancedFeatureProxyLayerMetaForObject(child));
  }

  function appendLayerBadge(meta, label, className = "", title = "") {
    const badge = document.createElement("span");
    badge.className = `layer-badge ${className}`.trim();
    badge.textContent = label;
    if (title) badge.title = title;
    meta.appendChild(badge);
    return badge;
  }

  function appendLayerProxyBadge(meta, object) {
    if (!layerHasProxyBadge(object)) return;
    appendLayerBadge(meta, "Proxy", "layer-badge-proxy", "Canvas uses a lightweight preview; export uses the source/full asset when available.");
  }

  function layerHasSourceBackedBadge(object) {
    if (!object) return false;
    if (nativePdfSourceForObject(object).available) return true;
    if (sourceBackedResultMeta(object)) return true;
    if (isDenseSvgProxyObject(object) || isProxyBackedPanel(object)) return true;
    if (advancedFeatureProxyLayerMetaForObject(object)) return true;
    const meta = object.importMeta || {};
    if (meta.sourceBacked || meta.source_backed || meta.sourceBackedFeatures || meta.source_backed_features) return true;
    return groupChildren(object).some((child) => nativePdfSourceForObject(child).available || sourceBackedResultMeta(child) || isProxyBackedPanel(child) || advancedFeatureProxyLayerMetaForObject(child));
  }

  function layerHasEditableVectorBadge(object) {
    if (!object) return false;
    if (isEditablePathObject(object)) return true;
    if (directEditableChildPaths(object).length > 0) return true;
    const pdfEntry = pdfEntrySummaryForObject(object);
    if (pdfEntry) return Number(pdfEntry.editability?.reconstructedObjectCount || 0) > 0;
    const meta = object.importMeta || {};
    return Boolean(meta.vectorPreserving || meta.vectorPreserved || meta.vector_preserving || meta.vector_preserved);
  }

  function appendLayerStructureBadges(meta, object) {
    if (isCompoundPathObject(object)) {
      appendLayerBadge(meta, "Compound", "layer-compound-badge", `${splitCompoundSubpaths(object.path).length.toLocaleString()} editable subpaths with an even-odd fill rule.`);
    }
    if (isAuthoredClippingMaskGroup(object)) {
      appendLayerBadge(meta, "Clip group", "layer-clipping-group-badge", "Editable Figure Tool clipping path and clipped contents.");
    }
    if (isGroupObject(object)) {
      appendLayerBadge(meta, "Group", "layer-structure-badge", `${groupChildren(object).length.toLocaleString()} child object${groupChildren(object).length === 1 ? "" : "s"}.`);
    }
    if (layerHasEditableVectorBadge(object)) {
      const editableCount = isEditablePathObject(object) ? 1 : directEditableChildPaths(object).length;
      appendLayerBadge(meta, editableCount ? "Edit" : "Vector", "layer-vector-badge", editableCount ? `${editableCount.toLocaleString()} editable path object${editableCount === 1 ? "" : "s"}.` : "Vector-preserving import.");
    }
    if (nativePdfDescriptorTreeForObject(object)) {
      appendLayerBadge(meta, "Native PDF", "layer-native-badge", "Native PDF provenance is available for bounded writer actions.");
    }
    if (layerHasSourceBackedBadge(object)) {
      appendLayerBadge(meta, "Source", "layer-source-badge", "Source-backed/provenance-backed object. Unsupported native features remain preserved rather than claimed editable.");
    }
  }

  function appendLayerClipMaskBadges(meta, object) {
    const inventory = clipMaskFeatureInventoryForObject(object);
    if (!inventory.hasFeatures) return;
    ["clip_path", "mask", "filter", "blend_mode"].forEach((feature) => {
      if (!inventory.featureTypes.includes(feature)) return;
      appendLayerBadge(
        meta,
        feature === "clip_path" ? "Clip" : feature === "blend_mode" ? "Blend" : clipMaskFeatureLabel(feature),
        `layer-feature-badge layer-feature-${feature.replace("_", "-")}`,
        `${clipMaskFeatureLabel(feature)} found. Editable items can be managed in Properties; other artwork remains preserved in the PDF.`
      );
    });
    const graph = nativePdfDescriptorTreeForObject(object)?.advanced_feature_graph || {};
    if (Array.isArray(graph.gradients) && graph.gradients.length) {
      appendLayerBadge(meta, "Gradient", "layer-feature-badge layer-feature-gradient", "Native gradient metadata detected; editing is limited to supported bounded writer actions.");
    } else if (gradientStopEditorMetaForObject(object)) {
      appendLayerBadge(meta, "Gradient", "layer-feature-badge layer-feature-gradient", "Released gradient stop editor object.");
    }
    if (Array.isArray(graph.patterns) && graph.patterns.length) {
      appendLayerBadge(meta, "Pattern", "layer-feature-badge layer-feature-pattern", "Native pattern metadata detected; editing is limited to supported bounded writer actions.");
    }
  }

  function renderLayerObject(object, selected, search = null, selectionPathIds = new Set()) {
      const item = document.createElement("div");
      const hidden = object.visible === false;
      const group = isGroupObject(object);
      const containsSelectedChild = group && inspectorObjectStack(object).slice(1).some((child) => selected.has(child.figureId));
      const collapsed = group ? (search?.active ? false : isLayerGroupCollapsed(object.figureId)) : false;
      const searchMatch = Boolean(search?.active && search.directIds?.has(object.figureId || ""));
      item.className = `layer-item${selected.has(object.figureId) ? " selected" : ""}${containsSelectedChild ? " contains-selected-child" : ""}${object.locked ? " locked" : ""}${hidden ? " hidden-object" : ""}${group ? " group-object" : ""}${searchMatch ? " search-match" : ""}`;
      item.dataset.layerId = object.figureId;
      if (object.figureStudioSvgGroupMeta?.sourceKey) {
        item.dataset.svgGroupKey = object.figureStudioSvgGroupMeta.sourceKey;
        item.dataset.svgGroupId = object.figureStudioSvgGroupMeta.id || "";
      }

      const main = document.createElement("div");
      main.className = "layer-main";

      const titleRow = document.createElement("div");
      titleRow.className = "layer-title-row";
      titleRow.appendChild(layerTreeDragHandle(object));
      if (group) {
        const toggle = layerButton(collapsed ? "Open" : "Close", object.figureId, "toggle-group", collapsed ? "Show group members" : "Hide group members");
        toggle.classList.add("layer-expand-button");
        titleRow.appendChild(toggle);
      }

      const name = document.createElement("input");
      name.className = "layer-name";
      const fullName = object.name || humanizeType(object.figureType);
      name.value = fullName;
      name.dataset.layerName = object.figureId;
      name.title = fullName;
      name.setAttribute("aria-label", `Rename ${fullName}`);
      if (inheritedMasterMeta(object)) name.readOnly = true;
      titleRow.appendChild(name);
      main.appendChild(titleRow);

      const meta = document.createElement("div");
      meta.className = "layer-meta";
      meta.textContent = object.figureStudioSvgGroupMeta
        ? ["SVG group", object.figureStudioSvgGroupMeta.id ? `#${object.figureStudioSvgGroupMeta.id}` : ""].filter(Boolean).join(" - ")
        : layerTypeLabel(object);
      appendLayerStructureBadges(meta, object);
      appendLayerProxyBadge(meta, object);
      appendLayerClipMaskBadges(meta, object);
      const tags = objectSelectionTags(object, { deep: false });
      if (tags.length) appendLayerBadge(meta, tags.slice(0, 2).join(", "), "object-tag-badge", `Semantic tags: ${tags.join(", ")}`);
      if (hidden) meta.appendChild(layerStateBadge("Hidden"));
      if (object.locked) meta.appendChild(layerStateBadge("Locked"));
      if (inheritedMasterMeta(object)) meta.appendChild(layerStateBadge("Inherited"));
      if (object.figureStudioMasterOverride) meta.appendChild(layerStateBadge("Local override"));
      main.appendChild(meta);
      item.appendChild(main);

      const actions = document.createElement("div");
      actions.className = "layer-actions";
      const selectButton = layerButton("Select", object.figureId, "select-on-canvas", "Select on canvas; fit in view if needed");
      const selectionUnavailableReason = layerTreeSelectionUnavailableReason(object);
      selectButton.disabled = Boolean(selectionUnavailableReason);
      if (selectionUnavailableReason) selectButton.title = selectionUnavailableReason;
      actions.appendChild(selectButton);
      const visibilityButton = layerButton(hidden ? "Show" : "Hide", object.figureId, "visible", hidden ? "Show object" : "Hide object");
      if (inheritedMasterMeta(object)) { visibilityButton.disabled = true; visibilityButton.title = "Choose Override to change this item on the slide."; }
      actions.appendChild(visibilityButton);
      const lockButton = layerButton(object.locked ? "Unlock" : "Lock", object.figureId, "lock", object.locked ? "Unlock object" : "Lock object");
      if (inheritedMasterMeta(object)) { lockButton.disabled = true; lockButton.title = "Inherited items stay locked. Choose Override to edit this slide."; }
      actions.appendChild(lockButton);
      actions.appendChild(layerButton("More", object.figureId, "menu", "Layer commands"));
      item.appendChild(actions);
      if (group && !collapsed) item.appendChild(renderLayerGroupChildren(object, 1, { rendered: 0 }, search, selectionPathIds));
      return item;
  }

  function ensureLayerState() {
    state.layers = state.layers || {};
    state.layers.collapsedBatches = state.layers.collapsedBatches || {};
    state.layers.collapsedGroups = state.layers.collapsedGroups || {};
    state.layers.pdfParts = normalizePdfPartsManagerFilters(state.layers.pdfParts);
  }

  function layerStateBadge(label) {
    const badge = document.createElement("span");
    badge.className = "layer-badge layer-state-badge";
    badge.textContent = label;
    return badge;
  }

  function isLayerGroupCollapsed(groupId) {
    ensureLayerState();
    return state.layers.collapsedGroups?.[groupId] !== false;
  }

  function layerChildButton(label, child, parent, action, title) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "layer-child-button";
    button.dataset.layerChildAction = action;
    button.title = title || label;
    button.setAttribute("aria-label", title || label);
    button.textContent = ["visible", "lock"].includes(action) ? "" : label;
    return button;
  }

  function layerTreeDragHandle(object) {
    const handle = document.createElement("button");
    handle.type = "button";
    handle.className = "layer-drag-handle";
    handle.textContent = "⋮⋮";
    handle.dataset.layerDragObjectId = object?.figureId || "";
    const reason = layerTreeProtectedReason(object, { deep: true });
    handle.draggable = !reason;
    handle.setAttribute("aria-disabled", String(Boolean(reason)));
    handle.setAttribute("aria-label", reason || `Move ${layerTreeObjectLabel(object)} in Layers`);
    handle.title = reason || `Drag ${layerTreeObjectLabel(object)} before, inside, or after another item`;
    if (reason) {
      handle.classList.add("disabled");
      handle.dataset.layerDragRejection = reason;
    }
    return handle;
  }

  function renderLayerGroupChildren(group, depth = 1, budget = { rendered: 0 }, search = null, selectionPathIds = new Set()) {
    const children = document.createElement("div");
    children.className = "layer-children";
    children.style.setProperty("--layer-tree-depth", String(depth));
    if (isAuthoredClippingMaskGroup(group) && group.clipPath) {
      const mask = ensureIsolationObjectIdentity(group.clipPath);
      const row = document.createElement("div");
      row.className = `layer-child-item clipping-path-child${pathNodeEdit.object === mask ? " selected" : ""}`;
      row.dataset.layerChildId = mask.figureId;
      row.dataset.layerParentId = group.figureId;
      row.dataset.layerClipPath = "true";
      row.title = "Edit clipping path with Direct Selection";
      const name = document.createElement("span");
      name.className = "layer-child-name";
      name.textContent = mask.name || "Clipping Path";
      const meta = document.createElement("span");
      meta.className = "layer-child-meta";
      meta.textContent = mask.inverted ? "Clipping path - inverted" : "Clipping path";
      row.append(name, meta);
      children.appendChild(row);
    }
    const allChildren = groupChildren(group).filter((child) => !search?.active || objectMatchesOrganizationSearch(child));
    allChildren.slice().reverse().forEach((child, displayIndex) => {
      const index = Math.max(0, allChildren.indexOf(child));
      if (budget.rendered >= LAYER_GROUP_CHILD_ROW_LIMIT && !layerTreeObjectOnSelectionPath(child, selectionPathIds)) return;
      ensureIsolationObjectIdentity(child, index);
      budget.rendered += 1;
      const branch = document.createElement("div");
      branch.className = "layer-child-branch";
      const row = document.createElement("div");
      const selected = selectedTopLevelObjects().includes(child);
      const nestedGroup = isGroupObject(child);
      const collapsed = nestedGroup ? (search?.active ? false : isLayerGroupCollapsed(child.figureId)) : false;
      const searchMatch = Boolean(search?.active && search.directIds?.has(child.figureId || ""));
      row.className = `layer-child-item${selected ? " selected" : ""}${child.visible === false ? " hidden-object" : ""}${child.locked ? " locked" : ""}${nestedGroup ? " group-child" : ""}${searchMatch ? " search-match" : ""}`;
      row.dataset.layerChildId = child.figureId;
      row.dataset.layerParentId = group.figureId;
      if (child.figureStudioSvgGroupMeta?.sourceKey) {
        row.dataset.svgGroupKey = child.figureStudioSvgGroupMeta.sourceKey;
        row.dataset.svgGroupId = child.figureStudioSvgGroupMeta.id || "";
      }
      row.style.setProperty("--layer-child-depth", String(depth));
      const fullName = child.name || `${humanizeType(child.figureType || child.type)} ${index + 1}`;
      row.title = `${fullName} - ${child.locked ? "unlock before editing" : "select inside group"}`;
      const identity = document.createElement("div");
      identity.className = "layer-child-identity";
      identity.appendChild(layerTreeDragHandle(child));
      if (nestedGroup) identity.appendChild(layerChildButton(collapsed ? "+" : "-", child, group, "toggle-group", collapsed ? "Show nested group" : "Hide nested group"));
      const name = document.createElement("input");
      name.className = "layer-child-name";
      name.value = fullName;
      name.dataset.layerChildName = child.figureId;
      name.dataset.layerParentId = group.figureId;
      name.title = fullName;
      name.setAttribute("aria-label", `Rename ${fullName}`);
      name.readOnly = Boolean(inheritedMasterMeta(child));
      identity.appendChild(name);
      const meta = document.createElement("span");
      meta.className = "layer-child-meta";
      meta.textContent = nestedGroup
        ? `${child.figureStudioSvgGroupMeta
          ? ["SVG group", child.figureStudioSvgGroupMeta.id ? `#${child.figureStudioSvgGroupMeta.id}` : ""].filter(Boolean).join(" - ")
          : "Group"} - ${groupChildren(child).length}`
        : child.figureType ? humanizeType(child.figureType) : humanizeType(child.type);
      identity.appendChild(meta);
      row.appendChild(identity);
      const actions = document.createElement("div");
      actions.className = "layer-child-actions";
      const selectButton = layerChildButton("Select", child, group, "select-on-canvas", "Select on canvas; fit in view if needed");
      const selectionUnavailableReason = layerTreeSelectionUnavailableReason(child);
      selectButton.disabled = Boolean(selectionUnavailableReason);
      if (selectionUnavailableReason) selectButton.title = selectionUnavailableReason;
      actions.appendChild(selectButton);
      actions.appendChild(layerChildButton(child.visible === false ? "Show" : "Hide", child, group, "visible", child.visible === false ? "Show object" : "Hide object"));
      actions.appendChild(layerChildButton(child.locked ? "Unlock" : "Lock", child, group, "lock", child.locked ? "Unlock object" : "Lock object"));
      actions.appendChild(layerChildButton("...", child, group, "menu", "Object commands"));
      row.appendChild(actions);
      branch.appendChild(row);
      if (nestedGroup && !collapsed) branch.appendChild(renderLayerGroupChildren(child, depth + 1, budget, search, selectionPathIds));
      children.appendChild(branch);
    });
    if (budget.rendered >= LAYER_GROUP_CHILD_ROW_LIMIT && depth === 1) {
      const note = document.createElement("div");
      note.className = "layer-window-note";
      note.textContent = "Additional nested objects are available through Isolation Mode.";
      children.appendChild(note);
    }
    return children;
  }

  function layerBatchMap(objects) {
    const map = new Map();
    objects.forEach((object) => {
      const batchId = releasedLayerBatchId(object);
      if (!batchId) return;
      if (!map.has(batchId)) map.set(batchId, []);
      map.get(batchId).push(object);
    });
    return map;
  }

  function releasedLayerBatchId(object) {
    const meta = object?.importMeta || {};
    const batchId = meta.importBatchId || object?.groupId || "";
    const partCount = Number(meta.importPartCount || 0) || 0;
    if (!batchId || partCount <= 1) return "";
    if (!meta.editableObjectImport || meta.editablePanelImport) return "";
    const mode = meta.importMode || meta.import_mode || "";
    if (![PDF_EDITABLE_VECTOR_IMPORT, PDF_LOCAL_SVG_VECTOR_IMPORT, PDF_JS_SVG_VECTOR_IMPORT, PDF_LIGHTWEIGHT_PART_IMPORT, PYMUPDF_SVG_VECTOR_IMPORT, SVG_VECTOR_GROUP_IMPORT, SCIENTIFIC_ASSET_VECTOR_IMPORT, USER_ASSET_VECTOR_IMPORT].includes(mode)) return "";
    return batchId;
  }

  function isLayerBatchCollapsed(batchId) {
    return state.layers?.collapsedBatches?.[batchId] !== false;
  }

  function renderLayerBatch(batchId, objects, selected) {
    const first = objects[0] || {};
    const hiddenCount = objects.filter((object) => object.visible === false).length;
    const lockedCount = objects.filter((object) => object.locked).length;
    const selectedCount = objects.filter((object) => selected.has(object.figureId)).length;
    const collapsed = isLayerBatchCollapsed(batchId);
    const item = document.createElement("div");
    item.className = `layer-item layer-batch${selectedCount ? " selected" : ""}${lockedCount === objects.length ? " locked" : ""}`;
    item.dataset.layerBatchId = batchId;

    const main = document.createElement("div");
    main.className = "layer-main";
    const name = document.createElement("div");
    name.className = "layer-name layer-batch-name";
    name.textContent = layerBatchName(objects);
    name.title = "Select released PDF parts";
    main.appendChild(name);

    const meta = document.createElement("div");
    meta.className = "layer-meta";
    const visibility = hiddenCount ? `, ${hiddenCount} hidden` : "";
    const locks = lockedCount ? `, ${lockedCount} locked` : "";
    const batchKind = releasedLayerBatchKind(objects);
    meta.textContent = `${objects.length} ${batchKind}${visibility}${locks}`;
    main.appendChild(meta);
    item.appendChild(main);

    const actions = document.createElement("div");
    actions.className = "layer-actions";
    actions.appendChild(layerBatchButton(collapsed ? "Open" : "Close", batchId, "toggle", collapsed ? "Show individual parts" : "Collapse individual parts"));
    actions.appendChild(layerBatchButton("Select", batchId, "select", "Select all parts in this batch"));
    actions.appendChild(layerBatchButton(hiddenCount === objects.length ? "Show" : "Hide", batchId, "visible", hiddenCount === objects.length ? "Show all parts" : "Hide all parts"));
    actions.appendChild(layerBatchButton(lockedCount === objects.length ? "Lock" : "Free", batchId, "lock", lockedCount === objects.length ? "Unlock all parts" : "Lock all parts"));
    item.appendChild(actions);
    return item;
  }

  function layerBatchName(objects) {
    const first = objects[0] || {};
    const meta = first.importMeta || {};
    const sourceName = meta.sourcePdfFilename || meta.sourceFilename || first.source?.filename || meta.releasedFromGroupName || first.name || "Vector group";
    const page = meta.pageNumber || meta.page || 1;
    const mode = meta.importMode || meta.import_mode || "";
    const prefix = releasedLayerBatchPrefix(mode);
    if ([PDF_EDITABLE_VECTOR_IMPORT, PDF_LOCAL_SVG_VECTOR_IMPORT, PDF_JS_SVG_VECTOR_IMPORT, PDF_LIGHTWEIGHT_PART_IMPORT, PYMUPDF_SVG_VECTOR_IMPORT].includes(mode)) {
      return `${prefix}: ${sourceName} page ${page}`;
    }
    return `${prefix}: ${sourceName}`;
  }

  function releasedLayerBatchKind(objects) {
    const mode = objects[0]?.importMeta?.importMode || objects[0]?.importMeta?.import_mode || "";
    if (mode === PDF_LIGHTWEIGHT_PART_IMPORT) return "lightweight PDF edits";
    if ([PDF_EDITABLE_VECTOR_IMPORT, PDF_LOCAL_SVG_VECTOR_IMPORT, PDF_JS_SVG_VECTOR_IMPORT, PYMUPDF_SVG_VECTOR_IMPORT].includes(mode)) return "released PDF parts";
    if (mode === SCIENTIFIC_ASSET_VECTOR_IMPORT) return "scientific asset parts";
    if (mode === USER_ASSET_VECTOR_IMPORT) return "saved asset parts";
    if (mode === SVG_VECTOR_GROUP_IMPORT) return "released SVG parts";
    return "released vector parts";
  }

  function releasedLayerBatchPrefix(mode) {
    if (mode === PDF_LIGHTWEIGHT_PART_IMPORT) return "PDF lightweight edits";
    if ([PDF_EDITABLE_VECTOR_IMPORT, PDF_LOCAL_SVG_VECTOR_IMPORT, PDF_JS_SVG_VECTOR_IMPORT, PYMUPDF_SVG_VECTOR_IMPORT].includes(mode)) return "PDF parts";
    if (mode === SCIENTIFIC_ASSET_VECTOR_IMPORT) return "Scientific asset parts";
    if (mode === USER_ASSET_VECTOR_IMPORT) return "My asset parts";
    if (mode === SVG_VECTOR_GROUP_IMPORT) return "SVG parts";
    return "Vector parts";
  }

  function layerButton(label, id, action, title) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = layerActionGlyph(action, label);
    button.title = title || label;
    button.setAttribute("aria-label", title || label);
    button.className = "layer-button";
    button.dataset.layerId = id;
    button.dataset.layerAction = action;
    return button;
  }

  function layerActionGlyph(action, fallback = "") {
    if (action === "visible" || action === "lock") return "";
    if (action === "menu") return "...";
    if (action === "toggle-group") return fallback === "Open" ? "+" : "-";
    return fallback;
  }

  function layerBatchButton(label, id, action, title) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = label;
    button.title = title || label;
    button.className = "layer-button";
    button.dataset.layerBatchId = id;
    button.dataset.layerBatchAction = action;
    return button;
  }

  function isFigureObject(object) {
    return object && object.figureId && !object.excludeFromExport;
  }

  function isReferenceObject(object) {
    return Boolean(
      object
      && (
        object.referenceMeta?.reference_only
        || object.source?.kind === "reference-only"
        || object.importMeta?.importMode === REFERENCE_IMAGE_IMPORT
        || object.figureType === "reference"
      )
    );
  }

  function getByFigureId(id) {
    return allCanvasObjectsDeep().find((object) => object.figureId === id);
  }

  function selectObjectById(id) {
    const object = getByFigureId(String(id || "").trim());
    if (!object) return false;
    setActiveObjects([object]);
    syncUi();
    showToast(`Selected ${object.name || humanizeType(object.figureType)}`);
    return true;
  }

  function layerBatchObjects(batchId) {
    if (!batchId) return [];
    return canvas.getObjects().filter((object) => releasedLayerBatchId(object) === batchId);
  }

  function isReleasedVectorPart(object) {
    const meta = object?.importMeta || {};
    const mode = meta.importMode || meta.import_mode || "";
    return Boolean(
      object
      && meta.editableObjectImport
      && !meta.editablePanelImport
      && VECTOR_PATH_RELEASE_IMPORT_MODES.has(mode)
      && (meta.releasedForPathEditing || meta.released_for_path_editing || meta.releasedFromGroupId || meta.releasedFromGroupName)
    );
  }

  function releasedVectorPartContext(object) {
    if (!isReleasedVectorPart(object)) return null;
    const batchId = releasedLayerBatchId(object);
    const batchObjects = layerBatchObjects(batchId);
    if (!batchId || !batchObjects.length) return null;
    const pathParts = batchObjects.filter((item) => isEditablePathObject(item) && pathNodeDescriptors(item).length && item.visible !== false && !item.locked);
    const partIndex = Math.max(0, batchObjects.indexOf(object));
    const pathIndex = Math.max(0, pathParts.indexOf(object));
    const meta = object.importMeta || {};
    const sourceName = meta.releasedFromGroupName || meta.sourceFilename || object.source?.filename || layerBatchName(batchObjects);
    return {
      batchId,
      batchObjects,
      pathParts,
      partIndex,
      pathIndex,
      sourceName,
      mode: meta.importMode || meta.import_mode || ""
    };
  }

  function appearanceColorHex(value, fallback = "#000000") {
    const raw = String(value || "").trim();
    const short = raw.match(/^#([0-9a-f]{3})$/i);
    if (short) return `#${short[1].split("").map((part) => `${part}${part}`).join("")}`.toLowerCase();
    if (/^#[0-9a-f]{6}$/i.test(raw)) return raw.toLowerCase();
    try {
      const hex = fabricRef?.Color ? new fabricRef.Color(raw).toHex() : "";
      if (/^[0-9a-f]{6}$/i.test(hex)) return `#${hex.toLowerCase()}`;
    } catch (_error) {
      // Unsupported paints stay outside the bounded solid-paint stack.
    }
    return fallback;
  }

  function appearancePaintVisible(value) {
    const paint = String(value || "").trim().toLowerCase();
    return Boolean(paint && paint !== "none" && paint !== "transparent" && paint !== "rgba(0,0,0,0)");
  }

  function normalizeAppearanceBlendMode(value) {
    const mode = String(value || "normal").trim().toLowerCase();
    return APPEARANCE_BLEND_MODES.includes(mode) ? mode : "normal";
  }

  function appearanceBlendModeToCanvas(value) {
    const mode = normalizeAppearanceBlendMode(value);
    return mode === "normal" ? "source-over" : mode;
  }

  function normalizeAppearanceGradientStops(value, primary = "#ffffff", secondary = "#0f8b8d") {
    const source = Array.isArray(value) && value.length >= 2
      ? value
      : [{ offset: 0, color: primary }, { offset: 1, color: secondary }];
    const usedIds = new Set();
    const stops = source.slice(0, 8).map((stop, index) => {
      let id = String(stop?.id || `stop-${index + 1}`).replace(/[^a-z0-9_-]+/gi, "-") || `stop-${index + 1}`;
      if (usedIds.has(id)) id = `${id}-${index + 1}`;
      usedIds.add(id);
      return {
      id,
      offset: clamp(Number(stop?.offset ?? index / Math.max(1, source.length - 1)), 0, 1),
      color: appearanceColorHex(stop?.color, index ? secondary : primary),
      swatchId: String(stop?.swatchId || stop?.swatch_id || ""),
      opacity: clamp(Number(stop?.opacity ?? 1), 0, 1),
      midpoint: clamp(Number(stop?.midpoint ?? 0.5), 0.01, 0.99)
    };
    }).sort((left, right) => left.offset - right.offset);
    if (stops.length < 2) return normalizeAppearanceGradientStops(null, primary, secondary);
    stops[0].offset = 0;
    stops[stops.length - 1].offset = 1;
    return stops;
  }

  function defaultAppearanceLinearGradientGeometry(angleValue = 0) {
    const angle = ((Number(angleValue || 0) % 360) + 360) % 360;
    const radians = angle * Math.PI / 180;
    const dx = Math.cos(radians) * 0.5;
    const dy = Math.sin(radians) * 0.5;
    return { angle, x1: 0.5 - dx, y1: 0.5 - dy, x2: 0.5 + dx, y2: 0.5 + dy };
  }

  function appearanceGradientRenderStops(value, primary = "#ffffff", secondary = "#0f8b8d") {
    const stops = normalizeAppearanceGradientStops(value, primary, secondary);
    const rendered = [];
    stops.slice(0, -1).forEach((stop, index) => {
      const next = stops[index + 1];
      if (!rendered.length) rendered.push({ offset: stop.offset, color: stop.color, opacity: stop.opacity });
      const midpointPercent = clamp(Number(stop.midpoint ?? 0.5) * 100, 1, 99);
      const exponent = pdfGradientExponentFromMidpoint(midpointPercent);
      if (Math.abs(exponent - 1) > 0.01) {
        [0.25, 0.5, 0.75].forEach((local) => {
          const progress = Math.pow(local, exponent);
          const startRgb = hexToRgb(stop.color) || { r: 0, g: 0, b: 0 };
          const endRgb = hexToRgb(next.color) || { r: 0, g: 0, b: 0 };
          const color = `#${["r", "g", "b"].map((channel) => (
            Math.round(startRgb[channel] + (endRgb[channel] - startRgb[channel]) * progress).toString(16).padStart(2, "0")
          )).join("")}`;
          rendered.push({
            offset: stop.offset + (next.offset - stop.offset) * local,
            color,
            opacity: stop.opacity + (next.opacity - stop.opacity) * progress
          });
        });
      }
      rendered.push({ offset: next.offset, color: next.color, opacity: next.opacity });
    });
    return rendered;
  }

  function sanitizePatternTileMarkup(value) {
    const markup = String(value || "");
    if (markup.length > 180000) return "";
    const cleaned = markup
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
      .replace(/<foreignObject\b[^>]*>[\s\S]*?<\/foreignObject>/gi, "")
      .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*')/gi, "")
      .replace(/\s(?:href|xlink:href)\s*=\s*("|')javascript:[\s\S]*?\1/gi, "");
    try {
      const parsed = new DOMParser().parseFromString(`<svg xmlns="http://www.w3.org/2000/svg">${cleaned}</svg>`, "image/svg+xml");
      return parsed.querySelector("parsererror") ? "" : cleaned;
    } catch {
      return "";
    }
  }

  function normalizePatternSourceBounds(value = {}) {
    return {
      left: Number.isFinite(Number(value.left)) ? Number(value.left) : 0,
      top: Number.isFinite(Number(value.top)) ? Number(value.top) : 0,
      width: clamp(Number(value.width) || 24, 1, 4096),
      height: clamp(Number(value.height) || 24, 1, 4096)
    };
  }

  function normalizeAppearancePattern(value, primary = "#26323d", secondary = "#ffffff") {
    const preset = String(value?.preset || "diagonal").toLowerCase();
    const kind = value?.kind === "vector" || value?.tileMarkup || value?.tile_markup ? "vector" : "preset";
    const sourceBounds = normalizePatternSourceBounds(value?.sourceBounds || value?.source_bounds);
    return {
      kind,
      preset: APPEARANCE_PATTERN_PRESETS.includes(preset) ? preset : "diagonal",
      libraryId: String(value?.libraryId || value?.library_id || ""),
      name: String(value?.name || "").trim().slice(0, 80),
      foreground: appearanceColorHex(value?.foreground, primary),
      background: appearanceColorHex(value?.background, secondary),
      foregroundSwatchId: String(value?.foregroundSwatchId || value?.foreground_swatch_id || ""),
      backgroundSwatchId: String(value?.backgroundSwatchId || value?.background_swatch_id || ""),
      scale: clamp(Number(value?.scale ?? 14), 6, 48),
      lineWidth: clamp(Number(value?.lineWidth ?? 1.5), 0.5, 8),
      tileMarkup: kind === "vector" ? sanitizePatternTileMarkup(value?.tileMarkup || value?.tile_markup) : "",
      sourceBounds,
      tileWidth: clamp(Number(value?.tileWidth ?? value?.tile_width ?? sourceBounds.width), 4, 512),
      tileHeight: clamp(Number(value?.tileHeight ?? value?.tile_height ?? sourceBounds.height), 4, 512),
      spacingX: clamp(Number(value?.spacingX ?? value?.spacing_x ?? 0), 0, 256),
      spacingY: clamp(Number(value?.spacingY ?? value?.spacing_y ?? 0), 0, 256),
      offsetX: clamp(Number(value?.offsetX ?? value?.offset_x ?? 0), -512, 512),
      offsetY: clamp(Number(value?.offsetY ?? value?.offset_y ?? 0), -512, 512),
      angle: ((Number(value?.angle || 0) % 360) + 360) % 360
    };
  }

  function normalizePatternSwatch(value, index = 0) {
    const pattern = normalizeAppearancePattern({ ...(value?.pattern || value), kind: "vector" });
    return {
      schema: PATTERN_SWATCH_SCHEMA,
      id: String(value?.id || pattern.libraryId || `pattern-${index + 1}`),
      name: String(value?.name || pattern.name || `Pattern ${index + 1}`).trim().slice(0, 80) || `Pattern ${index + 1}`,
      pattern: { ...pattern, kind: "vector" },
      source_object_ids: Array.isArray(value?.source_object_ids) ? value.source_object_ids.map(String).slice(0, 8) : [],
      created_at: String(value?.created_at || new Date().toISOString()),
      updated_at: String(value?.updated_at || value?.created_at || new Date().toISOString()),
      native_pdf_pattern_written: false,
      native_equivalent: false
    };
  }

  function normalizePatternLibrary(value) {
    const source = Array.isArray(value) ? value : value?.patterns;
    const seen = new Set();
    const patterns = (Array.isArray(source) ? source : []).slice(0, PATTERN_LIBRARY_MAX_ITEMS).map(normalizePatternSwatch).filter((entry) => {
      if (!entry.pattern.tileMarkup || seen.has(entry.id)) return false;
      seen.add(entry.id);
      entry.pattern.libraryId = entry.id;
      entry.pattern.name = entry.name;
      return true;
    });
    return { schema: PATTERN_LIBRARY_SCHEMA, patterns };
  }

  function serializePatternLibrary() {
    return cloneManifestValue(normalizePatternLibrary(patternLibrary), { schema: PATTERN_LIBRARY_SCHEMA, patterns: [] });
  }

  function findPatternSwatch(patternId) {
    return normalizePatternLibrary(patternLibrary).patterns.find((entry) => entry.id === patternId) || null;
  }

  function resolveAppearancePattern(value, primary = "#26323d", secondary = "#ffffff") {
    const descriptor = normalizeAppearancePattern(value, primary, secondary);
    if (descriptor.kind !== "vector" || descriptor.tileMarkup || !descriptor.libraryId) return descriptor;
    const linked = findPatternSwatch(descriptor.libraryId);
    if (!linked?.pattern?.tileMarkup) return descriptor;
    return normalizeAppearancePattern({
      ...linked.pattern,
      ...descriptor,
      tileMarkup: linked.pattern.tileMarkup,
      kind: "vector",
      libraryId: linked.id,
      name: descriptor.name || linked.name
    }, primary, secondary);
  }

  function compactPatternReferencesInValue(value) {
    const linked = new Map(normalizePatternLibrary(patternLibrary).patterns.map((entry) => [entry.id, entry.pattern.tileMarkup]));
    const visit = (item) => {
      if (Array.isArray(item)) return item.map(visit);
      if (!item || typeof item !== "object") return item;
      const clone = {};
      Object.entries(item).forEach(([key, child]) => {
        Object.defineProperty(clone, key, { value: visit(child), enumerable: true, writable: true, configurable: true });
      });
      const libraryId = String(clone.libraryId || clone.library_id || "");
      const markupKey = Object.prototype.hasOwnProperty.call(clone, "tileMarkup") ? "tileMarkup"
        : Object.prototype.hasOwnProperty.call(clone, "tile_markup") ? "tile_markup" : "";
      if (libraryId && markupKey && linked.has(libraryId) && sanitizePatternTileMarkup(clone[markupKey]) === linked.get(libraryId)) {
        clone[markupKey] = "";
        clone.kind = "vector";
      }
      return clone;
    };
    return visit(value);
  }

  function compactStrokeBrushReferencesInValue(value) {
    const selectedArtSources = new Map(normalizeStrokeBrushLibrary(strokeBrushLibrary).brushes
      .filter((brush) => brush.kind === "art" && brush.art.shape === "selected-art" && brush.art.sourceArtwork.pieces.length)
      .map((brush) => [brush.id, brush.art.sourceArtwork]));
    if (!selectedArtSources.size) return value;
    const visit = (item) => {
      if (Array.isArray(item)) return item.map(visit);
      if (!item || typeof item !== "object") return item;
      const clone = {};
      Object.entries(item).forEach(([key, child]) => {
        Object.defineProperty(clone, key, { value: visit(child), enumerable: true, writable: true, configurable: true });
      });
      const brushId = String(clone.brushId || clone.brush_id || "");
      const source = clone.art?.sourceArtwork || clone.art?.source_artwork;
      const linked = selectedArtSources.get(brushId);
      if (linked && source?.pieces?.length) {
        clone.art = {
          ...clone.art,
          shape: "selected-art",
          sourceArtwork: {
            schema: ART_BRUSH_SOURCE_SCHEMA,
            name: linked.name,
            referenceBrushId: brushId,
            sourceObjectIds: linked.sourceObjectIds,
            paths: linked.paths,
            pointCount: linked.pointCount,
            nativeEquivalent: false
          }
        };
        delete clone.art.source_artwork;
      }
      return clone;
    };
    return visit(value);
  }

  function compactReusableArtworkReferences(value) {
    return compactStrokeBrushReferencesInValue(compactPatternReferencesInValue(value));
  }

  function patternSelectionSources(selection = selectedTopLevelObjects()) {
    return (Array.isArray(selection) ? selection : []).filter((object) => canUseAppearanceStack(object) && !object.locked).slice(0, 8);
  }

  function selectionPatternSourceBounds(objects) {
    const rows = objects.map((object) => object.getBoundingRect?.()).filter(Boolean);
    const left = Math.min(...rows.map((row) => Number(row.left) || 0));
    const top = Math.min(...rows.map((row) => Number(row.top) || 0));
    const right = Math.max(...rows.map((row) => (Number(row.left) || 0) + Math.max(1, Number(row.width) || 1)));
    const bottom = Math.max(...rows.map((row) => (Number(row.top) || 0) + Math.max(1, Number(row.height) || 1)));
    return normalizePatternSourceBounds({ left, top, width: right - left, height: bottom - top });
  }

  function createPatternFromSelection(name = "", options = {}) {
    patternLibrary = normalizePatternLibrary(patternLibrary);
    const selected = Array.isArray(options.selection) ? options.selection : selectedTopLevelObjects();
    const sources = patternSelectionSources(selected);
    if (!sources.length || sources.length !== selected.length) {
      if (options.toast !== false) showToast("Select one to eight ordinary editable vectors for the tile");
      return { status: "unavailable", selectedCount: selected.length, eligibleCount: sources.length };
    }
    if (patternLibrary.patterns.length >= PATTERN_LIBRARY_MAX_ITEMS) {
      if (options.toast !== false) showToast(`Pattern library is limited to ${PATTERN_LIBRARY_MAX_ITEMS} tiles`);
      return { status: "limit", limit: PATTERN_LIBRARY_MAX_ITEMS };
    }
    const sourceBounds = selectionPatternSourceBounds(sources);
    const restoreSelection = selectedTopLevelObjects();
    if (String(canvas?.getActiveObject?.()?.type || "").toLowerCase() === "activeselection") {
      canvas.discardActiveObject();
      sources.forEach((object) => object.setCoords?.());
    }
    const tileMarkup = sanitizePatternTileMarkup(sources.map((object) => object.toSVG?.() || "").join(""));
    if (restoreSelection.length > 1) setActiveObjects(restoreSelection);
    if (!tileMarkup) return { status: "empty" };
    const patternName = String(name || `Pattern ${patternLibrary.patterns.length + 1}`).trim().slice(0, 80) || `Pattern ${patternLibrary.patterns.length + 1}`;
    const id = `pattern-${slugify(patternName) || "tile"}-${Date.now().toString(36)}`;
    const timestamp = new Date().toISOString();
    const pattern = normalizeAppearancePattern({
      kind: "vector",
      libraryId: id,
      name: patternName,
      tileMarkup,
      sourceBounds,
      tileWidth: clamp(sourceBounds.width, 8, 256),
      tileHeight: clamp(sourceBounds.height, 8, 256),
      spacingX: Math.min(24, Math.max(0, sourceBounds.width * 0.08)),
      spacingY: Math.min(24, Math.max(0, sourceBounds.height * 0.08)),
      background: "#ffffff"
    });
    const entry = normalizePatternSwatch({ id, name: patternName, pattern, source_object_ids: sources.map((object) => object.figureId || ""), created_at: timestamp, updated_at: timestamp });
    entry.source_object_ids = sources.map((object) => object.figureId || "").filter(Boolean);
    patternLibrary.patterns.push(entry);
    appearancePatternCache.clear();
    renderSwatchesPanel();
    if (options.history !== false) commitHistory("Pattern created");
    if (options.toast !== false) showToast(`Created vector pattern: ${entry.name}`);
    return { status: "ok", patternId: entry.id, name: entry.name, sourceObjectIds: entry.source_object_ids, pattern: cloneManifestValue(entry.pattern, {}) };
  }

  function patternLinkedUseCount(patternId) {
    let count = 0;
    allCanvasObjectsDeep().forEach((object) => {
      const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
      count += meta?.items.filter((item) => item.paintKind === "pattern" && item.pattern?.libraryId === patternId).length || 0;
    });
    graphicStyleLibrary.forEach((style) => {
      count += style.items.filter((item) => item.paintKind === "pattern" && item.pattern?.libraryId === patternId).length;
    });
    return count;
  }

  function syncLinkedPatternUses(patternId, descriptor, options = {}) {
    const pattern = normalizeAppearancePattern({ ...descriptor, kind: "vector", libraryId: patternId });
    let objectCount = 0;
    allCanvasObjectsDeep().forEach((object) => {
      const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
      if (!meta) return;
      let changed = false;
      meta.items = meta.items.map((item, index) => {
        if (item.paintKind !== "pattern" || item.pattern?.libraryId !== patternId) return item;
        changed = true;
        return normalizeAppearancePaintItem({ ...item, pattern }, index);
      });
      if (changed) {
        syncAppearanceStackPrimaryPaint(object, meta);
        objectCount += 1;
      }
    });
    graphicStyleLibrary = graphicStyleLibrary.map((style) => ({
      ...style,
      items: style.items.map((item, index) => item.paintKind === "pattern" && item.pattern?.libraryId === patternId
        ? normalizeAppearancePaintItem({ ...item, pattern }, index)
        : item)
    }));
    appearancePatternCache.clear();
    if (options.render !== false) canvas?.requestRenderAll?.();
    return objectCount;
  }

  function updatePatternSwatch(patternId, patch = {}, options = {}) {
    patternLibrary = normalizePatternLibrary(patternLibrary);
    const index = patternLibrary.patterns.findIndex((entry) => entry.id === patternId);
    if (index < 0) return { status: "missing", patternId };
    const current = patternLibrary.patterns[index];
    const name = patch.name == null ? current.name : String(patch.name || current.name).trim().slice(0, 80) || current.name;
    const patternPatch = patch.pattern || patch;
    const pattern = normalizeAppearancePattern({ ...current.pattern, ...patternPatch, kind: "vector", libraryId: patternId, name });
    const updated = normalizePatternSwatch({ ...current, name, pattern, updated_at: new Date().toISOString() }, index);
    updated.source_object_ids = current.source_object_ids || [];
    patternLibrary.patterns[index] = updated;
    const linkedObjectCount = syncLinkedPatternUses(patternId, pattern, { render: true });
    renderSwatchesPanel();
    renderMyAssetsDialogList();
    syncUi();
    if (options.history !== false) commitHistory(options.historyLabel || "Pattern updated");
    return { status: "ok", patternId, name, linkedObjectCount, pattern: cloneManifestValue(pattern, {}) };
  }

  function applyPatternSwatch(patternId, options = {}) {
    const entry = findPatternSwatch(patternId);
    if (!entry) return { status: "missing", patternId };
    const selection = Array.isArray(options.selection) ? options.selection : selectedTopLevelObjects();
    const eligible = selection.filter(canUseAppearanceStack);
    eligible.forEach((object) => {
      mutateAppearanceStack(object, "", (meta) => {
        let index = meta.items.findIndex((item) => item.id === meta.active_item_id && item.type === "fill");
        if (index < 0) index = meta.items.findIndex((item) => item.type === "fill");
        const item = normalizeAppearancePaintItem({
          ...(index >= 0 ? meta.items[index] : {}),
          id: index >= 0 ? meta.items[index].id : makeId("pattern-fill"),
          type: "fill",
          paintKind: "pattern",
          color: entry.pattern.foreground,
          opacity: index >= 0 ? meta.items[index].opacity : 1,
          pattern: entry.pattern,
          visible: true
        }, Math.max(0, index));
        if (index >= 0) meta.items[index] = item;
        else meta.items.unshift(item);
        meta.active_item_id = item.id;
      });
    });
    if (eligible.length && options.history !== false) commitHistory("Pattern applied");
    renderSwatchesPanel();
    if (options.toast !== false) showToast(eligible.length ? `Applied ${entry.name} to ${eligible.length} object${eligible.length === 1 ? "" : "s"}` : "Select an ordinary editable vector to apply the pattern");
    return { status: eligible.length ? "ok" : "unavailable", patternId, appliedCount: eligible.length, skippedCount: selection.length - eligible.length };
  }

  function deletePatternSwatch(patternId, options = {}) {
    patternLibrary = normalizePatternLibrary(patternLibrary);
    const index = patternLibrary.patterns.findIndex((entry) => entry.id === patternId);
    if (index < 0) return { status: "missing", patternId };
    const [removed] = patternLibrary.patterns.splice(index, 1);
    allCanvasObjectsDeep().forEach((object) => {
      const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
      if (!meta) return;
      let changed = false;
      meta.items = meta.items.map((item, itemIndex) => {
        if (item.paintKind !== "pattern" || item.pattern?.libraryId !== patternId) return item;
        changed = true;
        return normalizeAppearancePaintItem({ ...item, pattern: { ...item.pattern, libraryId: "", name: "" } }, itemIndex);
      });
      if (changed) syncAppearanceStackPrimaryPaint(object, meta);
    });
    graphicStyleLibrary = graphicStyleLibrary.map((style) => ({
      ...style,
      items: style.items.map((item, itemIndex) => item.paintKind === "pattern" && item.pattern?.libraryId === patternId
        ? normalizeAppearancePaintItem({ ...item, pattern: { ...item.pattern, libraryId: "", name: "" } }, itemIndex)
        : item)
    }));
    appearancePatternCache.clear();
    renderSwatchesPanel();
    syncUi();
    if (options.history !== false) commitHistory("Pattern deleted");
    return { status: "ok", patternId, name: removed.name };
  }

  function createPatternScenarioForQa() {
    if (!canvas) return { status: "not-ready" };
    if (appearancePatternEdit.active) cancelAppearancePatternEdit({ sync: false, toast: false });
    canvas.clear();
    canvas.backgroundColor = "#ffffff";
    patternLibrary = normalizePatternLibrary(null);
    const source = sourceMeta({ sourceId: "qa-vector-pattern", kind: "qa" });
    const petal = makeEllipse(126, 124, 52, 28, { fill: "#2a9d8f", stroke: "#173b4d", strokeWidth: 2 }, "Pattern petal", source);
    const center = makeEllipse(164, 140, 22, 22, { fill: "#f4a261", stroke: "#7b3f00", strokeWidth: 1.5 }, "Pattern center", source);
    const target = makeRect(360, 132, 360, 260, { fill: "#f8fafb", stroke: "#26323d", strokeWidth: 3 }, "Vector pattern target", source);
    [petal, center, target].forEach((object) => { applyLock(object, false); canvas.add(object); object.setCoords(); });
    setActiveObjects([petal, center]);
    const created = createPatternFromSelection("Cell scatter", { history: false, toast: false });
    canvas.setActiveObject(target);
    const applied = applyPatternSwatch(created.patternId, { history: false, toast: false });
    const style = saveGraphicStyleFromSelection("Cell scatter panel", { toast: false });
    commitHistory("Pattern QA scenario created");
    renderSwatchesPanel();
    syncUi();
    return {
      status: "ok",
      patternId: created.patternId,
      sourceObjectIds: [petal.figureId, center.figureId],
      targetObjectId: target.figureId,
      itemId: selectedAppearancePatternStateForObject(target)?.itemId || "",
      graphicStyleId: style.styleId || "",
      appliedCount: applied.appliedCount || 0
    };
  }

  function getPatternLibraryStateForQa() {
    const library = normalizePatternLibrary(patternLibrary);
    const selected = selectedTopLevelObjects()[0] || null;
    const selectedPattern = selectedAppearancePatternStateForObject(selected);
    return {
      schema: PATTERN_LIBRARY_SCHEMA,
      status: "ok",
      patternCount: library.patterns.length,
      patterns: library.patterns.map((entry) => ({
        id: entry.id,
        name: entry.name,
        linkedUseCount: patternLinkedUseCount(entry.id),
        sourceObjectIds: entry.source_object_ids || [],
        pattern: cloneManifestValue(entry.pattern, {}),
        nativePdfPatternWritten: false,
        nativeEquivalent: false
      })),
      selectedObjectId: selected?.figureId || "",
      selectedItemId: selectedPattern?.itemId || "",
      selectedPattern: cloneManifestValue(selectedPattern?.pattern || {}, {}),
      editor: getAppearancePatternEditStateForQa(),
      graphicStylePatternCount: graphicStyleLibrary.reduce((count, style) => count + style.items.filter((item) => item.paintKind === "pattern" && item.pattern?.kind === "vector").length, 0),
      nativePdfPatternWritten: false,
      nativeEquivalent: false
    };
  }

  function appearancePaintPrimaryColor(item, fallback = "#000000") {
    if (item?.type === "effect") return appearanceColorHex(item.color, fallback);
    if (item?.paintKind === "pattern") return appearanceColorHex(item.pattern?.foreground, fallback);
    if (item?.paintKind === "linear-gradient" || item?.paintKind === "radial-gradient") {
      return appearanceColorHex(item.gradient?.stops?.[0]?.color, fallback);
    }
    return appearanceColorHex(item?.color, fallback);
  }

  function appearancePaintSecondaryColor(item, fallback = "#ffffff") {
    if (item?.paintKind === "pattern") return appearanceColorHex(item.pattern?.background, fallback);
    if (item?.paintKind === "linear-gradient" || item?.paintKind === "radial-gradient") {
      return appearanceColorHex(item.gradient?.stops?.at(-1)?.color, fallback);
    }
    return fallback;
  }

  function normalizeAppearancePaintItem(item, index = 0) {
    const type = item?.type === "effect" ? "effect" : item?.type === "stroke" ? "stroke" : "fill";
    const blendMode = normalizeAppearanceBlendMode(item?.blendMode);
    if (type === "effect") {
      const effectKind = APPEARANCE_EFFECT_KINDS.includes(item?.effectKind) ? item.effectKind : "offset-copy";
      return {
        id: String(item?.id || `effect-${index + 1}`),
        type,
        effectKind,
        color: appearanceColorHex(item?.color, effectKind === "soft-shadow" ? "#26323d" : "#f4a261"),
        swatchId: String(item?.swatchId || item?.swatch_id || ""),
        opacity: clamp(Number(item?.opacity ?? (effectKind === "soft-shadow" ? 0.36 : 0.7)), 0, 1),
        visible: item?.visible !== false,
        blendMode,
        offsetX: clamp(Number(item?.offsetX ?? (effectKind === "soft-shadow" ? 8 : 12)), -96, 96),
        offsetY: clamp(Number(item?.offsetY ?? (effectKind === "soft-shadow" ? 8 : 12)), -96, 96),
        blur: effectKind === "soft-shadow" ? clamp(Number(item?.blur ?? 10), 1, 32) : 0,
        expandable: effectKind === "offset-copy"
      };
    }
    const dash = Array.isArray(item?.dashArray) ? item.dashArray.map(Number).filter((value) => Number.isFinite(value) && value >= 0).slice(0, 12) : [];
    const requestedKind = String(item?.paintKind || "solid").toLowerCase();
    const paintKind = APPEARANCE_PAINT_KINDS.includes(requestedKind) ? requestedKind : "solid";
    const color = appearanceColorHex(item?.color, type === "stroke" ? "#26323d" : "#ffffff");
    const gradient = normalizeAppearanceGradientStops(item?.gradient?.stops, color, item?.gradient?.stops?.at(-1)?.color || "#0f8b8d");
    const linearGeometry = defaultAppearanceLinearGradientGeometry(item?.gradient?.angle ?? 0);
    const hasLinearGeometry = ["x1", "y1", "x2", "y2"].every((key) => Number.isFinite(Number(item?.gradient?.[key])));
    const x1 = hasLinearGeometry ? clamp(Number(item.gradient.x1), -2, 3) : linearGeometry.x1;
    const y1 = hasLinearGeometry ? clamp(Number(item.gradient.y1), -2, 3) : linearGeometry.y1;
    const x2 = hasLinearGeometry ? clamp(Number(item.gradient.x2), -2, 3) : linearGeometry.x2;
    const y2 = hasLinearGeometry ? clamp(Number(item.gradient.y2), -2, 3) : linearGeometry.y2;
    const geometryAngle = hasLinearGeometry
      ? ((Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI) + 360) % 360
      : linearGeometry.angle;
    const pattern = normalizeAppearancePattern(item?.pattern, color, "#ffffff");
    return {
      id: String(item?.id || `paint-${index + 1}`),
      type,
      paintKind,
      color,
      swatchId: String(item?.swatchId || item?.swatch_id || ""),
      opacity: clamp(Number(item?.opacity ?? 1), 0, 1),
      visible: item?.visible !== false,
      blendMode,
      gradient: {
        stops: gradient,
        angle: geometryAngle,
        x1,
        y1,
        x2,
        y2,
        centerX: clamp(Number(item?.gradient?.centerX ?? 0.5), -1, 2),
        centerY: clamp(Number(item?.gradient?.centerY ?? 0.5), -1, 2),
        radius: clamp(Number(item?.gradient?.radius ?? 0.5), 0.05, 2),
        radialAngle: ((Number(item?.gradient?.radialAngle ?? 0) % 360) + 360) % 360
      },
      pattern,
      ...(type === "stroke" ? {
        width: clamp(Number(item?.width ?? 1), 0, 96),
        dashArray: dash,
        lineCap: normalizeStrokeLineCap(item?.lineCap || "round"),
        lineJoin: normalizeStrokeLineJoin(item?.lineJoin || "round"),
        miterLimit: Math.max(1, Number(item?.miterLimit || 10) || 10)
      } : {})
    };
  }

  function normalizeAppearanceStackMeta(meta) {
    if (!meta || meta.schema !== APPEARANCE_STACK_SCHEMA || !Array.isArray(meta.items)) return null;
    const items = meta.items.slice(0, APPEARANCE_STACK_MAX_ITEMS).map(normalizeAppearancePaintItem);
    const activeItemId = items.some((item) => item.id === meta.active_item_id)
      ? meta.active_item_id
      : items[0]?.id || "";
    return {
      schema: APPEARANCE_STACK_SCHEMA,
      order: "front-to-back",
      items,
      active_item_id: activeItemId,
      source_object_caching: meta.source_object_caching !== false,
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function defaultSwatchLibrary() {
    const groups = [
      { id: "swatch-group-scientific", name: "Scientific" },
      { id: "swatch-group-neutral", name: "Neutral" }
    ];
    const definitions = [
      ["global-teal", "Signal teal", "#2a9d8f", "global", groups[0].id],
      ["global-blue", "Data blue", "#2f6fb0", "global", groups[0].id],
      ["global-orange", "Highlight orange", "#f4a261", "global", groups[0].id],
      ["global-purple", "Pathway purple", "#7b61a8", "global", groups[0].id],
      ["global-red", "Alert red", "#d1495b", "global", groups[0].id],
      ["process-cyan", "Pale cyan", "#dff4f2", "process", groups[0].id],
      ["process-white", "White", "#ffffff", "process", groups[1].id],
      ["process-gray", "Mid gray", "#8a969f", "process", groups[1].id],
      ["process-charcoal", "Charcoal", "#26323d", "process", groups[1].id],
      ["process-black", "Black", "#000000", "process", groups[1].id]
    ];
    return {
      schema: SWATCH_LIBRARY_SCHEMA,
      groups,
      swatches: definitions.map(([id, name, color, kind, groupId]) => ({
        schema: SWATCH_SCHEMA,
        id,
        name,
        color,
        kind,
        groupId,
        createdAt: "",
        updatedAt: ""
      })),
      selected_swatch_id: definitions[0][0],
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function normalizeSwatchLibrary(value) {
    const fallback = defaultSwatchLibrary();
    const source = value?.schema === SWATCH_LIBRARY_SCHEMA ? value : null;
    if (!source) return fallback;
    const seenGroups = new Set();
    const groups = (Array.isArray(source.groups) ? source.groups : []).map((group, index) => {
      const id = String(group?.id || `swatch-group-${index + 1}`).trim().replace(/[^a-z0-9_-]+/gi, "-");
      if (!id || seenGroups.has(id)) return null;
      seenGroups.add(id);
      return { id, name: String(group?.name || `Color group ${index + 1}`).trim().slice(0, 60) || `Color group ${index + 1}` };
    }).filter(Boolean);
    if (!groups.length) groups.push(...fallback.groups);
    const groupIds = new Set(groups.map((group) => group.id));
    const seenSwatches = new Set();
    const swatches = (Array.isArray(source.swatches) ? source.swatches : []).slice(0, SWATCH_LIBRARY_MAX_ITEMS).map((swatch, index) => {
      let id = String(swatch?.id || `swatch-${index + 1}`).trim().replace(/[^a-z0-9_-]+/gi, "-");
      if (!id || seenSwatches.has(id)) id = `swatch-${index + 1}-${Date.now().toString(36)}`;
      seenSwatches.add(id);
      return {
        schema: SWATCH_SCHEMA,
        id,
        name: String(swatch?.name || `Swatch ${index + 1}`).trim().slice(0, 60) || `Swatch ${index + 1}`,
        color: appearanceColorHex(swatch?.color, "#000000"),
        kind: swatch?.kind === "global" ? "global" : "process",
        groupId: groupIds.has(swatch?.groupId) ? swatch.groupId : groups[0].id,
        createdAt: String(swatch?.createdAt || ""),
        updatedAt: String(swatch?.updatedAt || swatch?.createdAt || "")
      };
    }).filter(Boolean);
    if (!swatches.length) swatches.push(...fallback.swatches);
    const selectedId = swatches.some((swatch) => swatch.id === source.selected_swatch_id)
      ? source.selected_swatch_id
      : swatches[0]?.id || "";
    return {
      schema: SWATCH_LIBRARY_SCHEMA,
      groups,
      swatches,
      selected_swatch_id: selectedId,
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function serializeSwatchLibrary() {
    const library = normalizeSwatchLibrary(swatchLibrary);
    return {
      ...library,
      groups: library.groups.map((group) => ({ ...group })),
      swatches: library.swatches.map((swatch) => ({ ...swatch })),
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function findSwatch(swatchId) {
    return normalizeSwatchLibrary(swatchLibrary).swatches.find((swatch) => swatch.id === swatchId) || null;
  }

  function normalizeSwatchBindings(value) {
    const source = value?.schema === SWATCH_BINDING_SCHEMA ? value : {};
    const channels = source.channels && typeof source.channels === "object" ? source.channels : {};
    return {
      schema: SWATCH_BINDING_SCHEMA,
      channels: {
        fill: String(channels.fill || ""),
        stroke: String(channels.stroke || ""),
        text: String(channels.text || ""),
        arrowStart: String(channels.arrowStart || ""),
        arrowEnd: String(channels.arrowEnd || "")
      },
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function setObjectSwatchBinding(object, channel, swatchId) {
    if (!object) return;
    const bindings = normalizeSwatchBindings(object.figureStudioSwatchBindings);
    if (Object.prototype.hasOwnProperty.call(bindings.channels, channel)) bindings.channels[channel] = String(swatchId || "");
    object.figureStudioSwatchBindings = bindings;
    object.dirty = true;
  }

  function swatchRootIsSourceBacked(object) {
    return Boolean(
      object
      && (isReferenceObject(object)
        || isProxyBackedPanel(object)
        || isDenseSvgProxyObject(object)
        || nativePdfSourceForObject(object).available
        || pdfSourceIdForObject(object)
        || object.nativePdfSourceObjectId)
    );
  }

  function editableSwatchLeaves(selection = selectedTopLevelObjects()) {
    const leaves = [];
    const seen = new Set();
    const visit = (object) => {
      if (!object || seen.has(object) || object.locked || isReferenceObject(object)) return;
      seen.add(object);
      const semanticGroup = ["line", "arrow", "callout"].includes(String(object.figureType || ""));
      if (isGroupObject(object) && !semanticGroup) {
        groupChildren(object).forEach(visit);
        return;
      }
      const type = String(object.type || "").toLowerCase();
      if (supportsText(object) || ["line", "arrow", "callout"].includes(String(object.figureType || ""))
        || ["rect", "ellipse", "circle", "triangle", "path", "polygon", "polyline", "line"].includes(type)) leaves.push(object);
    };
    (selection || []).forEach((root) => {
      if (!swatchRootIsSourceBacked(root)) visit(root);
    });
    return leaves;
  }

  function allCanvasObjectsDeep() {
    const objects = [];
    const seen = new Set();
    const visit = (object) => {
      if (!object || seen.has(object)) return;
      seen.add(object);
      objects.push(object);
      groupChildren(object).forEach(visit);
    };
    (canvas?.getObjects?.() || []).forEach(visit);
    return objects;
  }

  function swatchIdsForObject(object) {
    const ids = new Set(Object.values(normalizeSwatchBindings(object?.figureStudioSwatchBindings).channels).filter(Boolean));
    const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
    (meta?.items || []).forEach((item) => {
      if (item.swatchId) ids.add(item.swatchId);
      if (item.pattern?.foregroundSwatchId) ids.add(item.pattern.foregroundSwatchId);
      if (item.pattern?.backgroundSwatchId) ids.add(item.pattern.backgroundSwatchId);
      (item.gradient?.stops || []).forEach((stop) => { if (stop.swatchId) ids.add(stop.swatchId); });
    });
    groupChildren(object).forEach((child) => swatchIdsForObject(child).forEach((id) => ids.add(id)));
    return ids;
  }

  function activeGradientStopTarget(options = {}) {
    const object = options.object || appearanceGradientEdit.object || selectedTopLevelObjects()[0];
    const itemId = options.itemId || appearanceGradientEdit.itemId || "";
    const selectedRole = String(options.stopId ? `stop:${options.stopId}` : appearanceGradientEdit.selected || "");
    if (!object || !itemId || !selectedRole.startsWith("stop:")) return null;
    return { object, itemId, stopId: selectedRole.slice(5) };
  }

  function applySwatchToObject(object, swatch, target = "fill", options = {}) {
    if (!object || !swatch || object.locked) return false;
    const swatchId = swatch.kind === "global" ? swatch.id : "";
    if (target === "gradient-stop") {
      const gradientTarget = activeGradientStopTarget({ ...options, object });
      if (!gradientTarget || gradientTarget.object !== object) return false;
      const stateForObject = selectedAppearanceGradientStateForObject(object, gradientTarget.itemId);
      const stops = stateForObject?.stops.map((stop) => stop.id === gradientTarget.stopId
        ? { ...stop, color: swatch.color, swatchId }
        : { ...stop });
      if (!stops) return false;
      updateAppearancePaint(object, gradientTarget.itemId, { gradient: { stops } }, { historyLabel: "" });
      syncAppearanceGradientEditFromObject(`stop:${gradientTarget.stopId}`);
      return true;
    }
    const meta = normalizeAppearanceStackMeta(object.figureStudioAppearanceStack);
    if (meta && ["fill", "stroke"].includes(target)) {
      const item = meta.items.find((entry) => entry.id === meta.active_item_id && entry.type === target)
        || meta.items.find((entry) => entry.type === target);
      if (item) {
        item.paintKind = "solid";
        item.color = swatch.color;
        item.swatchId = swatchId;
        syncAppearanceStackPrimaryPaint(object, meta);
        return true;
      }
    }
    if (target === "text" && !supportsText(object)) return false;
    if (["arrow-start", "arrow-end"].includes(target) && !["line", "arrow"].includes(String(object.figureType || ""))) return false;
    if (target === "stroke") {
      applyStylePatch(object, { stroke: swatch.color, strokeSwatchId: swatchId });
      setObjectSwatchBinding(object, "stroke", swatchId);
    } else if (target === "arrow-start") {
      applyStylePatch(object, { arrowStartFill: swatch.color, arrowStartSwatchId: swatchId });
      setObjectSwatchBinding(object, "arrowStart", swatchId);
    } else if (target === "arrow-end") {
      applyStylePatch(object, { arrowEndFill: swatch.color, arrowEndSwatchId: swatchId });
      setObjectSwatchBinding(object, "arrowEnd", swatchId);
    } else {
      applyStylePatch(object, { fill: swatch.color, fillSwatchId: swatchId });
      setObjectSwatchBinding(object, target === "text" ? "text" : "fill", swatchId);
    }
    return true;
  }

  function applySwatchToSelection(swatchId, target = swatchUiState.applyTarget, options = {}) {
    const swatch = findSwatch(swatchId);
    if (!swatch) return { status: "missing", swatchId };
    const requestedTarget = String(target || "fill");
    let targets = [];
    if (requestedTarget === "gradient-stop") {
      const gradientTarget = activeGradientStopTarget(options);
      if (gradientTarget) targets = [gradientTarget.object];
    } else {
      targets = editableSwatchLeaves(options.selection || selectedTopLevelObjects());
    }
    const applied = targets.filter((object) => applySwatchToObject(object, swatch, requestedTarget, options));
    swatchLibrary.selected_swatch_id = swatch.id;
    canvas.requestRenderAll();
    syncUi();
    renderSwatchesPanel();
    if (applied.length && options.history !== false) commitHistory(`Swatch applied to ${requestedTarget}`);
    if (options.toast !== false) {
      const skipped = Math.max(0, (options.selection || selectedTopLevelObjects()).length - applied.length);
      showToast(applied.length
        ? `${swatch.name} applied to ${applied.length} editable object${applied.length === 1 ? "" : "s"}${skipped ? `; ${skipped} unsupported or source-backed skipped` : ""}`
        : requestedTarget === "gradient-stop" ? "Select a gradient stop with the Gradient tool" : "Select ordinary editable artwork");
    }
    return { status: applied.length ? "ok" : "unavailable", swatchId, target: requestedTarget, appliedCount: applied.length };
  }

  function resolveGlobalSwatchLinks(options = {}) {
    const library = normalizeSwatchLibrary(swatchLibrary);
    const byId = new Map(library.swatches.filter((swatch) => swatch.kind === "global").map((swatch) => [swatch.id, swatch]));
    allCanvasObjectsDeep().forEach((object) => {
      const bindings = normalizeSwatchBindings(object.figureStudioSwatchBindings);
      const channelPatch = {};
      const channels = [
        ["fill", "fill", "fillSwatchId"], ["stroke", "stroke", "strokeSwatchId"],
        ["text", "fill", "textSwatchId"], ["arrowStart", "arrowStartFill", "arrowStartSwatchId"],
        ["arrowEnd", "arrowEndFill", "arrowEndSwatchId"]
      ];
      channels.forEach(([bindingKey, colorKey, idKey]) => {
        const swatch = byId.get(bindings.channels[bindingKey]);
        if (swatch) {
          channelPatch[colorKey] = swatch.color;
          channelPatch[idKey] = swatch.id;
        }
      });
      if (Object.keys(channelPatch).length && !object.locked) applyStylePatch(object, channelPatch);
      const meta = normalizeAppearanceStackMeta(object.figureStudioAppearanceStack);
      if (meta) {
        let changed = false;
        meta.items.forEach((item) => {
          const paintSwatch = byId.get(item.swatchId);
          if (paintSwatch) { item.color = paintSwatch.color; changed = true; }
          const foreground = byId.get(item.pattern?.foregroundSwatchId);
          const background = byId.get(item.pattern?.backgroundSwatchId);
          if (foreground) { item.pattern.foreground = foreground.color; changed = true; }
          if (background) { item.pattern.background = background.color; changed = true; }
          (item.gradient?.stops || []).forEach((stop) => {
            const stopSwatch = byId.get(stop.swatchId);
            if (stopSwatch) { stop.color = stopSwatch.color; changed = true; }
          });
        });
        if (changed) syncAppearanceStackPrimaryPaint(object, meta);
      }
    });
    graphicStyleLibrary.forEach((style) => {
      style.items.forEach((item) => {
        const paintSwatch = byId.get(item.swatchId);
        if (paintSwatch) item.color = paintSwatch.color;
        const foreground = byId.get(item.pattern?.foregroundSwatchId);
        const background = byId.get(item.pattern?.backgroundSwatchId);
        if (foreground) item.pattern.foreground = foreground.color;
        if (background) item.pattern.background = background.color;
        (item.gradient?.stops || []).forEach((stop) => {
          const stopSwatch = byId.get(stop.swatchId);
          if (stopSwatch) stop.color = stopSwatch.color;
        });
      });
    });
    if (options.render !== false) {
      canvas.requestRenderAll();
      syncUi();
      renderMyAssetsDialogList();
      renderSwatchesPanel();
    }
  }

  function addSwatch(options = {}) {
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    if (swatchLibrary.swatches.length >= SWATCH_LIBRARY_MAX_ITEMS) return { status: "limit", limit: SWATCH_LIBRARY_MAX_ITEMS };
    const name = String(options.name || `Swatch ${swatchLibrary.swatches.length + 1}`).trim().slice(0, 60);
    const timestamp = new Date().toISOString();
    const groupId = swatchLibrary.groups.some((group) => group.id === options.groupId) ? options.groupId : swatchLibrary.groups[0].id;
    const swatch = {
      schema: SWATCH_SCHEMA,
      id: String(options.id || `swatch-${slugify(name) || "color"}-${Date.now().toString(36)}`),
      name: name || "Swatch",
      color: appearanceColorHex(options.color, "#2a9d8f"),
      kind: options.kind === "process" ? "process" : "global",
      groupId,
      createdAt: timestamp,
      updatedAt: timestamp
    };
    swatchLibrary.swatches.push(swatch);
    swatchLibrary.selected_swatch_id = swatch.id;
    renderSwatchesPanel();
    if (options.history !== false) commitHistory("Swatch added");
    return { status: "ok", swatch: { ...swatch } };
  }

  function detachSwatchLinks(swatchId) {
    const requestedId = String(swatchId || "");
    if (!requestedId) return 0;
    let detached = 0;
    allCanvasObjectsDeep().forEach((object) => {
      const bindings = normalizeSwatchBindings(object.figureStudioSwatchBindings);
      let bindingChanged = false;
      Object.keys(bindings.channels).forEach((channel) => {
        if (bindings.channels[channel] === requestedId) {
          bindings.channels[channel] = "";
          bindingChanged = true;
          detached += 1;
        }
      });
      if (bindingChanged) object.figureStudioSwatchBindings = bindings;
      const meta = normalizeAppearanceStackMeta(object.figureStudioAppearanceStack);
      let appearanceChanged = false;
      (meta?.items || []).forEach((item) => {
        if (item.swatchId === requestedId) { item.swatchId = ""; appearanceChanged = true; detached += 1; }
        if (item.pattern?.foregroundSwatchId === requestedId) { item.pattern.foregroundSwatchId = ""; appearanceChanged = true; detached += 1; }
        if (item.pattern?.backgroundSwatchId === requestedId) { item.pattern.backgroundSwatchId = ""; appearanceChanged = true; detached += 1; }
        (item.gradient?.stops || []).forEach((stop) => {
          if (stop.swatchId === requestedId) { stop.swatchId = ""; appearanceChanged = true; detached += 1; }
        });
      });
      if (appearanceChanged) syncAppearanceStackPrimaryPaint(object, meta);
      if (bindingChanged || appearanceChanged) object.dirty = true;
    });
    graphicStyleLibrary.forEach((style) => {
      style.items.forEach((item) => {
        if (item.swatchId === requestedId) { item.swatchId = ""; detached += 1; }
        if (item.pattern?.foregroundSwatchId === requestedId) { item.pattern.foregroundSwatchId = ""; detached += 1; }
        if (item.pattern?.backgroundSwatchId === requestedId) { item.pattern.backgroundSwatchId = ""; detached += 1; }
        (item.gradient?.stops || []).forEach((stop) => {
          if (stop.swatchId === requestedId) { stop.swatchId = ""; detached += 1; }
        });
      });
    });
    return detached;
  }

  function updateSwatch(swatchId, patch = {}, options = {}) {
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    const swatch = swatchLibrary.swatches.find((entry) => entry.id === swatchId) || null;
    if (!swatch) return { status: "missing", swatchId };
    const previousKind = swatch.kind;
    if (patch.name != null) swatch.name = String(patch.name || "").trim().slice(0, 60) || swatch.name;
    if (patch.color != null) swatch.color = appearanceColorHex(patch.color, swatch.color);
    if (patch.kind != null) swatch.kind = patch.kind === "global" ? "global" : "process";
    if (patch.groupId != null && swatchLibrary.groups.some((group) => group.id === patch.groupId)) swatch.groupId = patch.groupId;
    swatch.updatedAt = new Date().toISOString();
    const detachedCount = previousKind === "global" && swatch.kind === "process" ? detachSwatchLinks(swatch.id) : 0;
    if (swatch.kind === "global" && patch.color != null) resolveGlobalSwatchLinks({ render: false });
    canvas.requestRenderAll();
    syncUi();
    renderMyAssetsDialogList();
    renderSwatchesPanel();
    if (options.history !== false) commitHistory("Swatch updated");
    return { status: "ok", swatch: { ...swatch }, detachedCount };
  }

  function deleteSwatch(swatchId, options = {}) {
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    const index = swatchLibrary.swatches.findIndex((swatch) => swatch.id === swatchId);
    if (index < 0) return { status: "missing", swatchId };
    const [removed] = swatchLibrary.swatches.splice(index, 1);
    const detachedCount = detachSwatchLinks(swatchId);
    if (swatchLibrary.selected_swatch_id === swatchId) swatchLibrary.selected_swatch_id = swatchLibrary.swatches[0]?.id || "";
    renderSwatchesPanel();
    if (options.history !== false) commitHistory("Swatch deleted");
    return { status: "ok", swatchId, name: removed.name, detachedCount };
  }

  function addSwatchGroup(name, options = {}) {
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    const cleanName = String(name || "").trim().slice(0, 60);
    if (!cleanName) return { status: "invalid" };
    const group = { id: `swatch-group-${slugify(cleanName) || "colors"}-${Date.now().toString(36)}`, name: cleanName };
    swatchLibrary.groups.push(group);
    swatchUiState.groupId = group.id;
    renderSwatchesPanel();
    if (options.history !== false) commitHistory("Color group added");
    return { status: "ok", group: { ...group } };
  }

  function selectSameArtwork(mode = "fill", options = {}) {
    const selected = selectedTopLevelObjects();
    if (!selected.length) return { status: "unavailable", count: 0 };
    const scope = options.scope || (isGroupIsolationActive() ? "isolation" : objectSelectionUiState.scope || "layer");
    const roots = organizationScopeObjects(scope, { editableOnly: true });
    const sourceObject = selected[0];
    let matcher = () => false;
    let label = "appearance";
    if (mode === "swatch") {
      const swatchId = [...swatchIdsForObject(sourceObject)][0] || "";
      if (!swatchId) return { status: "unavailable", reason: "no-global-swatch", count: 0 };
      matcher = (object) => swatchIdsForObject(object).has(swatchId);
      label = findSwatch(swatchId)?.name || "global swatch";
    } else if (["fill", "stroke"].includes(mode)) {
      const firstLeaf = editableSwatchLeaves([sourceObject]).find((object) => object.visible !== false) || sourceObject;
      const source = appearanceColorHex(readStyle(firstLeaf)?.[mode], "").toLowerCase();
      if (!source) return { status: "unavailable", reason: `no-${mode}`, count: 0 };
      matcher = (object) => editableSwatchLeaves([object]).some((leaf) => leaf.visible !== false && appearanceColorHex(readStyle(leaf)?.[mode], "").toLowerCase() === source);
      label = `${mode} ${source}`;
    } else if (mode === "type") {
      const source = String(sourceObject.figureType || sourceObject.type || "").toLowerCase();
      if (!source) return { status: "unavailable", reason: "no-type", count: 0 };
      matcher = (object) => String(object.figureType || object.type || "").toLowerCase() === source;
      label = humanizeType(sourceObject.figureType || sourceObject.type);
    } else if (mode === "text-style") {
      const source = objectTextStyleKeys(sourceObject)[0] || "";
      if (!source) return { status: "unavailable", reason: "no-text-style", count: 0 };
      matcher = (object) => objectTextStyleKeys(object).includes(source);
      label = "text style";
    } else if (mode === "component") {
      const source = componentInstanceMeta(sourceObject)?.componentId || "";
      if (!source) return { status: "unavailable", reason: "no-component", count: 0 };
      matcher = (object) => componentInstanceMeta(object)?.componentId === source;
      label = "component";
    } else if (mode === "tag") {
      const sourceTags = objectSelectionTags(sourceObject).map((tag) => tag.toLowerCase());
      if (!sourceTags.length) return { status: "unavailable", reason: "no-semantic-tag", count: 0 };
      const sourceTag = sourceTags[0];
      matcher = (object) => objectSelectionTags(object).some((tag) => tag.toLowerCase() === sourceTag);
      label = `tag ${sourceTags[0]}`;
    }
    const matches = roots.filter(matcher);
    if (matches.length) setActiveObjects(matches);
    syncUi();
    if (options.toast !== false) showToast(matches.length ? `Selected ${matches.length} object${matches.length === 1 ? "" : "s"} with ${label}` : `No editable artwork uses ${label} in this scope`);
    return { status: matches.length ? "ok" : "empty", mode, scope, count: matches.length, objectIds: matches.map((object) => object.figureId || "") };
  }

  function swatchGroupOptionsHtml(selectedId, includeAll = false) {
    const library = normalizeSwatchLibrary(swatchLibrary);
    return `${includeAll ? `<option value="all" ${selectedId === "all" ? "selected" : ""}>All groups</option>` : ""}${library.groups.map((group) => (
      `<option value="${escapeHtml(group.id)}" ${group.id === selectedId ? "selected" : ""}>${escapeHtml(group.name)}</option>`
    )).join("")}`;
  }

  function renderSwatchCard(swatch) {
    const selected = swatchLibrary.selected_swatch_id === swatch.id;
    return `
      <article class="swatch-library-item ${selected ? "selected" : ""}" data-swatch-id="${escapeHtml(swatch.id)}" role="option" aria-selected="${selected}">
        <button type="button" class="swatch-library-chip" data-swatch-apply="${escapeHtml(swatch.id)}" style="--swatch-color:${escapeHtml(swatch.color)}" title="Apply ${escapeHtml(swatch.name)}"><span></span></button>
        <div class="swatch-library-copy">
          <input type="text" value="${escapeHtml(swatch.name)}" maxlength="60" data-swatch-name="${escapeHtml(swatch.id)}" aria-label="Color name">
          <span>${swatch.kind === "global" ? "Global color" : "Process color"}</span>
        </div>
        <input type="color" value="${escapeHtml(swatch.color)}" data-swatch-color="${escapeHtml(swatch.id)}" aria-label="${escapeHtml(swatch.name)} color">
        <select data-swatch-kind="${escapeHtml(swatch.id)}" aria-label="${escapeHtml(swatch.name)} behavior">
          <option value="global" ${swatch.kind === "global" ? "selected" : ""}>Global</option>
          <option value="process" ${swatch.kind === "process" ? "selected" : ""}>Process</option>
        </select>
        <select data-swatch-group="${escapeHtml(swatch.id)}" aria-label="${escapeHtml(swatch.name)} color group">${swatchGroupOptionsHtml(swatch.groupId)}</select>
        <button type="button" class="swatch-library-delete" data-swatch-delete="${escapeHtml(swatch.id)}" title="Delete ${escapeHtml(swatch.name)}" aria-label="Delete ${escapeHtml(swatch.name)}">x</button>
      </article>`;
  }

  function patternPreviewDataUrl(patternValue) {
    const pattern = resolveAppearancePattern(patternValue);
    const width = Math.max(4, pattern.tileWidth + pattern.spacingX);
    const height = Math.max(4, pattern.tileHeight + pattern.spacingY);
    const bounds = pattern.sourceBounds;
    const scaleX = pattern.tileWidth / Math.max(1, bounds.width);
    const scaleY = pattern.tileHeight / Math.max(1, bounds.height);
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${fmt(width, 2)}" height="${fmt(height, 2)}" viewBox="0 0 ${fmt(width, 2)} ${fmt(height, 2)}"><rect width="100%" height="100%" fill="${escapeHtml(pattern.background)}"/><g transform="scale(${fmt(scaleX, 6)} ${fmt(scaleY, 6)}) translate(${fmt(-bounds.left, 3)} ${fmt(-bounds.top, 3)})">${pattern.tileMarkup}</g></svg>`;
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  }

  function renderPatternLibraryCard(entry) {
    const linked = patternLinkedUseCount(entry.id);
    const preview = patternPreviewDataUrl(entry.pattern);
    const selected = selectedTopLevelObjects();
    const selectedPattern = selected.length === 1 ? selectedAppearancePatternStateForObject(selected[0]) : null;
    const canEdit = selectedPattern?.pattern.libraryId === entry.id;
    return `
      <article class="pattern-library-item" data-pattern-id="${escapeHtml(entry.id)}">
        <button type="button" class="pattern-library-preview" data-pattern-apply="${escapeHtml(entry.id)}" title="Apply ${escapeHtml(entry.name)}" aria-label="Apply ${escapeHtml(entry.name)}" style="--pattern-preview:url(&quot;${escapeHtml(preview)}&quot;)"></button>
        <div class="pattern-library-copy">
          <input type="text" value="${escapeHtml(entry.name)}" maxlength="80" data-pattern-name="${escapeHtml(entry.id)}" aria-label="Pattern name">
          <span>Vector tile / ${linked} linked use${linked === 1 ? "" : "s"}</span>
        </div>
        <button type="button" data-pattern-edit="${escapeHtml(entry.id)}" ${canEdit ? "" : "disabled"}>Edit</button>
        <button type="button" class="pattern-library-delete" data-pattern-delete="${escapeHtml(entry.id)}" title="Delete ${escapeHtml(entry.name)}" aria-label="Delete ${escapeHtml(entry.name)}">&times;</button>
      </article>`;
  }

  function renderSwatchesPanel() {
    if (!els.swatchGrid) return;
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    const validGroup = swatchUiState.groupId === "all" || swatchLibrary.groups.some((group) => group.id === swatchUiState.groupId);
    if (!validGroup) swatchUiState.groupId = "all";
    if (els.swatchGroupFilter) els.swatchGroupFilter.innerHTML = swatchGroupOptionsHtml(swatchUiState.groupId, true);
    if (els.swatchGroupInput) els.swatchGroupInput.innerHTML = swatchGroupOptionsHtml(swatchLibrary.groups[0]?.id || "");
    if (els.swatchApplyTarget) els.swatchApplyTarget.value = swatchUiState.applyTarget;
    const visible = swatchLibrary.swatches.filter((swatch) => swatchUiState.groupId === "all" || swatch.groupId === swatchUiState.groupId);
    els.swatchGrid.innerHTML = visible.length ? visible.map(renderSwatchCard).join("") : `<div class="swatch-library-empty">No saved colors in this group.</div>`;
    if (els.swatchLibrarySummary) {
      const linkedObjects = allCanvasObjectsDeep().filter((object) => swatchIdsForObject(object).size).length;
      els.swatchLibrarySummary.textContent = `${swatchLibrary.swatches.length} colors / ${swatchLibrary.groups.length} groups / ${linkedObjects} linked objects`;
    }
    if (els.collectSelectionColorsBtn) els.collectSelectionColorsBtn.disabled = editableSwatchLeaves().length === 0;
    if (els.recolorSelectionBtn) els.recolorSelectionBtn.disabled = editableSwatchLeaves().length === 0;
    patternLibrary = normalizePatternLibrary(patternLibrary);
    if (els.patternLibraryGrid) els.patternLibraryGrid.innerHTML = patternLibrary.patterns.length
      ? patternLibrary.patterns.map(renderPatternLibraryCard).join("")
      : `<div class="swatch-library-empty">Select ordinary vectors, then create a reusable tile.</div>`;
    if (els.patternLibrarySummary) els.patternLibrarySummary.textContent = `${patternLibrary.patterns.length} named vector tile${patternLibrary.patterns.length === 1 ? "" : "s"}`;
    if (els.createPatternFromSelectionBtn) {
      const selection = selectedTopLevelObjects();
      els.createPatternFromSelectionBtn.disabled = !selection.length || selection.length > 8 || patternSelectionSources(selection).length !== selection.length || patternLibrary.patterns.length >= PATTERN_LIBRARY_MAX_ITEMS;
    }
    renderRecolorWorkspace();
  }

  function announceSwatches(message) {
    if (els.swatchLibraryStatus) els.swatchLibraryStatus.textContent = message || "";
  }

  function openSwatchesPanel(options = {}) {
    state.ui.rightInspectorVisible = true;
    setRailVisibility("right", true, { toast: false, focus: false });
    setInspectorTab("swatches");
    renderSwatchesPanel();
    if (options.recolor) beginRecolorSelection(options);
    requestAnimationFrame(() => (options.recolor ? els.recolorMappingList?.querySelector("input, select") : els.swatchGrid?.querySelector("[data-swatch-apply]"))?.focus());
    return getSwatchLibraryStateForQa();
  }

  function addColorValue(set, value) {
    const raw = String(value || "").trim();
    if (!appearancePaintVisible(raw)) return;
    const color = appearanceColorHex(raw, "");
    if (color) set.add(color.toLowerCase());
  }

  function colorsForSwatchObject(object) {
    const colors = new Set();
    const style = readStyle(object);
    [style.fill, style.stroke, style.arrowStartFill, style.arrowEndFill].forEach((value) => addColorValue(colors, value));
    const meta = normalizeAppearanceStackMeta(object.figureStudioAppearanceStack);
    (meta?.items || []).forEach((item) => {
      addColorValue(colors, item.color);
      addColorValue(colors, item.pattern?.foreground);
      addColorValue(colors, item.pattern?.background);
      (item.gradient?.stops || []).forEach((stop) => addColorValue(colors, stop.color));
    });
    return colors;
  }

  function collectSelectionColorsAsSwatches(options = {}) {
    const colors = new Set();
    editableSwatchLeaves(options.selection || selectedTopLevelObjects()).forEach((object) => colorsForSwatchObject(object).forEach((color) => colors.add(color)));
    if (!colors.size) return { status: "unavailable", addedCount: 0 };
    swatchLibrary = normalizeSwatchLibrary(swatchLibrary);
    let group = swatchLibrary.groups.find((entry) => entry.name === "Collected");
    if (!group) {
      group = { id: "swatch-group-collected", name: "Collected" };
      swatchLibrary.groups.push(group);
    }
    const existing = new Set(swatchLibrary.swatches.map((swatch) => swatch.color.toLowerCase()));
    const added = [...colors].filter((color) => !existing.has(color)).map((color, index) => addSwatch({
      name: `Collected ${index + 1}`,
      color,
      kind: "process",
      groupId: group.id,
      history: false
    }).swatch).filter(Boolean);
    swatchUiState.groupId = group.id;
    renderSwatchesPanel();
    if (added.length && options.history !== false) commitHistory("Selection colors collected");
    if (options.toast !== false) showToast(added.length ? `Added ${added.length} selection color${added.length === 1 ? "" : "s"}` : "Those colors are already in Saved colors");
    return { status: added.length ? "ok" : "unchanged", addedCount: added.length, colors: added.map((swatch) => swatch.color) };
  }

  function isNeutralRecolor(color) {
    const rgb = hexToRgb(appearanceColorHex(color, "#000000"));
    return Boolean(rgb && Math.max(rgb.r, rgb.g, rgb.b) - Math.min(rgb.r, rgb.g, rgb.b) <= 4);
  }

  function captureRecolorObject(object) {
    return {
      object,
      style: cloneManifestValue(readStyle(object), {}),
      styleMeta: cloneManifestValue(object.styleMeta || null, null),
      appearance: cloneManifestValue(normalizeAppearanceStackMeta(object.figureStudioAppearanceStack), null),
      bindings: cloneManifestValue(normalizeSwatchBindings(object.figureStudioSwatchBindings), null)
    };
  }

  function restoreRecolorSnapshots(snapshots = recolorSelectionState?.snapshots || []) {
    snapshots.forEach((snapshot) => {
      const object = snapshot.object;
      if (!object) return;
      applyStylePatch(object, cloneManifestValue(snapshot.style, {}));
      object.styleMeta = cloneManifestValue(snapshot.styleMeta, null);
      object.figureStudioSwatchBindings = cloneManifestValue(snapshot.bindings, null);
      if (snapshot.appearance) syncAppearanceStackPrimaryPaint(object, cloneManifestValue(snapshot.appearance, null));
      else delete object.figureStudioAppearanceStack;
      object.dirty = true;
    });
    canvas.requestRenderAll();
  }

  function recolorMappingFor(sourceColor) {
    const source = appearanceColorHex(sourceColor, "").toLowerCase();
    const mapping = recolorSelectionState?.mappings?.[source];
    if (!mapping || (recolorSelectionState.preserveNeutrals && isNeutralRecolor(source))) return { color: source, swatchId: "" };
    const swatch = findSwatch(mapping.swatchId);
    return {
      color: swatch?.color || appearanceColorHex(mapping.color, source),
      swatchId: swatch?.kind === "global" ? swatch.id : ""
    };
  }

  function recolorValue(value) {
    const source = appearanceColorHex(value, "").toLowerCase();
    return source ? recolorMappingFor(source) : { color: value, swatchId: "" };
  }

  function applyRecolorMappingToObject(object) {
    const style = readStyle(object);
    const fill = recolorValue(style.fill);
    const stroke = recolorValue(style.stroke);
    const arrowStart = recolorValue(style.arrowStartFill);
    const arrowEnd = recolorValue(style.arrowEndFill);
    applyStylePatch(object, {
      fill: fill.color,
      fillSwatchId: supportsText(object) ? "" : fill.swatchId,
      textSwatchId: supportsText(object) ? fill.swatchId : "",
      stroke: stroke.color,
      strokeSwatchId: stroke.swatchId,
      arrowStartFill: arrowStart.color,
      arrowStartSwatchId: arrowStart.swatchId,
      arrowEndFill: arrowEnd.color,
      arrowEndSwatchId: arrowEnd.swatchId
    });
    const meta = normalizeAppearanceStackMeta(object.figureStudioAppearanceStack);
    if (!meta) return;
    meta.items.forEach((item) => {
      const primary = recolorValue(item.color);
      item.color = primary.color;
      item.swatchId = primary.swatchId;
      if (item.pattern) {
        const foreground = recolorValue(item.pattern.foreground);
        const background = recolorValue(item.pattern.background);
        item.pattern.foreground = foreground.color;
        item.pattern.foregroundSwatchId = foreground.swatchId;
        item.pattern.background = background.color;
        item.pattern.backgroundSwatchId = background.swatchId;
      }
      (item.gradient?.stops || []).forEach((stop) => {
        const mapped = recolorValue(stop.color);
        stop.color = mapped.color;
        stop.swatchId = mapped.swatchId;
      });
    });
    syncAppearanceStackPrimaryPaint(object, meta);
  }

  function previewRecolorSelection(options = {}) {
    if (!recolorSelectionState) return { status: "inactive" };
    if (options.preserveNeutrals != null) recolorSelectionState.preserveNeutrals = options.preserveNeutrals !== false;
    restoreRecolorSnapshots();
    recolorSelectionState.snapshots.forEach((snapshot) => applyRecolorMappingToObject(snapshot.object));
    canvas.requestRenderAll();
    renderRecolorWorkspace();
    return getRecolorSelectionStateForQa();
  }

  function updateRecolorMapping(sourceColor, patch = {}, options = {}) {
    if (!recolorSelectionState) return { status: "inactive" };
    const source = appearanceColorHex(sourceColor, "").toLowerCase();
    if (!recolorSelectionState.mappings[source]) return { status: "missing", sourceColor: source };
    recolorSelectionState.mappings[source] = {
      color: appearanceColorHex(patch.color ?? recolorSelectionState.mappings[source].color, source),
      swatchId: String((patch.swatchId ?? recolorSelectionState.mappings[source].swatchId) || "")
    };
    return options.preview === false ? getRecolorSelectionStateForQa() : previewRecolorSelection();
  }

  function beginRecolorSelection(options = {}) {
    if (recolorSelectionState) cancelRecolorSelection({ toast: false });
    const leaves = editableSwatchLeaves(options.selection || selectedTopLevelObjects());
    const colors = new Set();
    leaves.forEach((object) => colorsForSwatchObject(object).forEach((color) => colors.add(color)));
    if (!leaves.length || !colors.size) {
      if (options.toast !== false) showToast("Select ordinary editable colored artwork");
      return { status: "unavailable", editableCount: leaves.length, colorCount: colors.size };
    }
    recolorSelectionState = {
      schema: "figureStudio.recolorSelection.v1",
      snapshots: leaves.map(captureRecolorObject),
      mappings: Object.fromEntries([...colors].sort().map((color) => [color, { color, swatchId: "" }])),
      preserveNeutrals: options.preserveNeutrals !== false,
      startedAt: new Date().toISOString()
    };
    if (els.recolorWorkspace) els.recolorWorkspace.hidden = false;
    renderRecolorWorkspace();
    return getRecolorSelectionStateForQa();
  }

  function cancelRecolorSelection(options = {}) {
    if (!recolorSelectionState) return { status: "inactive" };
    const count = recolorSelectionState.snapshots.length;
    restoreRecolorSnapshots();
    recolorSelectionState = null;
    if (els.recolorWorkspace) els.recolorWorkspace.hidden = true;
    renderSwatchesPanel();
    syncUi();
    if (options.toast !== false) showToast("Recolor preview cancelled");
    return { status: "cancelled", restoredCount: count };
  }

  function commitRecolorSelection(options = {}) {
    if (!recolorSelectionState) return { status: "inactive" };
    const count = recolorSelectionState.snapshots.length;
    const mappings = cloneManifestValue(recolorSelectionState.mappings, {});
    recolorSelectionState = null;
    if (els.recolorWorkspace) els.recolorWorkspace.hidden = true;
    renderSwatchesPanel();
    syncUi();
    if (options.history !== false) commitHistory("Selection recolored");
    if (options.toast !== false) showToast(`Recolored ${count} editable object${count === 1 ? "" : "s"}`);
    return { status: "ok", recoloredCount: count, mappings };
  }

  function getRecolorSelectionStateForQa() {
    if (!recolorSelectionState) return { status: "inactive", active: false };
    return {
      status: "ok",
      active: true,
      editableCount: recolorSelectionState.snapshots.length,
      colorCount: Object.keys(recolorSelectionState.mappings).length,
      preserveNeutrals: recolorSelectionState.preserveNeutrals,
      mappings: cloneManifestValue(recolorSelectionState.mappings, {}),
      nativePdfStreamMutated: false,
      nativeEquivalent: false
    };
  }

  function renderRecolorWorkspace() {
    if (!els.recolorWorkspace || !els.recolorMappingList) return;
    els.recolorWorkspace.hidden = !recolorSelectionState;
    if (!recolorSelectionState) return;
    const swatchOptions = normalizeSwatchLibrary(swatchLibrary).swatches.map((swatch) => `<option value="${escapeHtml(swatch.id)}">${escapeHtml(swatch.name)}${swatch.kind === "global" ? " / Global" : ""}</option>`).join("");
    els.recolorPreserveNeutrals.checked = recolorSelectionState.preserveNeutrals;
    if (els.recolorSummary) els.recolorSummary.textContent = `${recolorSelectionState.snapshots.length} objects / ${Object.keys(recolorSelectionState.mappings).length} colors`;
    els.recolorMappingList.innerHTML = Object.entries(recolorSelectionState.mappings).map(([source, mapping]) => `
      <div class="recolor-mapping-row" data-recolor-source="${escapeHtml(source)}">
        <span class="recolor-source-chip" style="--recolor-source:${escapeHtml(source)}" title="Original ${escapeHtml(source)}"></span>
        <span class="recolor-arrow">to</span>
        <input type="color" value="${escapeHtml(mapping.color)}" data-recolor-color="${escapeHtml(source)}" aria-label="Replacement for ${escapeHtml(source)}">
        <select data-recolor-swatch="${escapeHtml(source)}" aria-label="Saved replacement color for ${escapeHtml(source)}">
          <option value="">Custom color</option>${swatchOptions}
        </select>
      </div>`).join("");
    Object.entries(recolorSelectionState.mappings).forEach(([source, mapping]) => {
      const select = els.recolorMappingList.querySelector(`[data-recolor-swatch="${window.CSS?.escape ? window.CSS.escape(source) : source}"]`);
      if (select) select.value = mapping.swatchId || "";
    });
  }

  function getSwatchLibraryStateForQa() {
    const library = normalizeSwatchLibrary(swatchLibrary);
    return {
      schema: SWATCH_LIBRARY_SCHEMA,
      groupCount: library.groups.length,
      swatchCount: library.swatches.length,
      globalCount: library.swatches.filter((swatch) => swatch.kind === "global").length,
      selectedSwatchId: library.selected_swatch_id,
      activeGroupId: swatchUiState.groupId,
      applyTarget: swatchUiState.applyTarget,
      linkedObjectCount: allCanvasObjectsDeep().filter((object) => swatchIdsForObject(object).size).length,
      groups: library.groups.map((group) => ({ ...group })),
      swatches: library.swatches.map((swatch) => ({ ...swatch })),
      recolor: getRecolorSelectionStateForQa(),
      nativePdfStreamMutated: false,
      nativeEquivalent: false
    };
  }

  function createSwatchScenarioForQa() {
    canvas.discardActiveObject();
    canvas.getObjects().forEach((object) => canvas.remove(object));
    swatchLibrary = normalizeSwatchLibrary(defaultSwatchLibrary());
    const source = sourceMeta({ sourceId: "qa-swatches", kind: "qa" });
    const rectA = makeRect(190, 165, 150, 112, { fill: "#2a9d8f", stroke: "#26323d", strokeWidth: 3 }, "Global color A", source);
    const rectB = makeRect(390, 165, 150, 112, { fill: "#2a9d8f", stroke: "#26323d", strokeWidth: 3 }, "Global color B", source);
    const text = makeTextbox("Global colors keep scientific figures consistent", 190, 310, 350, 70, { fill: "#2f6fb0", fontSize: 20, fontWeight: "600" }, "Swatch text", source, "text");
    const arrow = makeArrow(210, 420, 300, 0, { stroke: "#d1495b", strokeWidth: 6, arrowEnd: "triangle", arrowEndFill: "#d1495b" }, "Swatch arrow", source);
    const gradient = makeEllipse(620, 175, 190, 145, { fill: "#f4a261", stroke: "#7b61a8", strokeWidth: 3 }, "Gradient swatches", source);
    const importedChildA = makeRect(-62, -42, 90, 84, { fill: "#67c587", stroke: "#26323d", strokeWidth: 2 }, "Imported SVG part A", source);
    const importedChildB = makeEllipse(18, -42, 90, 84, { fill: "#f7c948", stroke: "#26323d", strokeWidth: 2 }, "Imported SVG part B", source);
    const imported = new fabricRef.Group([importedChildA, importedChildB], { left: 650, top: 385, subTargetCheck: true, interactive: true });
    imported.set({
      figureId: makeId("qa-imported-svg"), figureType: "group", name: "Imported editable SVG colors", source,
      importMeta: { importMode: "svg-vector-group", import_mode: "svg-vector-group", editable: true }
    });
    [rectA, rectB, text, arrow, gradient, imported].forEach((object) => { applyLock(object, false); canvas.add(object); });
    const teal = findSwatch("global-teal");
    const blue = findSwatch("global-blue");
    const red = findSwatch("global-red");
    applySwatchToObject(rectA, teal, "fill");
    applySwatchToObject(rectB, teal, "fill");
    applySwatchToObject(text, blue, "text");
    applySwatchToObject(arrow, red, "stroke");
    applySwatchToObject(arrow, red, "arrow-end");
    const gradientMeta = normalizeAppearanceStackMeta({
      schema: APPEARANCE_STACK_SCHEMA,
      active_item_id: "qa-gradient-fill",
      items: [
        { id: "qa-gradient-stroke", type: "stroke", color: "#7b61a8", swatchId: "global-purple", width: 3 },
        { id: "qa-gradient-fill", type: "fill", paintKind: "linear-gradient", color: "#2a9d8f", gradient: { stops: [
          { id: "qa-stop-1", offset: 0, color: "#2a9d8f", swatchId: "global-teal" },
          { id: "qa-stop-2", offset: 0.52, color: "#f4a261", swatchId: "global-orange" },
          { id: "qa-stop-3", offset: 1, color: "#7b61a8", swatchId: "global-purple" }
        ], angle: 18 } }
      ]
    });
    syncAppearanceStackPrimaryPaint(gradient, gradientMeta);
    canvas.setActiveObject(rectA);
    canvas.requestRenderAll();
    renderSwatchesPanel();
    syncUi();
    commitHistory("Swatches QA scenario created");
    return {
      status: "ok",
      objectIds: [rectA, rectB, text, arrow, gradient, imported].map((object) => object.figureId || ""),
      rectAId: rectA.figureId,
      rectBId: rectB.figureId,
      textId: text.figureId,
      arrowId: arrow.figureId,
      gradientId: gradient.figureId,
      gradientItemId: "qa-gradient-fill",
      importedId: imported.figureId,
      globalSwatchId: teal.id
    };
  }

  function defaultGraphicStyles() {
    const definitions = [
      {
        id: GRAPHIC_STYLE_BUILTIN_IDS[0],
        name: "Journal outline",
        items: [
          { id: "journal-stroke", type: "stroke", color: "#26323d", width: 1.5 },
          { id: "journal-fill", type: "fill", color: "#ffffff" }
        ]
      },
      {
        id: GRAPHIC_STYLE_BUILTIN_IDS[1],
        name: "Signal gradient",
        items: [
          { id: "signal-stroke", type: "stroke", color: "#176b73", width: 1.25 },
          {
            id: "signal-fill",
            type: "fill",
            paintKind: "linear-gradient",
            color: "#38b2a4",
            gradient: { stops: [{ offset: 0, color: "#38b2a4" }, { offset: 1, color: "#f29e62" }], angle: 28 }
          }
        ]
      },
      {
        id: GRAPHIC_STYLE_BUILTIN_IDS[2],
        name: "Crosshatch note",
        items: [
          { id: "crosshatch-stroke", type: "stroke", color: "#24445b", width: 1.25 },
          {
            id: "crosshatch-fill",
            type: "fill",
            paintKind: "pattern",
            color: "#24445b",
            pattern: { preset: "crosshatch", foreground: "#24445b", background: "#e8f3f1", scale: 14, lineWidth: 1.25 }
          }
        ]
      }
    ];
    return definitions.map((style) => normalizeGraphicStyle({ ...style, builtIn: true }));
  }

  function normalizeGraphicStyle(style, index = 0) {
    if (!style || !Array.isArray(style.items) || !style.items.length) return null;
    const builtIn = style.builtIn === true || GRAPHIC_STYLE_BUILTIN_IDS.includes(style.id);
    const id = String(style.id || `graphic-style-${slugify(style.name || "custom") || "custom"}-${index + 1}`);
    const items = style.items.slice(0, APPEARANCE_STACK_MAX_ITEMS).map((item, itemIndex) => normalizeAppearancePaintItem(item, itemIndex));
    const strokeStyle = style.strokeStyle && typeof style.strokeStyle === "object"
      ? {
          width: clamp(Number(style.strokeStyle.width) || 1, 0.5, 48),
          profile: normalizeStrokeWidthProfile(style.strokeStyle.profile, style.strokeStyle.profile?.preset || "uniform"),
          brushId: String(style.strokeStyle.brushId || style.strokeStyle.brush_id || ""),
          lineCap: normalizeStrokeLineCap(style.strokeStyle.lineCap || "round"),
          lineJoin: normalizeStrokeLineJoin(style.strokeStyle.lineJoin || "round"),
          lineDash: "solid"
        }
      : null;
    return {
      schema: GRAPHIC_STYLE_SCHEMA,
      id,
      name: String(style.name || `Graphic style ${index + 1}`).trim().slice(0, 80) || `Graphic style ${index + 1}`,
      items,
      strokeStyle,
      builtIn,
      createdAt: style.createdAt || "",
      updatedAt: style.updatedAt || style.createdAt || "",
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function normalizeGraphicStyleLibrary(styles, options = {}) {
    const includeDefaults = options.includeDefaults !== false;
    const source = Array.isArray(styles)
      ? styles
      : styles?.schema === GRAPHIC_STYLE_LIBRARY_SCHEMA && Array.isArray(styles.styles)
        ? styles.styles
        : [];
    const defaults = includeDefaults ? defaultGraphicStyles() : [];
    const defaultIds = new Set(defaults.map((style) => style.id));
    const seen = new Set(defaultIds);
    const custom = source.map(normalizeGraphicStyle).filter((style) => {
      if (!style || defaultIds.has(style.id) || seen.has(style.id)) return false;
      seen.add(style.id);
      style.builtIn = false;
      return true;
    });
    return [...defaults, ...custom];
  }

  function serializeGraphicStyleLibrary() {
    return {
      schema: GRAPHIC_STYLE_LIBRARY_SCHEMA,
      styles: compactPatternReferencesInValue(graphicStyleLibrary
        .filter((style) => !style.builtIn)
        .map((style) => normalizeGraphicStyle(style))
        .filter(Boolean)),
      last_style_id: lastGraphicStyleId || "",
      native_pdf_stream_mutated: false,
      native_equivalence: false
    };
  }

  function findGraphicStyle(styleId) {
    return graphicStyleLibrary.find((style) => style.id === styleId) || null;
  }

  function graphicStyleSelectionTargets(selection = selectedTopLevelObjects()) {
    const selected = Array.isArray(selection) ? selection : [];
    const eligible = selected.filter(canUseAppearanceStack);
    return {
      selected,
      eligible,
      skipped: selected.filter((object) => !eligible.includes(object))
    };
  }

  function graphicStyleItemsForObject(object) {
    const state = appearanceStackStateForObject(object);
    return state.items.map((item, index) => normalizeAppearancePaintItem({
      ...cloneManifestValue(item, {}),
      id: `style-item-${index + 1}`
    }, index));
  }

  function saveGraphicStyleFromSelection(name, options = {}) {
    const selection = selectedTopLevelObjects();
    if (selection.length !== 1 || !canUseAppearanceStack(selection[0])) {
      const result = { status: "unavailable", selectedCount: selection.length, eligibleCount: graphicStyleSelectionTargets(selection).eligible.length };
      if (options.toast !== false) showToast("Select one ordinary editable vector to save a Graphic Style");
      return result;
    }
    const items = graphicStyleItemsForObject(selection[0]);
    if (!items.length) {
      if (options.toast !== false) showToast("The selected vector has no fill or stroke to save");
      return { status: "empty", selectedCount: 1, eligibleCount: 1 };
    }
    const requestedName = String(name || "").trim();
    const styleName = (requestedName || `Graphic style ${graphicStyleLibrary.filter((style) => !style.builtIn).length + 1}`).slice(0, 80);
    const timestamp = new Date().toISOString();
    const style = normalizeGraphicStyle({
      id: `graphic-style-${slugify(styleName) || "custom"}-${Date.now().toString(36)}`,
      name: styleName,
      items,
      strokeStyle: canUseVariableStroke(selection[0]) ? {
        width: readStyle(selection[0]).strokeWidth,
        profile: strokeWidthProfileForObject(selection[0]),
        brushId: readStyle(selection[0]).strokeBrushId,
        lineCap: readStyle(selection[0]).strokeLineCap,
        lineJoin: readStyle(selection[0]).strokeLineJoin,
        lineDash: "solid"
      } : null,
      createdAt: timestamp,
      updatedAt: timestamp,
      builtIn: false
    });
    graphicStyleLibrary.push(style);
    lastGraphicStyleId = style.id;
    renderMyAssetsDialogList();
    syncUi();
    commitHistory("Graphic Style saved");
    if (options.toast !== false) showToast(`Saved Graphic Style: ${style.name}`);
    return { status: "ok", styleId: style.id, name: style.name, itemCount: style.items.length, sourceObjectId: selection[0].figureId || "" };
  }

  function graphicStyleAppliedItems(style, object, mode) {
    const styleItems = style.items.map((item, index) => normalizeAppearancePaintItem({
      ...cloneManifestValue(item, {}),
      id: `graphic-${style.id}-${object.figureId || "object"}-${index + 1}`
    }, index));
    if (mode !== "merge") return { items: styleItems, clippedCount: 0 };
    const current = appearanceStackStateForObject(object).items.map((item, index) => normalizeAppearancePaintItem({
      ...cloneManifestValue(item, {}),
      id: `current-${object.figureId || "object"}-${index + 1}`
    }, index));
    const merged = [...styleItems, ...current];
    return {
      items: merged.slice(0, APPEARANCE_STACK_MAX_ITEMS),
      clippedCount: Math.max(0, merged.length - APPEARANCE_STACK_MAX_ITEMS)
    };
  }

  function applyGraphicStyle(styleId, mode = "replace", options = {}) {
    const style = findGraphicStyle(styleId);
    if (!style) return { status: "missing", styleId };
    const normalizedMode = mode === "merge" ? "merge" : "replace";
    const targets = graphicStyleSelectionTargets(options.selection || selectedTopLevelObjects());
    if (!targets.eligible.length) {
      if (options.toast !== false) showToast("Graphic Styles apply to ordinary editable vectors");
      return { status: "unavailable", styleId, mode: normalizedMode, selectedCount: targets.selected.length, appliedCount: 0, skippedCount: targets.skipped.length };
    }
    let clippedCount = 0;
    targets.eligible.forEach((object) => {
      const applied = graphicStyleAppliedItems(style, object, normalizedMode);
      clippedCount += applied.clippedCount;
      const meta = normalizeAppearanceStackMeta({
        schema: APPEARANCE_STACK_SCHEMA,
        items: applied.items,
        active_item_id: applied.items[0]?.id || "",
        source_object_caching: object.objectCaching !== false
      });
      syncAppearanceStackPrimaryPaint(object, meta);
      if (style.strokeStyle && canUseVariableStroke(object)) {
        applyStylePatch(object, {
          strokeWidth: style.strokeStyle.width,
          strokeProfile: "custom",
          strokeBrushId: style.strokeStyle.brushId,
          strokeWidthProfile: style.strokeStyle.profile,
          strokeLineCap: style.strokeStyle.lineCap,
          strokeLineJoin: style.strokeStyle.lineJoin,
          lineDash: "solid"
        });
      }
    });
    lastGraphicStyleId = style.id;
    canvas.requestRenderAll();
    syncUi();
    renderMyAssetsDialogList();
    if (options.history !== false) commitHistory(`Graphic Style ${normalizedMode === "merge" ? "merged" : "applied"}`);
    const result = {
      status: targets.skipped.length ? "partial" : "ok",
      styleId: style.id,
      name: style.name,
      mode: normalizedMode,
      selectedCount: targets.selected.length,
      appliedCount: targets.eligible.length,
      skippedCount: targets.skipped.length,
      skippedObjectIds: targets.skipped.map((object) => object.figureId || ""),
      clippedCount,
      nativePdfStreamMutated: false,
      nativeEquivalent: false
    };
    if (options.toast !== false) {
      const skipped = result.skippedCount ? `; ${result.skippedCount} source-backed or unsupported skipped` : "";
      const clipped = clippedCount ? `; ${clippedCount} back paint${clippedCount === 1 ? "" : "s"} omitted` : "";
      showToast(`${style.name} ${normalizedMode === "merge" ? "merged into" : "applied to"} ${result.appliedCount} object${result.appliedCount === 1 ? "" : "s"}${skipped}${clipped}`);
    }
    return result;
  }

  function renameGraphicStyle(styleId, proposedName, options = {}) {
    const style = findGraphicStyle(styleId);
    if (!style || style.builtIn) return { status: style ? "built-in" : "missing", styleId };
    const name = String(proposedName || "").trim().slice(0, 80);
    if (!name) return { status: "invalid", styleId };
    style.name = name;
    style.updatedAt = new Date().toISOString();
    renderMyAssetsDialogList();
    syncUi();
    if (options.history !== false) commitHistory("Graphic Style renamed");
    announceGraphicStyles(`Renamed style to ${name}.`);
    return { status: "ok", styleId, name };
  }

  function deleteGraphicStyle(styleId, options = {}) {
    const index = graphicStyleLibrary.findIndex((style) => style.id === styleId && !style.builtIn);
    if (index < 0) return { status: findGraphicStyle(styleId) ? "built-in" : "missing", styleId };
    const [style] = graphicStyleLibrary.splice(index, 1);
    if (lastGraphicStyleId === styleId) lastGraphicStyleId = graphicStyleLibrary[0]?.id || "";
    renderMyAssetsDialogList();
    syncUi();
    if (options.history !== false) commitHistory("Graphic Style deleted");
    announceGraphicStyles(`Deleted ${style.name}.`);
    return { status: "ok", styleId, remaining: graphicStyleLibrary.length };
  }

  function getGraphicStyleStateForQa() {
    const targets = graphicStyleSelectionTargets();
    return {
      schema: GRAPHIC_STYLE_LIBRARY_SCHEMA,
      styleCount: graphicStyleLibrary.length,
      customStyleCount: graphicStyleLibrary.filter((style) => !style.builtIn).length,
      lastStyleId: lastGraphicStyleId,
      selectedCount: targets.selected.length,
      eligibleCount: targets.eligible.length,
      skippedCount: targets.skipped.length,
      styles: graphicStyleLibrary.map((style) => ({
        id: style.id,
        name: style.name,
        builtIn: style.builtIn,
        itemCount: style.items.length,
        paintKinds: style.items.map((item) => item.paintKind || item.effectKind || item.type)
      })),
      nativePdfStreamMutated: false,
      nativeEquivalent: false
    };
  }

  function baseAppearanceStackItems(object) {
    const style = readStyle(object);
    const items = [];
    if (appearancePaintVisible(style.stroke) && Number(style.strokeWidth || 0) > 0 && typeof style.stroke === "string") {
      items.push(normalizeAppearancePaintItem({
        id: "base-stroke",
        type: "stroke",
        color: style.stroke,
        width: style.strokeWidth,
        dashArray: style.strokeDashArray,
        lineCap: style.strokeLineCap,
        lineJoin: style.strokeLineJoin,
        miterLimit: style.strokeMiterLimit
      }, items.length));
    }
    if (appearancePaintVisible(style.fill) && typeof style.fill === "string") {
      items.push(normalizeAppearancePaintItem({ id: "base-fill", type: "fill", color: style.fill }, items.length));
    }
    return items;
  }

  function canUseAppearanceStack(object) {
    if (!object || object.locked || isReferenceObject(object) || isGroupObject(object) || supportsText(object)) return false;
    if (["line", "arrow", "image", "callout"].includes(String(object.figureType || ""))) return false;
    if (isDenseSvgProxyObject(object) || isProxyBackedPanel(object) || pdfSourceIdForObject(object) || object.nativePdfSourceObjectId) return false;
    const type = String(object.type || "").toLowerCase();
    if (!["rect", "ellipse", "circle", "triangle", "path", "polygon", "polyline"].includes(type)) return false;
    const style = readStyle(object);
    return (!style.fill || typeof style.fill === "string") && (!style.stroke || typeof style.stroke === "string");
  }

  function appearanceStackStateForObject(object) {
    const authored = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
    const editable = canUseAppearanceStack(object);
    const items = authored?.items || (editable ? baseAppearanceStackItems(object) : []);
    const visibleItems = items.filter((item) => item.visible && item.opacity > 0);
    const nonExpandable = visibleItems.filter((item) => (
      item.type === "effect" ? item.expandable !== true : item.paintKind === "pattern"
    ));
    return {
      schema: APPEARANCE_STACK_SCHEMA,
      available: Boolean(authored || editable),
      editable,
      authored: Boolean(authored),
      order: "front-to-back",
      activeItemId: authored?.active_item_id || items[0]?.id || "",
      itemCount: items.length,
      paintCount: items.filter((item) => item.type !== "effect").length,
      effectCount: items.filter((item) => item.type === "effect").length,
      maxItems: APPEARANCE_STACK_MAX_ITEMS,
      items: items.map((item, index) => ({
        ...item,
        position: index,
        frontmost: index === 0,
        backmost: index === items.length - 1
      })),
      expandable: Boolean(authored && visibleItems.length && nonExpandable.length === 0),
      expandReason: !authored
        ? "Add an appearance paint or effect first."
        : nonExpandable.some((item) => item.type === "effect")
          ? "Soft shadows stay live because their blur is not ordinary path geometry."
          : nonExpandable.some((item) => item.paintKind === "pattern")
            ? "Pattern tiles stay live until vector tile expansion is available."
            : "",
      nativePdfStreamMutated: false,
      nativeEquivalent: false
    };
  }

  function appearanceStackRenderItems(object) {
    const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
    return meta?.items.filter((item) => item.visible && item.opacity > 0 && (item.type !== "stroke" || item.width > 0)) || [];
  }

  function appearancePaintProperties(object) {
    return {
      fill: object.fill,
      stroke: object.stroke,
      strokeWidth: object.strokeWidth,
      strokeDashArray: object.strokeDashArray,
      strokeDashOffset: object.strokeDashOffset,
      strokeLineCap: object.strokeLineCap,
      strokeLineJoin: object.strokeLineJoin,
      strokeMiterLimit: object.strokeMiterLimit,
      globalCompositeOperation: object.globalCompositeOperation
    };
  }

  const appearancePatternCache = new Map();

  function vectorPatternSourceSvg(patternValue) {
    const pattern = resolveAppearancePattern(patternValue);
    const bounds = pattern.sourceBounds;
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${fmt(bounds.left, 3)} ${fmt(bounds.top, 3)} ${fmt(bounds.width, 3)} ${fmt(bounds.height, 3)}"><rect x="${fmt(bounds.left, 3)}" y="${fmt(bounds.top, 3)}" width="${fmt(bounds.width, 3)}" height="${fmt(bounds.height, 3)}" fill="${escapeHtml(pattern.background)}"/>${pattern.tileMarkup}</svg>`;
  }

  function appearanceGradientResource(item) {
    if (!fabricRef?.Gradient) return appearancePaintPrimaryColor(item);
    const stops = appearanceGradientRenderStops(item?.gradient?.stops, appearancePaintPrimaryColor(item), appearancePaintSecondaryColor(item));
    if (item.paintKind === "radial-gradient") {
      return new fabricRef.Gradient({
        type: "radial",
        gradientUnits: "percentage",
        coords: {
          x1: item.gradient.centerX,
          y1: item.gradient.centerY,
          r1: 0,
          x2: item.gradient.centerX,
          y2: item.gradient.centerY,
          r2: item.gradient.radius
        },
        colorStops: stops
      });
    }
    return new fabricRef.Gradient({
      type: "linear",
      gradientUnits: "percentage",
      coords: {
        x1: Number(item.gradient?.x1 ?? 0),
        y1: Number(item.gradient?.y1 ?? 0.5),
        x2: Number(item.gradient?.x2 ?? 1),
        y2: Number(item.gradient?.y2 ?? 0.5)
      },
      colorStops: stops
    });
  }

  function appearancePatternTile(item) {
    const pattern = resolveAppearancePattern(item?.pattern, appearancePaintPrimaryColor(item), appearancePaintSecondaryColor(item));
    const key = JSON.stringify(pattern);
    if (appearancePatternCache.has(key)) return appearancePatternCache.get(key);
    const vector = pattern.kind === "vector" && pattern.tileMarkup;
    const size = vector ? Math.max(4, Math.min(512, Math.round(pattern.tileWidth + pattern.spacingX))) : Math.max(6, Math.round(pattern.scale));
    const height = vector ? Math.max(4, Math.min(512, Math.round(pattern.tileHeight + pattern.spacingY))) : size;
    const tile = document.createElement("canvas");
    tile.width = size;
    tile.height = height;
    const context = tile.getContext("2d");
    context.fillStyle = pattern.background;
    context.fillRect(0, 0, size, height);
    if (vector) {
      const image = new Image();
      image.onload = () => {
        context.clearRect(0, 0, size, height);
        context.fillStyle = pattern.background;
        context.fillRect(0, 0, size, height);
        context.save();
        if (pattern.angle) {
          context.translate(pattern.tileWidth / 2, pattern.tileHeight / 2);
          context.rotate(pattern.angle * Math.PI / 180);
          context.translate(-pattern.tileWidth / 2, -pattern.tileHeight / 2);
        }
        context.drawImage(image, 0, 0, pattern.tileWidth, pattern.tileHeight);
        context.restore();
        canvas?.requestRenderAll?.();
      };
      image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(vectorPatternSourceSvg(pattern))}`;
      appearancePatternCache.set(key, tile);
      return tile;
    }
    context.strokeStyle = pattern.foreground;
    context.fillStyle = pattern.foreground;
    context.lineWidth = pattern.lineWidth;
    context.lineCap = "round";
    if (pattern.preset === "dots") {
      context.beginPath();
      context.arc(size / 2, size / 2, Math.max(1, pattern.lineWidth * 1.35), 0, Math.PI * 2);
      context.fill();
    } else {
      const diagonal = () => {
        context.beginPath();
        context.moveTo(-size * 0.2, size * 0.8);
        context.lineTo(size * 0.8, -size * 0.2);
        context.moveTo(size * 0.2, size * 1.2);
        context.lineTo(size * 1.2, size * 0.2);
        context.stroke();
      };
      diagonal();
      if (pattern.preset === "crosshatch") {
        context.save();
        context.translate(size, 0);
        context.scale(-1, 1);
        diagonal();
        context.restore();
      }
    }
    appearancePatternCache.set(key, tile);
    return tile;
  }

  function appearancePaintResource(item) {
    if (item.paintKind === "linear-gradient" || item.paintKind === "radial-gradient") return appearanceGradientResource(item);
    if (item.paintKind === "pattern" && fabricRef?.Pattern) {
      const pattern = resolveAppearancePattern(item.pattern, appearancePaintPrimaryColor(item), appearancePaintSecondaryColor(item));
      return new fabricRef.Pattern({ source: appearancePatternTile(item), repeat: "repeat", offsetX: pattern.offsetX, offsetY: pattern.offsetY });
    }
    return appearancePaintPrimaryColor(item);
  }

  function applyAppearancePaintProperties(object, item, options = {}) {
    const paint = options.svgFallback ? appearancePaintPrimaryColor(item) : appearancePaintResource(item);
    object.globalCompositeOperation = appearanceBlendModeToCanvas(item.blendMode);
    if (item.type === "effect") {
      object.fill = appearancePaintPrimaryColor(item);
      object.stroke = appearancePaintPrimaryColor(item);
      object.strokeWidth = Math.max(0.75, Number(object.styleMeta?.strokeWidth || object.strokeWidth || 0));
      object.strokeDashArray = null;
      return;
    }
    if (item.type === "fill") {
      object.fill = paint;
      object.stroke = null;
      object.strokeWidth = 0;
      return;
    }
    object.fill = null;
    object.stroke = paint;
    object.strokeWidth = Number(item.width || 0);
    object.strokeDashArray = item.dashArray?.length ? [...item.dashArray] : null;
    object.strokeDashOffset = 0;
    object.strokeLineCap = item.lineCap || "round";
    object.strokeLineJoin = item.lineJoin || "round";
    object.strokeMiterLimit = Number(item.miterLimit || 10);
  }

  function restoreAppearancePaintProperties(object, saved) {
    Object.assign(object, saved);
  }

  function ensureAppearanceStack(object) {
    const existing = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
    if (existing) return existing;
    if (!canUseAppearanceStack(object)) return null;
    const items = baseAppearanceStackItems(object);
    return normalizeAppearanceStackMeta({
      schema: APPEARANCE_STACK_SCHEMA,
      items,
      active_item_id: items[0]?.id || "",
      source_object_caching: object.objectCaching !== false
    });
  }

  function syncAppearanceStackPrimaryPaint(object, meta) {
    const normalized = normalizeAppearanceStackMeta(meta);
    if (!object || !normalized) return;
    const fill = normalized.items.find((item) => item.type === "fill" && item.visible && item.opacity > 0);
    const stroke = normalized.items.find((item) => item.type === "stroke" && item.visible && item.opacity > 0 && item.width > 0);
    const current = readStyle(object);
    object.styleMeta = {
      ...current,
      fill: fill ? appearancePaintPrimaryColor(fill) : "",
      stroke: stroke ? appearancePaintPrimaryColor(stroke) : "",
      strokeWidth: Number(stroke?.width || 0),
      strokeDashArray: stroke?.dashArray?.length ? [...stroke.dashArray] : null,
      strokeLineCap: stroke?.lineCap || current.strokeLineCap || "round",
      strokeLineJoin: stroke?.lineJoin || current.strokeLineJoin || "round",
      strokeMiterLimit: Number(stroke?.miterLimit || current.strokeMiterLimit || 10)
    };
    object.set({
      figureStudioAppearanceStack: normalized,
      fill: object.styleMeta.fill,
      stroke: object.styleMeta.stroke,
      strokeWidth: object.styleMeta.strokeWidth,
      strokeDashArray: object.styleMeta.strokeDashArray,
      strokeLineCap: object.styleMeta.strokeLineCap,
      strokeLineJoin: object.styleMeta.strokeLineJoin,
      strokeMiterLimit: object.styleMeta.strokeMiterLimit,
      objectCaching: false,
      dirty: true
    });
    refreshObjectHierarchy(object);
  }

  function mutateAppearanceStack(object, historyLabel, mutator) {
    const meta = ensureAppearanceStack(object);
    if (!object || !meta || !canUseAppearanceStack(object)) return { status: "unavailable", ...appearanceStackStateForObject(object) };
    mutator(meta);
    const normalized = normalizeAppearanceStackMeta(meta);
    syncAppearanceStackPrimaryPaint(object, normalized);
    canvas.requestRenderAll();
    syncUi();
      if (historyLabel) commitHistory(historyLabel);
    return { status: "ok", objectId: object.figureId || "", ...appearanceStackStateForObject(object) };
  }

  function addAppearancePaint(object, type = "fill", options = {}) {
    const paintType = type === "stroke" ? "stroke" : "fill";
    const current = appearanceStackStateForObject(object);
    if (current.itemCount >= APPEARANCE_STACK_MAX_ITEMS) {
      return { status: "limit", limit: APPEARANCE_STACK_MAX_ITEMS, ...current };
    }
    return mutateAppearanceStack(object, options.historyLabel || `${paintType === "fill" ? "Fill" : "Stroke"} added`, (meta) => {
      const source = meta.items.find((item) => item.type === paintType);
      const item = normalizeAppearancePaintItem({
        ...(source || {}),
        id: makeId(`paint-${paintType}`),
        type: paintType,
        paintKind: options.paintKind || source?.paintKind || "solid",
        color: options.color || source?.color || (paintType === "stroke" ? "#26323d" : "#5eead4"),
        opacity: options.opacity ?? (paintType === "fill" ? 0.65 : 1),
        width: options.width ?? source?.width ?? 6,
        blendMode: options.blendMode || source?.blendMode || "normal",
        gradient: options.gradient || source?.gradient,
        pattern: options.pattern || source?.pattern,
        visible: true
      });
      meta.items.unshift(item);
      meta.active_item_id = item.id;
    });
  }

  function updateAppearancePaint(object, itemId, patch = {}, options = {}) {
    return mutateAppearanceStack(object, options.historyLabel || "Appearance paint updated", (meta) => {
      const index = meta.items.findIndex((item) => item.id === itemId);
      if (index < 0) return;
      const current = meta.items[index];
      meta.items[index] = normalizeAppearancePaintItem({
        ...current,
        ...patch,
        gradient: patch.gradient ? {
          ...(current.gradient || {}),
          ...patch.gradient,
          stops: patch.gradient.stops || current.gradient?.stops
        } : current.gradient,
        pattern: patch.pattern ? { ...(current.pattern || {}), ...patch.pattern } : current.pattern
      }, index);
      meta.active_item_id = meta.items[index].id;
    });
  }

  function reorderAppearancePaint(object, itemId, direction, options = {}) {
    return mutateAppearanceStack(object, options.historyLabel || "Appearance paint reordered", (meta) => {
      const index = meta.items.findIndex((item) => item.id === itemId);
      const next = clamp(index + (Number(direction) < 0 ? -1 : 1), 0, meta.items.length - 1);
      if (index < 0 || next === index) return;
      const [item] = meta.items.splice(index, 1);
      meta.items.splice(next, 0, item);
      meta.active_item_id = item.id;
    });
  }

  function duplicateAppearancePaint(object, itemId, options = {}) {
    return mutateAppearanceStack(object, options.historyLabel || "Appearance paint duplicated", (meta) => {
      if (meta.items.length >= APPEARANCE_STACK_MAX_ITEMS) return;
      const index = meta.items.findIndex((item) => item.id === itemId);
      if (index < 0) return;
      const copy = { ...meta.items[index], id: makeId(`paint-${meta.items[index].type}`) };
      meta.items.splice(index, 0, copy);
      meta.active_item_id = copy.id;
    });
  }

  function removeAppearancePaint(object, itemId, options = {}) {
    return mutateAppearanceStack(object, options.historyLabel || "Appearance paint removed", (meta) => {
      const index = meta.items.findIndex((item) => item.id === itemId);
      if (index < 0) return;
      meta.items.splice(index, 1);
      meta.active_item_id = meta.items[Math.min(index, meta.items.length - 1)]?.id || "";
    });
  }

  function addAppearanceEffect(object, effectKind = "offset-copy", options = {}) {
    const kind = APPEARANCE_EFFECT_KINDS.includes(effectKind) ? effectKind : "offset-copy";
    const current = appearanceStackStateForObject(object);
    if (current.itemCount >= APPEARANCE_STACK_MAX_ITEMS) {
      return { status: "limit", limit: APPEARANCE_STACK_MAX_ITEMS, ...current };
    }
    return mutateAppearanceStack(object, options.historyLabel || `${kind === "soft-shadow" ? "Soft shadow" : "Offset copy"} added`, (meta) => {
      const item = normalizeAppearancePaintItem({
        id: makeId("appearance-effect"),
        type: "effect",
        effectKind: kind,
        color: options.color || (kind === "soft-shadow" ? "#26323d" : "#f4a261"),
        opacity: options.opacity ?? (kind === "soft-shadow" ? 0.36 : 0.7),
        blendMode: options.blendMode || (kind === "soft-shadow" ? "multiply" : "normal"),
        offsetX: options.offsetX ?? (kind === "soft-shadow" ? 8 : 12),
        offsetY: options.offsetY ?? (kind === "soft-shadow" ? 8 : 12),
        blur: options.blur ?? 10,
        visible: true
      });
      meta.items.unshift(item);
      meta.active_item_id = item.id;
    });
  }

  function clearAppearanceStack(object, options = {}) {
    const meta = normalizeAppearanceStackMeta(object?.figureStudioAppearanceStack);
    if (!object || !meta || object.locked) return { status: "unavailable", ...appearanceStackStateForObject(object) };
    const fill = meta.items.find((item) => item.type === "fill" && item.visible && item.opacity > 0);
    const stroke = meta.items.find((item) => item.type === "stroke" && item.visible && item.opacity > 0 && item.width > 0);
    delete object.figureStudioAppearanceStack;
    object.set({ objectCaching: meta.source_object_caching !== false, dirty: true });
    applyStylePatch(object, {
      fill: fill ? appearancePaintPrimaryColor(fill) : "",
      stroke: stroke ? appearancePaintPrimaryColor(stroke) : "",
      strokeWidth: Number(stroke?.width || 0),
      strokeDashArray: stroke?.dashArray?.length ? [...stroke.dashArray] : null
    });
    canvas.requestRenderAll();
    syncUi();
    if (options.historyLabel !== "") commitHistory(options.historyLabel || "Appearance reduced to base paint");
    return { status: "ok", objectId: object.figureId || "", ...appearanceStackStateForObject(object) };
  }

  function expandedAppearanceOffset(item, object) {
    const radians = Number(object?.angle || 0) * Math.PI / 180;
    const x = Number(item?.offsetX || 0) * Number(object?.scaleX || 1);
    const y = Number(item?.offsetY || 0) * Number(object?.scaleY || 1);
    return {
      x: x * Math.cos(radians) - y * Math.sin(radians),
      y: x * Math.sin(radians) + y * Math.cos(radians)
    };
  }

  async function expandAppearance(object = selectedTopLevelObjects()[0], options = {}) {
    const stack = appearanceStackStateForObject(object);
    if (!object || !stack.authored || object.locked) return { status: "unavailable", ...stack };
    if (!stack.expandable) {
      if (options.toast !== false) showLongToast(stack.expandReason || "This appearance must remain live.");
      return { status: "guarded", reason: stack.expandReason || "non-expandable-appearance", ...stack };
    }
    const items = appearanceStackRenderItems(object);
    if (!items.length) return { status: "empty", ...stack };
    const clones = await Promise.all([...items].reverse().map(async (item, index) => {
      const clone = await object.clone(CUSTOM_PROPS);
      delete clone.figureStudioAppearanceStack;
      delete clone.figureStudioExpandedAppearanceMeta;
      applyAppearancePaintProperties(clone, item);
      const primary = appearancePaintPrimaryColor(item);
      const offset = item.type === "effect" ? expandedAppearanceOffset(item, object) : { x: 0, y: 0 };
      clone.set({
        left: Number(clone.left || 0) + offset.x,
        top: Number(clone.top || 0) + offset.y,
        opacity: clamp(Number(object.opacity ?? 1), 0, 1) * clamp(Number(item.opacity ?? 1), 0, 1),
        globalCompositeOperation: appearanceBlendModeToCanvas(item.blendMode),
        figureId: makeId(item.type === "effect" ? "expanded-effect" : `expanded-${item.type}`),
        figureType: object.figureType || object.type || "path",
        name: `${object.name || "Object"} ${item.type === "effect" ? "offset" : item.type} ${index + 1}`,
        objectCaching: false,
        dirty: true
      });
      clone.styleMeta = {
        ...readStyle(object),
        fill: item.type === "stroke" ? "" : primary,
        stroke: item.type === "stroke" ? primary : "",
        strokeWidth: item.type === "stroke" ? Number(item.width || 0) : 0,
        opacity: clone.opacity,
        blendMode: item.blendMode
      };
      clone.source = sourceMeta({ sourceId: object.figureId || "", kind: "expanded-appearance" });
      applyLock(clone, false);
      clone.setCoords?.();
      return clone;
    }));
    if (options.ownershipContext) {
      const ownership = revalidateObjectContextCommandAfterAwait(options.ownershipContext);
      if (ownership.status !== "ok") {
        if (options.toast !== false) showToast(ownership.message);
        return { status: "cancelled", reason: ownership.reason, objectId: object.figureId || "" };
      }
    }
    const parent = object.group || canvas;
    const index = collectionObjects(parent).indexOf(object);
    if (parent === canvas) canvas.remove(object);
    else parent.remove?.(object);
    const group = new fabricRef.Group(clones, { subTargetCheck: false, interactive: false, objectCaching: false });
    group.set({
      figureId: makeId("expanded-appearance"),
      figureType: "group",
      name: `${object.name || "Object"} expanded appearance`,
      source: sourceMeta({ sourceId: object.figureId || "", kind: "expanded-appearance" }),
      styleMeta: readStyle(object),
      figureStudioExpandedAppearanceMeta: {
        schema: "figureStudio.expandedAppearance.v1",
        source_object_id: object.figureId || "",
        item_count: clones.length,
        ordinary_vector_children: true,
        native_pdf_stream_mutated: false,
        native_equivalence: false
      }
    });
    applyLock(group, false);
    insertObjectIntoCollection(parent, group, index < 0 ? collectionObjects(parent).length : index);
    refreshObjectHierarchy(group);
    if (parent === canvas) canvas.setActiveObject(group);
    else selectIsolatedObject(group, { sync: false });
    canvas.requestRenderAll();
    syncUi();
    commitHistory("Appearance expanded");
    if (options.toast !== false) showToast(`Appearance expanded to ${clones.length} vector objects`);
    return { status: "ok", objectId: group.figureId || "", childCount: clones.length, nativeEquivalent: false };
  }

