    const cytoplasm = makeRect(42, 106, 876, 360, { fill: "#f7fbfd", stroke: "#b9c9d4", strokeWidth: 2, rx: 26, ry: 26 }, "Cell cytoplasm", sourceMeta({ sourceId: "organization-fixture", kind: "cell-context" }));
    const membrane = makeRect(42, 212, 876, 26, { fill: "#d8edf4", stroke: "#6d98aa", strokeWidth: 2, rx: 10, ry: 10 }, "Plasma membrane", sourceMeta({ sourceId: "organization-fixture", kind: "membrane" }));
    [cytoplasm, membrane].forEach((object) => object.set({ figureStudioLayerId: contextLayer.id }));
