    activeObjectLayerState().activeLayerId = "layer-mechanism";
    const ligandA = makeRect(0, 0, 38, 24, { fill: "#f6c85f", stroke: "#8a5a10", strokeWidth: 2, rx: 12, ry: 12 }, "EGF ligand A", sourceMeta({ sourceId: "organization-fixture", kind: "ligand" }));
    const ligandB = makeRect(45, 0, 38, 24, { fill: "#f6c85f", stroke: "#8a5a10", strokeWidth: 2, rx: 12, ry: 12 }, "EGF ligand B", sourceMeta({ sourceId: "organization-fixture", kind: "ligand" }));
    const ligands = createOrganizationFixtureGroup([ligandA, ligandB], "EGF ligand dimer", "layer-mechanism");
    ligands.set({ left: 170, top: 116 });

    const receptorLeft = makeRect(0, 0, 34, 150, { fill: "#66b8d5", stroke: "#155e75", strokeWidth: 3, rx: 14, ry: 14 }, "EGFR protomer A", sourceMeta({ sourceId: "organization-fixture", kind: "receptor" }));
    const receptorRight = makeRect(48, 0, 34, 150, { fill: "#66b8d5", stroke: "#155e75", strokeWidth: 3, rx: 14, ry: 14 }, "EGFR protomer B", sourceMeta({ sourceId: "organization-fixture", kind: "receptor" }));
    const phosphoA = makeRect(0, 0, 16, 16, { fill: "#f05d5e", stroke: "#8f1d2c", strokeWidth: 2, rx: 8, ry: 8 }, "pY1068", sourceMeta({ sourceId: "organization-fixture", kind: "phosphosite" }));
    const phosphoB = makeRect(24, 0, 16, 16, { fill: "#f05d5e", stroke: "#8f1d2c", strokeWidth: 2, rx: 8, ry: 8 }, "pY1173", sourceMeta({ sourceId: "organization-fixture", kind: "phosphosite" }));
    const phosphoCluster = createOrganizationFixtureGroup([phosphoA, phosphoB], "Autophosphorylation sites");
    phosphoCluster.set({ left: 20, top: 132 });
