    ensureLayerState();
    [sourceGroup, movableGroup, destinationGroup, semanticOwner, denseRevealRoot, denseRevealAncestor].filter(Boolean).forEach((group) => { state.layers.collapsedGroups[group.figureId] = false; });
    applyObjectLayerStackOrder();
