  async function createLayerObjectPolishScenarioForQa() {
    ensureDeckState();
    await restoreDeckPage(state.deck.activePageId || state.deck.pages[0]?.id, { captureCurrent: false, historyLabel: "" });
    applyFigureTemplate("graphical-abstract", { skipHistory: true, toast: false });
    const objects = canvas.getObjects().filter((object) => isFigureObject(object) && !isReferenceObject(object));
    if (objects.length >= 2) {
      setActiveObjects(objects.slice(0, 2));
      groupSelection();
      const group = selectedTopLevelObjects()[0];
      if (group && isGroupObject(group)) {
        group.name = "QA grouped biology assets";
        if (typeof canvas.bringObjectToFront === "function") canvas.bringObjectToFront(group);
        ensureLayerState();
        state.layers.collapsedGroups[group.figureId] = false;
      }
    }
    canvas.getObjects().filter((object) => isFigureObject(object) && !isReferenceObject(object)).forEach((object, index) => {
      if (!object.name || /^Group \(/.test(object.name)) object.name = index === 0 ? "QA grouped biology assets" : `Layer object ${index}`;
    });
    setInspectorTab("layers");
    syncUi();
    return getLayerStateForQa();
  }

  function createClipMaskInspectionScenarioForQa() {
    const art = artboardPx();
    const clipped = new fabricRef.Rect({
      left: art.width * 0.18,
      top: art.height * 0.22,
      width: art.width * 0.30,
      height: art.height * 0.22,
      fill: "#dff6ff",
      stroke: "#155e75",
      strokeWidth: 3,
      rx: 10,
      ry: 10,
      objectCaching: false
    });
    const clip = new fabricRef.Circle({
      left: art.width * 0.23,
      top: art.height * 0.21,
      radius: Math.min(art.width, art.height) * 0.095,
      originX: "left",
      originY: "top",
      absolutePositioned: true,
      objectCaching: false
    });
    baseMeta(clipped, "rect", "Parsed SVG clip-path object", sourceMeta({
      sourceId: "clip-mask-fixture.svg",
      filename: "clip-mask-fixture.svg",
      kind: "svg-clip-path-fixture",
      notes: "QA fixture with a Fabric clipPath object already represented in the parsed object model."
    }), { fill: "#dff6ff", stroke: "#155e75", strokeWidth: 3, opacity: 1 });
    clipped.set({
      clipPath: clip,
      importMeta: importMeta({
        importMode: SVG_VECTOR_GROUP_IMPORT,
        import_mode: SVG_VECTOR_GROUP_IMPORT,
        vectorPreserving: true,
        advancedFeatureProfile: {
          clip_path_count: 1,
          referenced_clip_path_count: 1,
          mask_count: 0,
          referenced_mask_count: 0,
          filter_count: 0,
          referenced_filter_count: 0,
          blend_mode_element_count: 0
        }
      })
    });
    const descriptors = [
      {
        schema: "figureStudio.advancedSvgNativeProxyDescriptor.v1",
        tag: "rect",
        element_id: "clip-target",
        features: ["clip_path"],
        feature_refs: [{ kind: "clip_path", id: "qaClip" }],
        bounds: { x: 0, y: 0, width: 170, height: 92 },
        source_width: 420,
        source_height: 260
      },
      {
        schema: "figureStudio.advancedSvgNativeProxyDescriptor.v1",
        tag: "circle",
        element_id: "mask-target",
        features: ["mask"],
        feature_refs: [{ kind: "mask", id: "qaMask" }],
        bounds: { x: 190, y: 28, width: 150, height: 110 },
        source_width: 420,
        source_height: 260
      }
    ];
    const proxies = descriptors.map((descriptor, index) => nativeAdvancedFeatureProxyRect(descriptor, index));
    const proxyGroup = new fabricRef.Group(proxies, {
      left: art.width * 0.50,
      top: art.height * 0.28,
      originX: "left",
      originY: "top",
      subTargetCheck: true,
      objectCaching: false
    });
    const proxyMeta = {
      schema: "figureStudio.advancedSvgNativeProxyLayer.v1",
      source_object_id: clipped.figureId || "",
      source_object_name: clipped.name || "",
      proxy_count: proxies.length,
      total_detected_count: proxies.length,
      omitted_count: 0,
      feature_types: ["clip_path", "mask"],
      native_proxy_policy: "editable-native-bounds-for-source-backed-compositing-features",
      full_native_equivalence: false,
      created_at: new Date().toISOString()
    };
    baseMeta(proxyGroup, "svg", "Clip/mask proxy bounds", sourceMeta({
      sourceId: "clip-mask-fixture.svg proxies",
      filename: "clip-mask-fixture.svg",
      kind: "advanced-svg-native-feature-proxy-layer",
      notes: "QA fixture with clip and mask proxy bounds already represented as Fabric objects."
    }), { opacity: 1 });
    proxyGroup.set({
      importMeta: importMeta({
        importMode: "advanced-svg-native-feature-proxy-layer",
        import_mode: "advanced-svg-native-feature-proxy-layer",
        vectorPreserving: true,
        advancedSvgNativeProxyLayer: proxyMeta,
        advanced_svg_native_proxy_layer: proxyMeta,
        fullNativeEquivalence: false,
        full_native_equivalence: false
      }),
      denseSvgAdvancedFeatureProxyMeta: proxyMeta,
      objectCaching: false
    });
    canvas.add(clipped);
    canvas.add(proxyGroup);
    canvas.setActiveObject(proxyGroup);
    setInspectorTab("properties");
    canvas.requestRenderAll();
    syncUi();
    commitHistory("Clip/mask inspection fixture");
    return getClipMaskInspectionStateForQa();
  }

