  function showLayerContextMenuForQa(preferred = {}) {
    setInspectorTab("layers");
    renderLayers();
    const rows = canvas.getObjects().filter((object) => isFigureObject(object) && !isReferenceObject(object)).slice().reverse();
    const target = preferred.id
      ? getByFigureId(preferred.id)
      : rows.find((object) => isGroupObject(object)) || rows[0];
    if (!target) return { shown: false, commands: [] };
    const row = els.layersList?.querySelector(`[data-layer-id="${target.figureId}"]`);
    const rect = row?.getBoundingClientRect?.();
    showLayerContextMenu({
      clientX: rect ? rect.left + Math.min(160, rect.width - 20) : 980,
      clientY: rect ? rect.top + Math.min(36, rect.height / 2) : 240
    }, target.figureId);
    return {
      shown: !els.layerContextMenu?.hidden,
      target: layerObjectSummary(target),
      groups: contextMenuGroupsForQa(els.layerContextMenu),
      commands: Array.from(els.layerContextMenu?.querySelectorAll("[data-layer-context-command]") || []).map((button) => ({
        command: button.dataset.layerContextCommand,
        disabled: Boolean(button.disabled),
        hidden: Boolean(button.hidden || button.closest("[hidden]"))
      }))
    };
  }

  function executeLayerCommandForQa(command, options = {}) {
    const before = getLayerStateForQa();
    const layerId = options.id || before.selectedIds[0] || before.rows[0]?.id || "";
    executeLayerContextCommand(command, { layerId, label: options.label });
    return {
      command,
      before,
      after: getLayerStateForQa()
    };
  }

