            pageNumber: meta.pageNumber || 1,
            pageCount: meta.pageCount || meta.page_count || 1,
            converterName: meta.converterName || meta.converter?.name || "",
            converterLibrary: meta.converterLibrary || meta.converter?.library || "",
            preservationClassification: meta.preservationClassification || "",
            textCount: Number(meta.textCount || 0) || 0,
