      panelName: panel?.name || "",
      panelChildCount: groupChildren(panel).length,
      openedObjectCount: openedObjects.length,
      openedAsDocument: Boolean(sourceObject?.importMeta?.openedAsDocument),
      editingEntry: sourceObject?.importMeta?.editingEntry || "",
      sourcePdfRetained: Boolean(source.available),
      nativeDescriptorTreeRetained: Boolean(nativeTree),
      nativeDescriptorCount: Number(nativeTree?.object_counts?.descriptor_count || 0) || 0,
      nativeDescriptorMaterializationStatus: nativeTree?.materialization?.status || "unavailable",
      nativeDescriptorMaterializationEngine: nativeTree?.materialization?.engine || "",
      nativeMaterializedTextCount: Number(nativeTree?.object_counts?.text_span_count || 0) || 0,
      nativeDeferredNodeCount: Number(nativeTree?.materialization?.deferred_node_count || 0) || 0,
      nativeDeferredNodeKinds: Array.isArray(nativeTree?.materialization?.deferred_node_kinds)
