      dropPoint,
      groupedPanel: true,
      openAsDocument: options?.openAsDocument === true,
      figureType: "pdf",
      originalWidth,
      originalHeight,
      batchPrefix: "pdf-vector",
      namePrefix: options?.namePrefix || `PDF ${file.name} p${pageNumber}`,
      selectionName: options?.selectionName || `PDF vector: ${file.name} page ${pageNumber}`,
      historyLabel: options?.historyLabel ?? "PDF vector objects imported",
