    els.scientificSymbolPopover?.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        closeScientificSymbolPopover({ restoreText: true });
        return;
      }
      const buttons = [...els.scientificSymbolPopover.querySelectorAll("[data-scientific-symbol]")].filter((button) => !button.hidden);
      if (event.target === els.scientificSymbolSearch && event.key === "ArrowDown") {
        event.preventDefault();
        buttons[0]?.focus?.({ preventScroll: true });
        return;
      }
      const currentIndex = buttons.indexOf(event.target.closest?.("[data-scientific-symbol]"));
      if (currentIndex < 0 || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
      event.preventDefault();
      const columns = 7;
      const nextIndex = event.key === "Home" ? 0
        : event.key === "End" ? buttons.length - 1
          : event.key === "ArrowLeft" ? Math.max(0, currentIndex - 1)
            : event.key === "ArrowRight" ? Math.min(buttons.length - 1, currentIndex + 1)
              : event.key === "ArrowUp" ? Math.max(0, currentIndex - columns)
                : Math.min(buttons.length - 1, currentIndex + columns);
      buttons[nextIndex]?.focus?.({ preventScroll: true });
    });
