    els.loadProjectInput.addEventListener("change", async () => {
      const expectedKind = pendingProjectOpenKind;
      pendingProjectOpenKind = "";
      const operation = pendingBrowserOpenOperation;
      pendingBrowserOpenOperation = null;
      const file = els.loadProjectInput.files?.[0] || null;
      try {
        if (!file) {
          const message = "Open cancelled. Your open documents were not changed.";
          finishDocumentFileOperation(operation, "cancelled", message);
          showToast(message);
          return;
        }
        if (!documentFileOperationOwnerIsCurrent(operation)) {
          const message = "Open finished after its original document closed. Your current document was not changed.";
          finishDocumentFileOperation(operation, "cancelled", message);
          showLongToast(message);
          return;
        }
        const tab = await loadProject(file, { expectedKind });
        if (!tab) {
          const message = `Figure Tool could not open ${file.name}.`;
          finishDocumentFileOperation(operation, "failure", message);
          showLongToast(message);
          return;
        }
        const filename = documentTabDisplayName(tab);
        const message = `Opened ${filename} from your browser. Browser access does not expose a native file path.`;
        finishDocumentFileOperation(operation, "success", message, { tab, filename });
        showLongToast(message);
      } finally {
        els.loadProjectInput.value = "";
      }
    });
    els.loadProjectInput.addEventListener("cancel", () => {
      const operation = pendingBrowserOpenOperation;
      if (!operation) return;
      pendingBrowserOpenOperation = null;
      pendingProjectOpenKind = "";
      const message = "Open cancelled. Your open documents were not changed.";
      finishDocumentFileOperation(operation, "cancelled", message);
      showToast(message);
    });
